// Строка результата: сумма + доля от продажи (base). Модульный уровень — см. коммент выше.
export const CalcRow = ({ label, value, base, strong, tone, hint }: any) => {
  const v = Number(value) || 0;
  const pct = Number(base) > 0 ? `${(v / Number(base) * 100).toFixed(1)}%` : '';
  return (
    <div className={`flex justify-between items-baseline gap-2 ${strong ? 'py-1.5 mt-1 border-t font-extrabold text-base' : 'py-0.5'} ${tone || ''}`}>
      <span className={strong ? '' : 'text-slate-600'}>{label}{hint ? <span className="ml-1 text-[10px] text-slate-400">{hint}</span> : null}</span>
      <span className="tabular-nums whitespace-nowrap">
        {v.toLocaleString('ru-RU', { maximumFractionDigits: 2 })} ₽
        {pct ? <span className={`ml-1.5 text-[11px] font-normal ${strong ? 'opacity-70' : 'text-slate-400'}`}>{pct}</span> : null}
      </span>
    </div>
  );
};

const CalcLine = ({ label, value, sign, strong, muted }: any) => (
  <div className={`flex items-center justify-between py-1.5 text-sm ${strong ? 'font-bold text-slate-900' : muted ? 'text-slate-400' : 'text-slate-600'}`}>
    <span>{sign}{label}</span>
    <span className={strong ? '' : 'font-medium text-slate-800'}>{calcMoney(value)} ₽</span>
  </div>
);

/**
 * Разделы со своим сканером: сборка ФБО («Поставки») и поиск ФБС.
 *
 * Свёрнутая плашка «Скан ЧЗ» туда сканер не перехватывает — иначе код ФБО мог
 * бы записаться маркой на задание ФБС. Сканировать в плашку там можно, щёлкнув
 * в её поле.
 */
const FBS_SCAN_OWN_SCANNER_TABS: string[] = ['supplies', 'fbs_search'];

const Tab_suppliers = lazyNamed<any>(() => import('./dashboard/Tab_suppliers'), 'Tab_suppliers', 'dash-Tab_suppliers');
const Tab_supplies = lazyNamed<any>(() => import('./dashboard/Tab_supplies'), 'Tab_supplies', 'dash-Tab_supplies');
const Tab_reception = lazyNamed<any>(() => import('./dashboard/Tab_reception'), 'Tab_reception', 'dash-Tab_reception');
const Tab_map = lazyNamed<any>(() => import('./dashboard/Tab_map'), 'Tab_map', 'dash-Tab_map');
const Tab_barters = lazyNamed<any>(() => import('./dashboard/Tab_barters'), 'Tab_barters', 'dash-Tab_barters');
const Tab_honest_sign = lazyNamed<any>(() => import('./dashboard/Tab_honest_sign'), 'Tab_honest_sign', 'dash-Tab_honest_sign');
const Tab_analytics = lazyNamed<any>(() => import('./dashboard/Tab_analytics'), 'Tab_analytics', 'dash-Tab_analytics');
