  const [generalReportCwRows, setGeneralReportCwRows] = useState<any[]>([]);
  const [tempWorkerForm, setTempWorkerForm] = useState({
    supplier_id: '',
    date: mskTodayYmd(),
    worker_name: '',
    work_comment: '',
    quantity: '',
    earnings: '',
    hours: ''
  });
  // Multi-line "add shift" model: several positions (different workers / goods /
  // prices) added in one go. Each line: worker, type, qty×price OR hours×price.
  const makeTempLine = () => ({ supplier_id: '', worker_name: '', work_comment: '', isTime: false, quantity: '', price: '', hours: '' });
  const [tempWorkerLines, setTempWorkerLines] = useState<any[]>([makeTempLine()]);
  const tempLineEarnings = (l: any) => l.isTime ? (Number(l.hours || 0) * Number(l.price || 0)) : (Number(l.quantity || 0) * Number(l.price || 0));
  const [tempWorkerEditForm, setTempWorkerEditForm] = useState({
    id: '',
    supplier_id: '',
    date: mskTodayYmd(),
    worker_name: '',
    work_comment: '',
    isTime: false,
    quantity: '',
    price: '',
    earnings: '',
    hours: ''
  });
  const tempEditEarnings = (f: any) => f.isTime ? (Number(f.hours || 0) * Number(f.price || 0)) : (Number(f.quantity || 0) * Number(f.price || 0));
  const [tempWorkerPaymentModal, setTempWorkerPaymentModal] = useState<{ open: boolean; logId: string; mode: 'pay' | 'extra' | 'edit'; supplierId: string; amount: string; error?: string }>({ open: false, logId: '', mode: 'pay', supplierId: '', amount: '', error: '' });
  const [tempWorkerQuickPayWorkerFilter, setTempWorkerQuickPayWorkerFilter] = useState('all');
  const [tempWorkerQuickPayPayerSupplierId, setTempWorkerQuickPayPayerSupplierId] = useState('');
  const [tempWorkerQuickPaySelectedIds, setTempWorkerQuickPaySelectedIds] = useState<string[]>([]);
