  const openFboPalletItemQtyEdit = (item: FboPalletItem) => {
    setFboPalletItemQtyEdit({ id: item.id, title: item.title || '', qty: String(Math.max(1, Number(item.qty || 1))) });
  };

  const handleSaveFboPalletItemQtyEdit = async () => {
    const edit = fboPalletItemQtyEdit;
    if (!edit) return;
    const qty = Math.floor(Number(edit.qty));
    if (!Number.isFinite(qty) || qty < 1) {
      showToast('Введите целое число больше 0', 'error');
      return;
    }
    try {
      const snapshot = await loadFboPalletSnapshot();
      await saveFboPalletSnapshot({
        ...snapshot,
        items: snapshot.items.map((it) => String(it.id) === String(edit.id) ? { ...it, qty } : it),
      });
      setFboPalletItemQtyEdit(null);
      await fetchFboPalletData(fboPalletSupplierId);
      logAction('ФБО: изменение количества', `Товар «${edit.title || edit.id}» → ${qty} шт`, currentEmployee?.id);
      showToast('Количество обновлено', 'success');
    } catch (e: any) {
      showToast('Ошибка изменения количества: ' + (e?.message || 'неизвестно'), 'error');
    }
  };

  const handleAddFboPallet = async () => {
    const supplierId = String(fboPalletSupplierId || '').trim();
    if (!supplierId) {
      showToast('Выберите поставщика для паллет', 'error');
      return;
    }
    if (!fboPalletSelectedWarehouseId) {
      showToast('Сначала выберите или создайте склад поставки', 'error');
      return;
    }
    if (!fboPalletSelectedSupplyId) {
      showToast('Сначала выберите или создайте поставку', 'error');
      return;
    }

    try {
      const { session, snapshot } = await getFboPalletActiveSession(supplierId);
      const currentPallets = snapshot.pallets.filter((p) => String(p.session_id) === String(session.id) && String(p.supply_id || '') === String(fboPalletSelectedSupplyId) && !p.deleted_at);
      const used = new Set(currentPallets.map((p) => Number(p.pallet_number)).filter((n) => Number.isFinite(n) && n > 0));
      let nextNumber = 1;
      while (used.has(nextNumber)) nextNumber += 1;

      const pallet: FboPallet = {
        id: createFboPalletId('fbo-pallet'),
        session_id: session.id,
        supplier_id: supplierId,
        warehouse_id: fboPalletSelectedWarehouseId,
        supply_id: fboPalletSelectedSupplyId,
        pallet_number: nextNumber,
        created_at: new Date().toISOString(),
        deleted_at: null,
      };
      await saveFboPalletSnapshot({ ...snapshot, pallets: [...snapshot.pallets, pallet] });
      await fetchFboPalletData(supplierId);
      logAction('ФБО: создание паллеты', `Паллета №${nextNumber} · поставщик ${suppliers.find((s:any)=>String(s.id)===supplierId)?.name || supplierId}`, currentEmployee?.id);
      showToast('Паллета №' + nextNumber + ' добавлена', 'success');
    } catch (e: any) {
      showToast('Ошибка добавления паллеты: ' + (e?.message || 'неизвестно'), 'error');
    }
  };

  const openFboPalletProductPicker = (palletId: string) => {
    setFboPalletSelectedProducts({});
    setFboPalletProductPicker({ open: true, palletId });
  };

  const closeFboPalletProductPicker = () => {
    setFboPalletSelectedProducts({});
    setFboPalletProductPicker({ open: false, palletId: '' });
  };

  const setFboPalletSelectedProductQty = (productKey: string, qty: number) => {
    const cleanQty = Math.max(1, Math.min(999, Math.floor(Number(qty) || 1)));
    setFboPalletSelectedProducts((prev) => ({ ...prev, [productKey]: cleanQty }));
  };

  const toggleFboPalletSelectedProduct = (productKey: string, checked: boolean) => {
    setFboPalletSelectedProducts((prev) => {
      const next = { ...prev };
      if (checked) next[productKey] = next[productKey] || 1;
      else delete next[productKey];
      return next;
    });
  };

  const handleAddSelectedProductsToFboPallet = async () => {
    const palletId = String(fboPalletProductPicker.palletId || '').trim();
    const supplierId = String(fboPalletSupplierId || '').trim();
    if (!palletId || !supplierId) return;

    const selectedProducts = fboPalletProducts.filter((product) => fboPalletSelectedProducts[product.key]);
    if (selectedProducts.length === 0) {
      showToast('Выберите товары для паллеты', 'error');
      return;
    }

    try {
      const barcodes = Array.from(new Set(selectedProducts.map((product) => String(product.barcode || '').trim()).filter(Boolean)));
      const productIdsByBarcode = new Map<string, string>();
      if (barcodes.length > 0) {
        const { data } = await supabase
          .from('products')
          .select('id, barcode')
          .eq('supplier_id', supplierId)
          .in('barcode', barcodes)
          .is('deleted_at', null)
          .limit(1000);
        (data || []).forEach((row: any) => {
          const barcode = String(row?.barcode || '').trim();
          if (barcode && row?.id) productIdsByBarcode.set(barcode, String(row.id));
        });
      }

      const snapshot = await loadFboPalletSnapshot();
      const now = new Date().toISOString();
      const items = selectedProducts.map((product) => {
        const barcode = String(product.barcode || '').trim();
        const qty = Math.max(1, Math.floor(Number(fboPalletSelectedProducts[product.key]) || 1));
        return {
          id: createFboPalletId('fbo-pallet-item'),
          pallet_id: palletId,
          supplier_id: supplierId,
          product_id: productIdsByBarcode.get(barcode) || null,
          nm_id: product.nm_id || null,
          barcode: product.barcode || null,
          vendor_code: product.vendor_code || null,
          title: product.title,
          size: product.size || null,
          color: product.color || null,
          photo_url: product.photo_url || null,
          qty,
          product_json: product.product_json || null,
          created_at: now,
          deleted_at: null,
        } as FboPalletItem;
      });
      await saveFboPalletSnapshot({ ...snapshot, items: [...items, ...snapshot.items] });

      await fetchFboPalletData(supplierId);
      const totalQty = items.reduce((a, it: any) => a + Number(it.qty || 0), 0);
      logAction('ФБО: товары в паллету', `Добавлено позиций: ${items.length} (${totalQty} шт): ${items.slice(0,5).map((it:any)=>it.title).join(', ')}${items.length>5?'…':''}`, currentEmployee?.id);
      closeFboPalletProductPicker();
      showToast('Товары добавлены в паллету: ' + items.length, 'success');
    } catch (e: any) {
      showToast('Ошибка добавления товаров в паллету: ' + (e?.message || 'неизвестно'), 'error');
    }
  };

  const handleDeleteFboPalletItem = async (itemId: string) => {
    try {
      const snapshot = await loadFboPalletSnapshot();
      const deletedAt = new Date().toISOString();
      const delItem = snapshot.items.find((it) => String(it.id) === String(itemId));
      await saveFboPalletSnapshot({
        ...snapshot,
        items: snapshot.items.map((item) => String(item.id) === String(itemId) ? { ...item, deleted_at: deletedAt } : item),
      });
      await fetchFboPalletData(fboPalletSupplierId);
      logAction('ФБО: удаление товара из паллеты', `Товар «${delItem?.title || itemId}»${delItem?.qty ? ` (${delItem.qty} шт)` : ''}`, currentEmployee?.id);
    } catch (e: any) {
      showToast('Ошибка удаления товара из паллеты: ' + (e?.message || 'неизвестно'), 'error');
    }
  };

  const handleDeleteFboPallet = async (palletId: string) => {
    try {
      const snapshot = await loadFboPalletSnapshot();
      const deletedAt = new Date().toISOString();
      const delPallet = snapshot.pallets.find((p) => String(p.id) === String(palletId));
      await saveFboPalletSnapshot({
        ...snapshot,
        pallets: snapshot.pallets.map((pallet) => String(pallet.id) === String(palletId) ? { ...pallet, deleted_at: deletedAt } : pallet),
        items: snapshot.items.map((item) => String(item.pallet_id) === String(palletId) ? { ...item, deleted_at: deletedAt } : item),
      });
      await fetchFboPalletData(fboPalletSupplierId);
      logAction('ФБО: удаление паллеты', `Паллета №${delPallet?.pallet_number ?? palletId}`, currentEmployee?.id);
    } catch (e: any) {
      showToast('Ошибка удаления паллеты: ' + (e?.message || 'неизвестно'), 'error');
    }
  };

  const handleDeleteFboPalletWarehouse = async (warehouseId: string) => {
    const id = String(warehouseId || '').trim();
    if (!id) return;
    try {
      const snapshot = await loadFboPalletSnapshot();
      const warehouse = snapshot.warehouses.find((w) => String(w.id) === id);
      const supplyIds = new Set(
        snapshot.supplies.filter((s) => String(s.warehouse_id) === id).map((s) => String(s.id))
      );
      const palletIds = new Set(
        snapshot.pallets
          .filter((p) => String(p.warehouse_id || '') === id || supplyIds.has(String(p.supply_id || '')))
          .map((p) => String(p.id))
      );
      const activePallets = snapshot.pallets.filter((p) => palletIds.has(String(p.id)) && !p.deleted_at).length;
      const confirmed = await confirmDialog(
        activePallets > 0
          ? `Удалить склад «${warehouse?.name || id}»? Вместе с ним будут полностью удалены поставки, паллеты (${activePallets}) и их товары.`
          : `Удалить склад «${warehouse?.name || id}»?`
      );
      if (!confirmed) return;

      // Физическое удаление: убираем склад, его поставки, паллеты и товары из снапшота
      await saveFboPalletSnapshot({
        ...snapshot,
        warehouses: snapshot.warehouses.filter((w) => String(w.id) !== id),
        supplies: snapshot.supplies.filter((s) => !supplyIds.has(String(s.id))),
        pallets: snapshot.pallets.filter((p) => !palletIds.has(String(p.id))),
        items: snapshot.items.filter((item) => !palletIds.has(String(item.pallet_id))),
      });
      if (String(fboPalletSelectedWarehouseId) === id) {
        setFboPalletSelectedWarehouseId('');
        setFboPalletSelectedSupplyId('');
      }
      await fetchFboPalletData(fboPalletSupplierId);
      logAction('ФБО: удаление склада поставки', `Склад «${warehouse?.name || id}»${activePallets > 0 ? ` (паллет: ${activePallets})` : ''}`, currentEmployee?.id);
      showToast('Склад удалён', 'success');
    } catch (e: any) {
      showToast('Ошибка удаления склада: ' + (e?.message || 'неизвестно'), 'error');
    }
  };

  const getFboPalletScannedCount = async (product: Product) => {
    if (!currentSupply) return 0;
    const productId = String(product?.id || '').trim();
    const barcode = String(product?.barcode || '').trim();
    const nmId = String(product?.nm_id || product?.wb_sku || '').trim();

    try {
      if (warehouseOfflineEnabled) {
        const scans = await warehouseOfflineClient.getFboScans().catch(() => ({ pending: [], synced: [] }));
        const rows = [...((scans.pending || []) as any[]), ...((scans.synced || []) as any[])];
        return rows.filter((row: any) => {
          if (String(row?.supply_id || row?.supplyId || '') !== String(currentSupply.id)) return false;
          if (productId && String(row?.product_id || row?.productId || '') === productId) return true;
          if (barcode && String(row?.product_barcode || row?.barcode || '') === barcode) return true;
          return false;
        }).length;
      }

      if (fboOfflineMode) {
        const session = offlineFboSessionRef.current && offlineFboSessionRef.current.supply_id === currentSupply.id ? offlineFboSessionRef.current : buildEmptyOfflineFboSession(currentSupply);
        return (session.items || []).filter((item: any) => {
          const itemProduct = item?.product || {};
          if (productId && String(item?.product_id || itemProduct?.id || '') === productId) return true;
          if (barcode && String(itemProduct?.barcode || '') === barcode) return true;
          if (nmId && String(itemProduct?.nm_id || itemProduct?.wb_sku || '') === nmId) return true;
          return false;
        }).length;
      }

      if (!productId || productId.startsWith('offline-product-')) return 0;
      const { data: boxes, error: boxesError } = await supabase
        .from('supply_boxes')
        .select('id')
        .eq('supply_id', currentSupply.id)
        .is('deleted_at', null);
      if (boxesError) throw boxesError;
      const boxIds = (boxes || []).map((box: any) => String(box.id)).filter(Boolean);
      if (boxIds.length === 0) return 0;

      const { count, error } = await supabase
        .from('supply_items')
        .select('id', { count: 'exact', head: true })
        .in('box_id', boxIds)
        .eq('product_id', productId)
        .is('deleted_at', null);
      if (error) throw error;

      const pendingCount = pendingScansRef.current.filter((scan) => String(scan.productId || '') === productId).length;
      return Number(count || 0) + pendingCount;
    } catch (e) {
      console.warn('getFboPalletScannedCount failed', e);
      return 0;
    }
  };

  const findFboPalletHint = async (product: Product): Promise<FboPalletHint | null> => {
    const supplierId = String(currentSupply?.supplier_id || product?.supplier_id || '').trim();
    if (!supplierId) return null;

    try {
      const productId = String(product?.id || '').trim();
      const barcode = String(product?.barcode || '').trim();
      const nmId = String(product?.nm_id || product?.wb_sku || '').trim();
      if ((!productId || productId.startsWith('offline-product-')) && !barcode && !nmId) return null;

      const snapshot = await loadFboPalletSnapshot();
      // Include deleted warehouses/supplies too: a pallet may still reference a
      // soft-deleted one, and we still want to show its name in the scan hint.
      const warehouseById = new Map(snapshot.warehouses.map((warehouse) => [String(warehouse.id), warehouse]));
      const supplyById = new Map((snapshot.supplies || []).map((supply) => [String(supply.id), supply]));
      const activeSessionIds = new Set(snapshot.sessions
        .filter((session) => String(session.supplier_id) === supplierId && session.status === 'active' && !session.deleted_at)
        .map((session) => String(session.id)));
      const activePallets = snapshot.pallets.filter((pallet) => activeSessionIds.has(String(pallet.session_id)) && !pallet.deleted_at);
      const activePalletById = new Map(activePallets.map((pallet) => [String(pallet.id), pallet]));
      const activePalletIds = new Set(activePallets.map((pallet) => String(pallet.id)));
      const matchingItems = snapshot.items
        .filter((item) => String(item.supplier_id) === supplierId && !item.deleted_at && activePalletIds.has(String(item.pallet_id)))
        .filter((item) => {
          if (productId && !productId.startsWith('offline-product-') && item.product_id && String(item.product_id) === productId) return true;
          if (barcode && item.barcode && String(item.barcode) === barcode) return true;
          if (nmId && item.nm_id && String(item.nm_id) === nmId) return true;
          return false;
        })
        .sort((a, b) => {
          const palletA = activePalletById.get(String(a.pallet_id));
          const palletB = activePalletById.get(String(b.pallet_id));
          const numberDiff = Number(palletA?.pallet_number || 0) - Number(palletB?.pallet_number || 0);
          if (numberDiff !== 0) return numberDiff;
          return String(a.created_at || '').localeCompare(String(b.created_at || ''));
        });
      if (matchingItems.length === 0) return null;

      // Prefer items on pallets that belong to a real (non-deleted) warehouse.
      // Orphaned legacy pallets without a warehouse_id must not win the hint when
      // a properly-assigned pallet holds the same product — otherwise the worker
      // sees "Склад: не указан" even though the product is on a named pallet.
      const palletHasWarehouse = (palletId?: string | null) => {
        const pal = activePalletById.get(String(palletId || ''));
        const wh = pal ? warehouseById.get(String(pal.warehouse_id || '')) : null;
        return !!(wh && !wh.deleted_at);
      };
      const warehouseBacked = matchingItems.filter((item) => palletHasWarehouse(item.pallet_id));
      const effectiveItems = warehouseBacked.length > 0 ? warehouseBacked : matchingItems;

      const scannedQty = await getFboPalletScannedCount(product);
      let cumulativeQty = 0;
      const data = effectiveItems.find((item) => {
        cumulativeQty += Math.max(1, Number(item.qty || 1));
        return scannedQty < cumulativeQty;
      });
      const pallet = activePalletById.get(String(data?.pallet_id || ''));
      if (!data || !pallet?.pallet_number) return null;
      const warehouse = warehouseById.get(String(pallet.warehouse_id || ''));
      const supply = supplyById.get(String(pallet.supply_id || ''));
      const targetQty = Math.max(1, Number(data.qty || 1));
      return {
        warehouse_name: warehouse?.name || '',
        supply_name: supply?.name || '',
        supply_date: supply?.date || '',
        pallet_number: Number(pallet.pallet_number),
        item_title: String(data.title || product.name || ''),
        item_size: data.size || product.size || '',
        item_color: data.color || product.color || '',
        target_qty: targetQty,
        scanned_qty: Math.max(0, scannedQty - (cumulativeQty - targetQty)),
      };
    } catch (e) {
      console.warn('findFboPalletHint failed', e);
      return null;
    }
  };

  const fetchBoxItems = async (boxId: string) => {
    if (!boxId) {
      setBoxItems([]);
      return;
    }
    if (fboOfflineMode && currentSupply) {
      const session = offlineFboSession && offlineFboSession.supply_id === currentSupply.id ? offlineFboSession : buildEmptyOfflineFboSession(currentSupply);
      setBoxItems((session.items || []).filter((item) => item.box_id === boxId).sort((a, b) => String(b.created_at).localeCompare(String(a.created_at))));
      return;
    }
    if (warehouseOfflineEnabled) {
      try {
        const scans = await warehouseOfflineClient.getFboScans();
        const rows = [...((scans.pending || []) as any[]), ...((scans.synced || []) as any[])]
          .filter((row) => String(row?.box_id || row?.boxId || '') === String(boxId))
          .sort((a, b) => String(b.createdAt || b.created_at || '').localeCompare(String(a.createdAt || a.created_at || '')));
        setBoxItems(rows.map((row: any) => ({
          id: String(row.id || `warehouse-offline-${row.honest_sign_code || row.code || Math.random()}`),
          box_id: String(row.box_id || row.boxId || boxId),
          product_id: String(row.product_id || row.productId || ''),
          honest_sign_code: String(row.honest_sign_code || row.code || ''),
          created_at: String(row.created_at || row.createdAt || new Date().toISOString()),
          product: {
            id: String(row.product_id || row.productId || ''),
            supplier_id: String(row.supplier_id || currentSupply?.supplier_id || ''),
            name: String(row.product_name || ''),
            wb_sku: String(row.product_barcode || ''),
            barcode: String(row.product_barcode || ''),
            size: String(row.product_size || ''),
            color: String(row.product_color || ''),
            model_number: String(row.product_model_number || ''),
            created_at: String(row.created_at || row.createdAt || ''),
          } as Product,
        })));
      } catch (e) {
        setBoxItems([]);
      }
      return;
    }
    const { data } = await supabase.from('supply_items').select('*, product:products(*)').eq('box_id', boxId).order('created_at', { ascending: false });
    setBoxItems(data || []);
  };

  useEffect(() => {
    if (currentBox) fetchBoxItems(currentBox.id);
  }, [currentBox, fboOfflineMode, offlineFboSession, warehouseOfflineEnabled]);

  const ensureWbSkuIndex = async (supplierId: string) => {
    if (wbSkuIndexRef.current[supplierId]) return wbSkuIndexRef.current[supplierId];

    const index = new Map<string, { card: any; size: any }>();
    const addSkuToIndex = (sku: unknown, card: any, size: any = null) => {
      const key = String(sku || '').trim();
      if (key && !index.has(key)) index.set(key, { card, size });
    };

    if (warehouseOfflineEnabled) {
      const snapshot = await getWarehouseOfflineSnapshotOrEmpty();
      setWarehouseOfflineSnapshot(snapshot);
      for (const card of (snapshot.wbProducts || []) as any[]) {
        const cardSupplierId = String(card?.supplierId || card?.supplier_id || card?.supplierID || '');
        // Строго: товар должен явно принадлежать текущему поставщику.
        // Карточки без supplier_id НЕ индексируем — иначе чужой ШК попадает в чужую поставку.
        if (String(cardSupplierId) !== String(supplierId)) continue;
        addSkuToIndex(card?.barcode, card);
        const cardSkus = [
          ...(Array.isArray(card?.skus) ? card.skus : []),
          ...(Array.isArray(card?.barcodes) ? card.barcodes : []),
        ];
        cardSkus.forEach((sku) => addSkuToIndex(sku, card));
        const sizes = Array.isArray(card?.sizes) ? card.sizes : [];
        for (const size of sizes) {
          const skus = Array.isArray(size?.skus) ? size.skus : [];
          for (const sku of skus) addSkuToIndex(sku, card, size);
        }
      }
      wbSkuIndexRef.current[supplierId] = index;
      return index;
    }

    const pageSize = 200;
    let from = 0;

    while (true) {
      const { data: rows, error } = await supabase
        .from('wb_products_cache')
        .select('product_json')
        .eq('supplier_id', supplierId)
        .range(from, from + pageSize - 1);

      if (error) throw error;

      const chunk = rows || [];
      for (const row of chunk as any[]) {
        const card = row?.product_json;
        addSkuToIndex(card?.barcode, card);
        const cardSkus = [
          ...(Array.isArray(card?.skus) ? card.skus : []),
          ...(Array.isArray(card?.barcodes) ? card.barcodes : []),
        ];
        cardSkus.forEach((sku) => addSkuToIndex(sku, card));
        const sizes = Array.isArray(card?.sizes) ? card.sizes : [];
        for (const size of sizes) {
          const skus = Array.isArray(size?.skus) ? size.skus : [];
          for (const sku of skus) addSkuToIndex(sku, card, size);
        }
      }

      if (chunk.length < pageSize) break;
      from += pageSize;
    }

    wbSkuIndexRef.current[supplierId] = index;
    return index;
  };

  const ensureSupplierProductsIndex = async (supplierId: string) => {
    if (supplierProductsIndexRef.current[supplierId]) return supplierProductsIndexRef.current[supplierId];

    const index = new Map<string, Product>();

    if (warehouseOfflineEnabled || fboOfflineMode) {
      supplierProductsIndexRef.current[supplierId] = index;
      return index;
    }

    const pageSize = 200;
    let from = 0;

    while (true) {
      const { data, error } = await supabase
        .from('products')
        .select('*')
        .eq('supplier_id', supplierId)
        .is('deleted_at', null)
        .range(from, from + pageSize - 1);

      if (error) throw error;

      const chunk = (data || []) as Product[];
      for (const p of chunk) {
        if (p?.barcode) index.set(String(p.barcode), p);
      }

      if (chunk.length < pageSize) break;
      from += pageSize;
    }

    supplierProductsIndexRef.current[supplierId] = index;
    return index;
  };

  const ensureWbModelNumbers = async () => {
    if (wbModelNumbersRef.current.loaded) return wbModelNumbersRef.current.values;
    try {
      const { data } = await supabase.from('app_settings').select('value').eq('key', 'wb_model_numbers_v1').maybeSingle();
      const parsed = data?.value ? (typeof data.value === 'string' ? JSON.parse(data.value) : data.value) : {};
      const source = (parsed?.models && typeof parsed.models === 'object' ? parsed.models : parsed) as Record<string, string>;
      const values: Record<string, string> = {};
      Object.entries(source || {}).forEach(([key, value]) => {
        const cleanKey = String(key || '').trim();
        const cleanValue = String(value || '').trim();
        if (cleanKey && cleanValue) values[cleanKey] = cleanValue;
      });
      wbModelNumbersRef.current = { loaded: true, values };
      return values;
    } catch (e) {
      console.warn('Failed to load WB model numbers for FBO scan card', e);
      wbModelNumbersRef.current = { loaded: true, values: {} };
      return {};
    }
  };

  const preloadOfflineFboIndexes = useCallback(async (supplierId: string) => {
    if (!supplierId) return;
    if (wbSkuIndexRef.current[supplierId] && supplierProductsIndexRef.current[supplierId]) return;
    if (!offlineFboIndexesWarmupRef.current[supplierId]) {
      offlineFboIndexesWarmupRef.current[supplierId] = Promise.all([
        ensureWbSkuIndex(supplierId),
        ensureSupplierProductsIndex(supplierId),
      ]).then(() => undefined).finally(() => {
        delete offlineFboIndexesWarmupRef.current[supplierId];
      });
    }
    await offlineFboIndexesWarmupRef.current[supplierId];
  }, []);

  // Прогреваем индексы SKU/товаров заранее (при открытии поставки), чтобы первый
  // скан не ждал ~4с построения индекса из wb_products_cache.
  useEffect(() => {
    const sid = currentSupply?.supplier_id;
    if (!sid) return;
    preloadOfflineFboIndexes(sid);
    ensureWbModelNumbers();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [currentSupply?.supplier_id]);

  // Бейдж сборщика: WRK:<employeeId>. Возвращает true, если код распознан как бейдж.
  const tryHandleWorkerBadge = (raw: string): boolean => {
    const m = String(raw || '').trim().match(/^WRK[:;]\s*([0-9a-fA-F-]{6,})$/);
    if (!m) return false;
    const id = m[1];
    const emp = (employees || []).find((e: any) => String(e.id) === id);
    if (!emp) {
      playScanTone('error');
      showToast('Бейдж сборщика не распознан (сотрудник не найден)', 'error');
      return true;
    }
    setActiveScannerEmployee({ id: String(emp.id), name: emp.full_name || 'Сотрудник' });
    playScanTone('success');
    showToast(`Сканирует: ${emp.full_name || 'Сотрудник'}`, 'success');
    return true;
  };

  const handleItemScan = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentSupply) return;

    let input = (itemInputRef.current?.value || '').trim();
    if (!input) return;
    if (itemInputRef.current) itemInputRef.current.value = ''; // Clear immediately for speed

    if (/[\p{Script=Cyrillic}]/u.test(input)) {
       input = fixLayout(input);
       showToast('Раскладка исправлена', 'info');
    }

    if (tryHandleWorkerBadge(input)) return;

    if (input.trim() === 'ACTION:NEW_BOX' || input.trim() === 'NEW_BOX' || input.includes('NEW_BOX') || input.includes('ACTION;NEW_BOX')) {
      finishCurrentBoxAndReturn();
      return;
    }

    if (input.trim() === 'ACTION:GENERATE_BOX' || input.trim() === 'action:generate_box' || input.includes('GENERATE_BOX') || input.includes('generate_box') || input.includes('ACTION;GENERATE_BOX')) {
      await createNextBoxInCurrentSupply();
      return;
    }

    // Search scanned item in WB products cache (shared DB table), not in manual products section.
    let product = null;
    let matchedCard: any = null;
    let matchedSize: any = null;

    try {
      if (fboOfflineMode) {
        await preloadOfflineFboIndexes(currentSupply.supplier_id);
      }

      let skuIndex = await ensureWbSkuIndex(currentSupply.supplier_id);
      let hit = skuIndex.get(String(input).trim());

      // One forced re-index attempt only for online mode
      if (!hit && !fboOfflineMode) {
        delete wbSkuIndexRef.current[currentSupply.supplier_id];
        skuIndex = await ensureWbSkuIndex(currentSupply.supplier_id);
        hit = skuIndex.get(String(input).trim());
      }

      if (hit) {
        matchedCard = hit.card;
        matchedSize = hit.size;
      }

      // Защита: ШК должен принадлежать поставщику текущей поставки.
      // Если в карточке указан другой supplier_id — товар чужой, не заносим.
      if (matchedCard) {
        const cardSup = String(matchedCard?.supplierId || matchedCard?.supplier_id || matchedCard?.supplierID || '').trim();
        if (cardSup && cardSup !== String(currentSupply.supplier_id)) {
          const otherName = suppliers.find((s: any) => String(s.id) === cardSup)?.name || 'другой поставщик';
          showToast(`Этот ШК принадлежит другому поставщику (${otherName}). Товар не добавлен.`, 'error');
          playScanTone('error');
          return;
        }
      }

      if (matchedCard && matchedSize) {
        const productsIndex = await ensureSupplierProductsIndex(currentSupply.supplier_id);
        const cachedProduct = productsIndex.get(String(input));
        const modelNumbers = await ensureWbModelNumbers();
        const nmId = String(matchedCard?.nmID || matchedCard?.nmId || '').trim();
        const manualModelNumber = nmId ? String(modelNumbers[nmId] || '').trim() : '';

        if (cachedProduct) {
          product = buildFboScanProductCard({ ...cachedProduct, model_number: manualModelNumber }, matchedCard, matchedSize, input);
        } else {
          const colorValue = getWbCharacteristicValue(matchedCard, ['цвет']);

          if (fboOfflineMode) {
            const offlineProduct = {
              id: `offline-product-${currentSupply.supplier_id}-${String(input).trim()}`,
              supplier_id: currentSupply.supplier_id,
              name: String(matchedCard.title || 'Товар'),
              wb_sku: String(matchedCard.nmID || ''),
              barcode: String(input).trim(),
              size: String(matchedSize.techSize || ''),
              color: String(colorValue || ''),
              created_at: new Date().toISOString(),
              model_number: manualModelNumber,
            } as Product;
            product = buildFboScanProductCard(offlineProduct, matchedCard, matchedSize, input);
            productsIndex.set(String(input), product);
          } else {
            const { data: newProd, error: insertError } = await supabase
              .from('products')
              .insert({
                name: matchedCard.title,
                wb_sku: String(matchedCard.nmID || ''),
                barcode: input,
                size: matchedSize.techSize,
                color: colorValue,
                supplier_id: currentSupply.supplier_id,
              })
              .select()
              .single();

            if (!insertError && newProd) {
              product = buildFboScanProductCard({ ...(newProd as Product), model_number: manualModelNumber }, matchedCard, matchedSize, input);
              productsIndex.set(String(input), product);
            }
          }
        }
      }
    } catch (e) {
      console.error('WB cache search error:', e);
    }

    if (!product) {
      showToast('Товар не найден в разделе Товары WB (кэш поставщика). Нажмите «Обновить» в Товары WB.', 'error');
      return;
    }

    const palletHint = await findFboPalletHint(product);
    setFboPalletHint(palletHint);
    if (palletHint) {
      showToast(`${(palletHint.warehouse_name || 'Склад не указан') + ' • '}${(palletHint.supply_name || 'Поставка не указана') + ' • '}Паллета №${palletHint.pallet_number}: ${Number(palletHint.scanned_qty || 0) + 1}/${palletHint.target_qty || 1}. Поставьте коробку туда.`, 'info');
    }

    setScannedItem(product);
    setSupplyStep('HONEST_SIGN');
  };

  const playScanTone = (kind: 'success' | 'error' = 'success') => {
    try {
      const Ctx = (window as any).AudioContext || (window as any).webkitAudioContext;
      if (!Ctx) return;
      if (!scanAudioCtxRef.current) scanAudioCtxRef.current = new Ctx();
      const ctx = scanAudioCtxRef.current;
      if (ctx.state === 'suspended') ctx.resume?.();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.type = kind === 'error' ? 'square' : 'sine';
      osc.frequency.value = kind === 'error' ? 220 : 880;
      gain.gain.setValueAtTime(0.0001, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(kind === 'error' ? 0.15 : 0.12, ctx.currentTime + 0.01);
      gain.gain.exponentialRampToValueAtTime(0.0001, ctx.currentTime + 0.10);
      osc.start();
      osc.stop(ctx.currentTime + 0.11);
    } catch {}
  };

  const syncScannedCodesToUnifiedBase = useCallback(async (codes: string[], supplierId?: string) => {
    const normalizedSupplierId = String(supplierId || '').trim();
    const uniqueCodes = Array.from(new Set((codes || []).map((code) => String(code || '').trim()).filter(Boolean)));
    if (!normalizedSupplierId || uniqueCodes.length === 0) return;

    const nowIso = new Date().toISOString();
    const { data: existing, error: existingError } = await supabase
      .from('unified_honest_sign_codes')
      .select('id, code, supplier_id, category')
      .filter('code', 'in', pgInList(uniqueCodes));

    if (existingError) throw existingError;

    const existingByCode = new Map<string, any>();
    (existing || []).forEach((row: any) => {
      const code = String(row?.code || '').trim();
      if (code) existingByCode.set(code, row);
    });

    const idsToUpdate: string[] = [];
    const toInsert: Array<{ supplier_id: string; category: string; code: string; file_name: string; status: string; created_at: string }> = [];

    uniqueCodes.forEach((code) => {
      const row = existingByCode.get(code);
      if (!row) {
        toInsert.push({
          supplier_id: normalizedSupplierId,
          category: normalizeHSCategory('Без категории'),
          code,
          file_name: 'Отсканировано',
          status: 'scanned',
          created_at: nowIso,
        });
        return;
      }

      const rowSupplierId = String(row?.supplier_id || '').trim();
      if (!rowSupplierId || rowSupplierId === normalizedSupplierId) {
        if (row?.id) idsToUpdate.push(String(row.id));
      }
    });

    if (idsToUpdate.length > 0) {
      const { error } = await supabase
        .from('unified_honest_sign_codes')
        .update({
          supplier_id: normalizedSupplierId,
          file_name: 'Отсканировано',
          status: 'scanned',
          created_at: nowIso,
        })
        .in('id', idsToUpdate);
      if (error) throw error;
    }

    if (toInsert.length > 0) {
      const { error } = await supabase
        .from('unified_honest_sign_codes')
        .insert(toInsert);
      if (error) throw error;
    }
  }, [normalizeHSCategory]);

  const isCodeAlreadyScannedForSupplier = useCallback(async (code: string, supplierId?: string) => {
    const normalizedCode = String(code || '').trim();
    const normalizedSupplierId = String(supplierId || '').trim();
    if (!normalizedCode || !normalizedSupplierId) return false;

    const { data, error } = await supabase
      .from('unified_honest_sign_codes')
      .select('id')
      .eq('supplier_id', normalizedSupplierId)
      .eq('code', normalizedCode)
      .or('file_name.eq.Отсканировано,status.eq.scanned')
      .limit(1)
      .maybeSingle();

    if (error) throw error;
    return Boolean(data?.id);
  }, []);

  const flushPendingScans = useCallback(async () => {
    if (pendingScansRef.current.length === 0) return;
    const batch = [...pendingScansRef.current];
    pendingScansRef.current = [];

    const { error } = await supabase.from('supply_items').insert(
      batch.map((x) => ({ box_id: x.boxId, product_id: x.productId, honest_sign_code: x.code, scanned_by: x.scannedBy || null }))
    );

    if (error) {
      playScanTone('error');
      showToast('Ошибка пакетного сохранения: ' + error.message, 'error');
      return;
    }

    try {
      await syncScannedCodesToUnifiedBase(batch.map((x) => x.code), currentSupply?.supplier_id);
    } catch (e: any) {
      console.error('Failed to sync FBO scanned codes to unified base', e);
      showToast('ЧЗ сохранён в поставку, но не удалось обновить базу ЧЗ', 'error');
    }

    if (currentBox) fetchBoxItems(currentBox.id);
  }, [currentBox, currentSupply?.supplier_id, syncScannedCodesToUnifiedBase]);

  const handleHonestSignScan = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!currentBox || !scannedItem) return;

    let code = (honestSignInputRef.current?.value || '').trim();
    if (!code) return;

    if (isScanningRef.current) return;
    isScanningRef.current = true;

    try {
        if (honestSignInputRef.current) honestSignInputRef.current.value = ''; // Clear immediately for speed

        if (/[\p{Script=Cyrillic}]/u.test(code)) {
           code = fixLayout(code);
           showToast('Раскладка исправлена', 'info');
        }

        if (tryHandleWorkerBadge(code)) return;

        if (code.trim() === 'ACTION:NEW_BOX' || code.trim() === 'NEW_BOX' || code.includes('NEW_BOX') || code.includes('ACTION;NEW_BOX')) {
          finishCurrentBoxAndReturn();
          return;
        }

        // Validation: Prevent scanning item barcodes (EAN-8, EAN-13, UPC-12)
        // Honest Sign codes are usually much longer (DataMatrix)
        if ((code.length === 8 || code.length === 12 || code.length === 13) && /^\d+$/.test(code)) {
          playScanTone('error');
          showToast('Это штрихкод товара, а не Честный Знак!', 'error');
          return;
        }

        if (warehouseOfflineEnabled) {
          const scanRow = {
            supply_id: currentSupply?.id,
            supply_name: currentSupply?.name,
            supplier_id: currentSupply?.supplier_id,
            box_id: currentBox.id,
            box_name: currentBox.name,
            product_id: scannedItem.id,
            product_name: scannedItem.name,
            product_barcode: scannedItem.barcode,
            product_size: scannedItem.size,
            product_color: scannedItem.color,
            product_model_number: scannedItem.model_number || '',
            honest_sign_code: code,
            code,
            createdAt: new Date().toISOString(),
          };
          await warehouseOfflineClient.enqueueFboScan(scanRow);
          await checkWarehouseOfflineServer(false);
          playScanTone('success');
          setBoxItems((prev) => ([{ id: 'warehouse-offline-' + Date.now() + '-' + Math.random(), box_id: currentBox.id, product_id: scannedItem.id, honest_sign_code: code, created_at: new Date().toISOString(), deleted_at: null, product: scannedItem } as any, ...(prev || [])]));
          setSupplyStats((prev) => ({ ...prev, items: Number(prev.items || 0) + 1 }));
          showToast('Скан сохранён в локальную очередь ПК', 'success');
          setScannedItem(null);
          setSupplyStep('BOX');
          return;
        }

        if (fboOfflineMode && currentSupply) {
          const session = offlineFboSessionRef.current && offlineFboSessionRef.current.supply_id === currentSupply.id ? offlineFboSessionRef.current : buildEmptyOfflineFboSession(currentSupply);
          const offlineDuplicate = (session.items || []).some((item) => item.honest_sign_code === code);
          if (offlineDuplicate) {
            playScanTone('error');
            showToast('Этот Честный Знак уже добавлен в оффлайн-сессию!', 'error');
            return;
          }
          const newItem: SupplyItem = {
            id: `offline-item-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
            box_id: currentBox.id,
            product_id: scannedItem.id,
            honest_sign_code: code,
            created_at: new Date().toISOString(),
            product: scannedItem,
          };
          updateOfflineFboSession((currentSession) => ({ ...currentSession, items: [newItem, ...(currentSession.items || [])] }), currentBox.id);
          playScanTone('success');
          showToast('Товар добавлен в оффлайн-сессию', 'success');
          setScannedItem(null);
          setSupplyStep('BOX');
          return;
        }

        const pendingDuplicate = pendingScansRef.current.some((x) => x.code === code);
        if (pendingDuplicate) {
          playScanTone('error');
          showToast('Этот Честный Знак уже добавлен в очередь!', 'error');
          return;
        }

        // Дубль проверяем по всей истории: и в базе ЧЗ поставщика, и глобально по supply_items.
        const existsInSupplierScannedBase = await isCodeAlreadyScannedForSupplier(code, currentSupply?.supplier_id);
        if (existsInSupplierScannedBase) {
          playScanTone('error');
          showToast('Этот Честный Знак уже есть в базе отсканированных ЧЗ этого поставщика!', 'error');
          return;
        }

        const { data: existing } = await supabase.from('supply_items').select('id').eq('honest_sign_code', code).maybeSingle();
        if (existing) {
          playScanTone('error');
          showToast('Этот Честный Знак уже отсканирован!', 'error');
          return;
        }

        pendingScansRef.current.push({ boxId: currentBox.id, productId: scannedItem.id, code, scannedBy: resolveScannerId() });
        playScanTone('success');
        setBoxItems((prev) => ([{ id: `pending-${Date.now()}-${Math.random()}`, box_id: currentBox.id, product_id: scannedItem.id, honest_sign_code: code, created_at: new Date().toISOString(), deleted_at: null, product: scannedItem } as any, ...(prev || [])]));
        setSupplyStats((prev) => ({ ...prev, items: Number(prev.items || 0) + 1 }));

        if (flushScansTimeoutRef.current) {
          window.clearTimeout(flushScansTimeoutRef.current);
        }

        flushScansTimeoutRef.current = window.setTimeout(() => {
          flushPendingScans().catch((err) => {
            console.error('Batch flush failed', err);
          });
        }, 90);

        showToast('Товар добавлен', 'success');
        setScannedItem(null);
        setSupplyStep('BOX');
    } finally {
        isScanningRef.current = false;
    }
  };

  useEffect(() => {
    return () => {
      if (flushScansTimeoutRef.current) {
        window.clearTimeout(flushScansTimeoutRef.current);
      }
      if (offlineFboSessionWriteTimeoutRef.current) {
        window.clearTimeout(offlineFboSessionWriteTimeoutRef.current);
      }
      if (offlineFboStatsRefreshTimeoutRef.current) {
        window.clearTimeout(offlineFboStatsRefreshTimeoutRef.current);
      }
      flushPendingScans().catch(() => undefined);
    };
  }, [flushPendingScans]);

  const handleDeleteBox = async (boxId: string) => {
    if (!await confirmDialog('Вы уверены, что хотите удалить эту коробку?')) return;
    try {
      if (warehouseOfflineEnabled) {
        const snapshot = await getWarehouseOfflineSnapshotOrEmpty();
        const box = (snapshot.fboBoxes || []).find((row: any) => String(row?.id || '') === String(boxId));
        const nextSnapshot = {
          ...snapshot,
          fboBoxes: (snapshot.fboBoxes || []).filter((row: any) => String(row?.id || '') !== String(boxId)),
        };
        await saveWarehouseOfflineSnapshotState(nextSnapshot);
        await warehouseOfflineClient.deleteFboScansByBox(boxId).catch(() => ({ ok: true, deleted: 0 }));
        if (currentBox?.id === boxId) {
          setCurrentBox(null);
          setSupplyStep('SUPPLY');
          setBoxItems([]);
        }
        if (currentSupply) {
          await fetchBoxesList(currentSupply.id);
          await fetchSupplyStats(currentSupply.id);
        }
        logAction('Удаление коробки', `Удалена коробка (offline): ${box?.name || boxId}`, currentEmployee?.id);
        showToast('Offline-коробка удалена' + (box?.name ? `: ${box.name}` : ''), 'success');
        return;
      }

      if (fboOfflineMode && currentSupply) {
        const offBox = (offlineFboSessionRef.current?.boxes || []).find((b: any) => b.id === boxId);
        updateOfflineFboSession((session) => ({
          ...session,
          boxes: (session.boxes || []).filter((box) => box.id !== boxId),
          items: (session.items || []).filter((item) => item.box_id !== boxId),
        }));
        if (currentBox?.id === boxId) {
          setCurrentBox(null);
          setSupplyStep('SUPPLY');
          setBoxItems([]);
        }
        logAction('Удаление коробки', `Удалена коробка (offline): ${offBox?.name || boxId}`, currentEmployee?.id);
        showToast('Оффлайн-коробка удалена', 'success');
        return;
      }

      const { data: box } = await supabase.from('boxes').select('name').eq('id', boxId).single();
      const { error } = await supabase.from('boxes').update({ deleted_at: new Date().toISOString() }).eq('id', boxId);
      if (error) throw error;

      await logAction('Удаление коробки', `Удалена коробка: ${box?.name || 'Без названия'}`, currentEmployee?.id);

      if (currentSupply) fetchBoxesList(currentSupply.id);
      showToast('Коробка удалена', 'success');
    } catch (e: any) {
      showToast('Ошибка удаления коробки: ' + e.message, 'error');
    }
  };

  const handleDeleteWarehouseCost = async (id: string) => {
    if (!await confirmDialog('Удалить запись?')) return;
    const { error } = await supabase.from('supplier_warehouse_costs').delete().eq('id', id);
    if (error) showToast('Ошибка удаления: ' + error.message, 'error');
    else {
        showToast('Запись удалена', 'success');
        fetchWarehouseCosts();
        fetchReportsData();
    }
  };

  const handleEditWarehouseCost = (item: any) => {
    setWarehouseCostForm({
        month: item.month_date.slice(0, 7),
        cost: item.cost.toString()
    });
  };

  const handleSaveWarehouseCost = async () => {
    if (!reportsReportForm.supplier_id) return;
    if (!warehouseCostForm.cost) {
        showToast('Введите стоимость', 'error');
        return;
    }

    try {
        const date = `${warehouseCostForm.month}-01`;
        const { error } = await supabase.from('supplier_warehouse_costs').upsert({
            supplier_id: reportsReportForm.supplier_id,
            month_date: date,
            cost: parseFloat(warehouseCostForm.cost),
            updated_at: new Date().toISOString()
        }, { onConflict: 'supplier_id, month_date' });

        if (error) throw error;

        showToast('Стоимость склада сохранена', 'success');
        setWarehouseCostForm({ ...warehouseCostForm, cost: '' });
        if (reportsReportResult) generateReportsReport();
        fetchReportsData();
        fetchWarehouseCosts();
    } catch (e: any) {
        showToast('Ошибка сохранения: ' + e.message, 'error');
    }
  };

  const softDeleteWithActor = async (table: string, id: string) => {
    const payload: any = { deleted_at: new Date().toISOString(), deleted_by: currentEmployee?.id || null };
    let res = await supabase.from(table).update(payload).eq('id', id);
    if (res.error && String(res.error.message || '').toLowerCase().includes('deleted_by')) {
      res = await supabase.from(table).update({ deleted_at: payload.deleted_at }).eq('id', id);
    }
    return res;
  };

  const handleDeleteSupply = (id: string) => {
    openConfirmModal(
      'Удаление поставки',
      'Удалить поставку? Все коробки и товары в ней будут удалены.',
      async () => {
        try {
          // 1. Get all boxes
          const { data: boxes } = await supabase.from('boxes').select('id').eq('supply_id', id);
          const boxIds = boxes?.map(b => b.id) || [];

          // 2. Delete all items in these boxes
          if (boxIds.length > 0) {
            await supabase.from('supply_items').update({ deleted_at: new Date().toISOString() }).in('box_id', boxIds);
          }

          // 3. Delete boxes
          await supabase.from('boxes').update({ deleted_at: new Date().toISOString() }).eq('supply_id', id);

          // 4. Delete supply
          const { error } = await softDeleteWithActor('supplies', id);

          if (error) throw error;

          await logAction('Удаление поставки', 'Удалена поставка', currentEmployee?.id);

          showToast('Поставка удалена', 'success');
          fetchSuppliesList();
        } catch (error: any) {
          console.error('Delete error:', error);
          showToast('Ошибка удаления: ' + error.message, 'error');
        }
        setConfirmModal(prev => ({ ...prev, isOpen: false }));
      }
    );
  };

  // Telegram State
  const [telegramBotToken, setTelegramBotToken] = useState('');
  const [telegramBotTokenFile, setTelegramBotTokenFile] = useState('');
  const [writeoffBotToken, setWriteoffBotToken] = useState('');
  const [writeoffAdminChatId, setWriteoffAdminChatId] = useState('498924112');
  const [isTokenLocked, setIsTokenLocked] = useState(true);
  const [telegramSupplierId, setTelegramSupplierId] = useState('');
  const [telegramMessage, setTelegramMessage] = useState('');
  const [telegramFile, setTelegramFile] = useState<File | null>(null);
  const [sendingTelegram, setSendingTelegram] = useState(false);
  const [showCloseModal, setShowCloseModal] = useState(false);
  const telegramFileRef = useRef<HTMLInputElement>(null);

  // Removed localStorage effect for telegramBotToken

  const generateSupplyExcel = async (supply: Supply) => {
    // 1. Fetch all boxes
    const { data: boxes, error: boxesError } = await supabase
      .from('boxes')
      .select('id, name')
      .eq('supply_id', supply.id);

    if (boxesError) throw boxesError;

    const boxMap = new Map(boxes?.map(b => [b.id, b.name]) || []);
    const boxIds = boxes?.map(b => b.id) || [];

    // 2. Fetch all items
    let items: any[] = [];
    if (boxIds.length > 0) {
      const { data, error: itemsError } = await supabase
        .from('supply_items')
        .select('*, product:products(barcode)')
        .in('box_id', boxIds);

      if (itemsError) throw itemsError;
      items = data || [];
    }

    // 3. Group and Count
    // Key: "ProductBarcode|BoxName" -> Count
    const counts = new Map<string, number>();

    items.forEach(item => {
      const productData = Array.isArray(item.product) ? item.product[0] : item.product;
      const barcode = productData?.barcode || 'UNKNOWN';
      const boxName = boxMap.get(item.box_id) || 'UNKNOWN';
      const key = `${barcode}|${boxName}`;
      counts.set(key, (counts.get(key) || 0) + 1);
    });

    // 4. Format Data
    let rows = Array.from(counts.entries()).map(([key, count]) => {
      const [barcode, boxName] = key.split('|');
      return {
        'Баркод товара': barcode,
        'Кол-во товаров': count,
        'ШК короба': boxName,
        'Срок годности': ''
      };
    });

    // 5. Create workbook blob
    return await createWorkbookBlob([
      {
        name: 'Поставка',
        rows,
        headers: ['Баркод товара', 'Кол-во товаров', 'ШК короба', 'Срок годности'],
        widths: [20, 15, 20, 15],
      },
    ]);
  };

  const handleDownloadExcel = async () => {
    if (!currentSupply) return;
    try {
      const blob = await generateSupplyExcel(currentSupply);

      const supplierName = suppliers.find(s => s.id === currentSupply.supplier_id)?.name || 'Unknown';
      const dateStr = new Date().toLocaleDateString('ru-RU').replace(/\./g, '-');
      const fileName = `${supplierName}_${dateStr}.xlsx`;

      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = fileName;
      a.click();
      window.URL.revokeObjectURL(url);
    } catch (error: any) {
      showToast('Ошибка генерации файла: ' + error.message, 'error');
    }
  };

  const handleCloseSupply = () => {
    if (!currentSupply) return;
    setShowCloseModal(true);
  };

  const executeCloseSupply = async () => {
    if (!currentSupply) return;
    setShowCloseModal(false);

    const supplier = suppliers.find(s => s.id === currentSupply.supplier_id);
    if (!supplier || !supplier.telegram_chat_id) {
      showToast('У поставщика не настроен Telegram Chat ID', 'error');
      return;
    }

    if (!telegramBotToken) {
      showToast('Не настроен токен Telegram бота', 'error');
      return;
    }

    setSendingTelegram(true);
    try {
      const blob = await generateSupplyExcel(currentSupply);

      const supplierName = supplier.name;
      const dateStr = new Date().toLocaleDateString('ru-RU').replace(/\./g, '-');
      const fileName = `${supplierName}_${dateStr}.xlsx`;

      const formData = new FormData();
      formData.append('chat_id', supplier.telegram_chat_id);
      formData.append('document', blob, fileName);
      formData.append('caption', `Ваша поставка готова к отгрузке.\nКоличество товаров: ${supplyStats.items}\nКоличество коробок: ${supplyStats.boxes}\nЗагрузите файл на WB.`);

      const response = await fetch(`https://api.telegram.org/bot${telegramBotToken}/sendDocument`, {
        method: 'POST',
        body: formData
      });

      const data = await response.json();
      if (!data.ok) throw new Error(data.description);

      // Update status
      const { error } = await supabase
        .from('supplies')
        .update({ status: 'closed' })
        .eq('id', currentSupply.id);

      if (error) throw error;

      setCurrentSupply({ ...currentSupply, status: 'closed' });
      await logAction('Закрытие поставки', `Закрыта поставка: ${currentSupply.name}`, currentEmployee?.id);
      showToast('Поставка закрыта и отправлена поставщику', 'success');
    } catch (error: any) {
      showToast('Ошибка: ' + error.message, 'error');
    } finally {
      setSendingTelegram(false);
    }
  };

  const handleToggleSupplyLock = async () => {
    if (!currentSupply) return;
    const newStatus = currentSupply.status === 'closed' ? 'active' : 'closed';

    if (newStatus === 'active' && !(await confirmDialog({ title: 'Открыть поставку', tone: 'primary', confirmText: 'Открыть', message: 'Открыть поставку для редактирования?' }))) return;

    const { error } = await supabase
      .from('supplies')
      .update({ status: newStatus })
      .eq('id', currentSupply.id);

    if (error) {
      showToast('Ошибка обновления статуса: ' + error.message, 'error');
    } else {
      setCurrentSupply({ ...currentSupply, status: newStatus });
      logAction(newStatus === 'closed' ? 'Блокировка поставки' : 'Разблокировка поставки', `Поставка «${currentSupply.name}»`, currentEmployee?.id);
      showToast(newStatus === 'closed' ? 'Поставка заблокирована' : 'Поставка разблокирована', 'success');
    }
  };

  // Settings Logic
  const handleSaveSetting = async (key: string, value: string) => {
    try {
      const { error } = await supabase
        .from('app_settings')
        .upsert({ key, value });

      if (error) throw error;
      showToast('Настройка сохранена', 'success');
    } catch (e) {
      console.error('Error saving setting:', e);
      showToast('Ошибка при сохранении', 'error');
    }
  };

  useEffect(() => {
    const fetchSettings = async () => {
        const { data } = await supabase
          .from('app_settings')
          .select('key, value')
          .in('key', ['telegram_bot_token', 'telegram_reception_bot_token', 'telegram_login_logs_bot_token', 'telegram_bot_token_file', 'backup_bot_token', 'telegram_writeoff_bot_token', 'telegram_writeoff_admin_chat_id', 'database_backup_logs']);

        if (data) {
            data.forEach(setting => {
                if (setting.key === 'telegram_bot_token') setTelegramBotToken(setting.value);
                if (setting.key === 'telegram_reception_bot_token') setTelegramReceptionBotToken(setting.value);
                if (setting.key === 'telegram_login_logs_bot_token') setTelegramBotTokenFile(setting.value);
                if (setting.key === 'backup_bot_token') setBackupBotToken(setting.value);
                if (setting.key === 'telegram_writeoff_bot_token') setWriteoffBotToken(setting.value);
                if (setting.key === 'telegram_writeoff_admin_chat_id' && setting.value) setWriteoffAdminChatId(setting.value);
                if (setting.key === 'database_backup_logs') {
                    try {
                        const parsed = typeof setting.value === 'string' ? JSON.parse(setting.value) : setting.value;
                        if (Array.isArray(parsed)) {
                            setDatabaseLogs(parsed);
                        }
                    } catch (e) {
                        console.error('Failed to parse database logs', e);
                    }
                }
            });
        }
    };
    fetchSettings();
  }, []);

  const handleSendTelegram = (e: React.FormEvent) => {
    e.preventDefault();
    const selectedToken = selectedBotForManual === 'reception'
      ? telegramReceptionBotToken
      : selectedBotForManual === 'file'
        ? backupBotToken
        : telegramBotToken;

    if (!selectedToken || !telegramSupplierId || (!telegramMessage && !telegramFile)) {
      showToast('Заполните все обязательные поля', 'error');
      return;
    }

    const supplier = suppliers.find(s => s.id === telegramSupplierId);
    if (!supplier || !supplier.telegram_chat_id) {
      showToast('У выбранного поставщика нет Chat ID', 'error');
      return;
    }

    // Capture data for background sending
    const currentMessage = telegramMessage;
    const currentFile = telegramFile;
    const currentToken = selectedToken;
    const chatId = supplier.telegram_chat_id;

    // Optimistic UI update
    showToast('Сообщение отправлено', 'success');
    setTelegramMessage('');
    setTelegramFile(null);
    if (telegramFileRef.current) telegramFileRef.current.value = '';

    // Send in background
    (async () => {
      try {
        const formData = new FormData();
        formData.append('chat_id', chatId);

        let endpoint = `https://api.telegram.org/bot${currentToken}/sendMessage`;

        if (currentFile) {
          endpoint = `https://api.telegram.org/bot${currentToken}/sendDocument`;
          formData.append('document', currentFile);
          if (currentMessage) formData.append('caption', currentMessage);
        } else {
          formData.append('text', currentMessage);
        }

        const response = await fetch(endpoint, {
          method: 'POST',
          body: formData
        });

        const data = await response.json();
        if (!data.ok) throw new Error(data.description);
      } catch (error: any) {
        console.error('Background Telegram send failed:', error);
      }
    })();
  };

  const handleSendTelegramMenu = async () => {
    const selectedToken = selectedBotForManual === 'reception'
      ? telegramReceptionBotToken
      : selectedBotForManual === 'file'
        ? backupBotToken
        : telegramBotToken;

    if (!selectedToken || !telegramSupplierId) {
      showToast('Выберите бота и поставщика', 'error');
      return;
    }

    const supplier = suppliers.find(s => s.id === telegramSupplierId);
    if (!supplier || !supplier.telegram_chat_id) {
      showToast('У выбранного поставщика нет Chat ID', 'error');
      return;
    }

    try {
      // 1) Clear old keyboard first
      const clearResp = await fetch(`https://api.telegram.org/bot${selectedToken}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chat_id: supplier.telegram_chat_id,
          text: 'Обновляю меню…',
          reply_markup: { remove_keyboard: true }
        })
      });
      const clearData = await clearResp.json();
      if (!clearData.ok) throw new Error(clearData.description || 'Telegram API error (remove keyboard)');

      // 2) New main menu button
      const response = await fetch(`https://api.telegram.org/bot${selectedToken}/sendMessage`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          chat_id: supplier.telegram_chat_id,
          text: 'Меню SkladPro',
          reply_markup: {
            keyboard: [[{ text: '📦 Показать активные поставки' }]],
            resize_keyboard: true,
            one_time_keyboard: false,
          }
        })
      });

      const data = await response.json();
      if (!data.ok) throw new Error(data.description || 'Telegram API error');

      // 3) Immediately send active supplies list with download links per supply
      const { data: activeSupplies, error: suppliesError } = await supabase
        .from('supplies')
        .select('id, name, status, created_at')
        .eq('supplier_id', telegramSupplierId)
        .is('deleted_at', null)
        .not('status', 'in', '(done,completed,closed)')
        .order('created_at', { ascending: false })
        .limit(15);
      if (suppliesError) throw suppliesError;

      const { data: allFiles } = await supabase
        .from('print_files')
        .select('name, url, supplier_id, created_at')
        .eq('supplier_id', telegramSupplierId)
        .order('created_at', { ascending: false })
        .limit(500);

      const files = (allFiles || []) as Array<{ name?: string; url?: string }>;
      const suppliesRows = (activeSupplies || []) as Array<{ id: string; name?: string; status?: string }>;

      for (const s of suppliesRows) {
        const supplyName = String(s?.name || 'Поставка').trim();
        const filesForSupply = files.filter((f) => String(f?.name || '').toLowerCase().includes(supplyName.toLowerCase()));
        const fbsFile = filesForSupply.find((f) => /fbs|лист\s*подбора|picking/i.test(String(f?.name || '')));
        const groupFile = filesForSupply.find((f) => /груп|group/i.test(String(f?.name || '')));
        const stickerFile = filesForSupply.find((f) => /стикер|sticker|этикет/i.test(String(f?.name || '')));

        const row1: Array<{ text: string; url: string }> = [];
        if (fbsFile?.url) row1.push({ text: '📥 FBS лист', url: String(fbsFile.url) });
        if (groupFile?.url) row1.push({ text: '📥 Групп лист', url: String(groupFile.url) });
        const row2: Array<{ text: string; url: string }> = [];
        if (stickerFile?.url) row2.push({ text: '🏷 Стикеры', url: String(stickerFile.url) });

        const inline_keyboard = [row1, row2].filter((r) => r.length > 0);
        const text = `📦 ${supplyName}${s?.status ? `\nСтатус: ${s.status}` : ''}`;

        await fetch(`https://api.telegram.org/bot${selectedToken}/sendMessage`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            chat_id: supplier.telegram_chat_id,
            text,
            ...(inline_keyboard.length ? { reply_markup: { inline_keyboard } } : {})
          })
        });
      }

      if (!suppliesRows.length) {
        await fetch(`https://api.telegram.org/bot${selectedToken}/sendMessage`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            chat_id: supplier.telegram_chat_id,
            text: 'Активные поставки не найдены.'
          })
        });
      }

      showToast('Меню и список активных поставок отправлены в Telegram', 'success');
    } catch (error: any) {
      showToast(`Ошибка отправки меню: ${error?.message || 'Unknown error'}`, 'error');
    }
  };

  // Suppliers Functions
  /** Сколько раз уже перезапрашивали поставщиков после ошибки: без этого будет вечный цикл. */
  const suppliersRetryRef = useRef(0);

  const fetchSuppliers = async () => {
    const { data, error } = await supabase
      .from('suppliers')
      .select('*')
      .is('deleted_at', null)
      .order('created_at', { ascending: false });

    /*
     * Молчаливый пустой список — худший исход.
     *
     * 02.10 на телефоне раздел ФБС открылся без поставщиков, заказов и
     * поставок, а в шапке значилось «база подключена»: запрос упал, ошибка
     * ушла только в консоль. Теперь о провале говорим вслух и пробуем ещё раз.
     */
    if (error) {
      console.error('Error fetching suppliers:', error);
      showToast(`Не удалось загрузить поставщиков: ${error.message || 'нет связи с базой'}`, 'error');
      setLoadingSuppliers(false);
      if (suppliersRetryRef.current < 2) {
        suppliersRetryRef.current += 1;
        setTimeout(() => { void fetchSuppliers(); }, 4000);
      }
      return;
    }

    suppliersRetryRef.current = 0;
    setSuppliers(data || []);
    if (!(data || []).length) {
      showToast('База ответила, но список поставщиков пуст — проверьте доступ', 'warning');
    }
    setLoadingSuppliers(false);
  };

  // Bind a "Деньги на складе" account (sasha/leha) to a supplier. Each owner can
  // belong to only one supplier; writeoffs then notify that supplier's chat.
  const handleBindSupplierOwner = async (supplierId: string, owner: string | null) => {
    try {
      if (owner) {
        // Release this owner from any other supplier first (unique constraint).
        await supabase.from('suppliers').update({ warehouse_money_owner: null }).eq('warehouse_money_owner', owner);
      }
      const { error } = await supabase.from('suppliers').update({ warehouse_money_owner: owner }).eq('id', supplierId);
      if (error) throw error;
      await fetchSuppliers();
      showToast(owner ? 'Счёт привязан к поставщику' : 'Привязка снята', 'success');
    } catch (e: any) {
      showToast('Ошибка привязки: ' + (e?.message || 'неизвестно'), 'error');
    }
  };

  const handleSupplierSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setSubmittingSupplier(true);
    try {
      if (editingSupplierId) {
        await supabase.from('suppliers').update(supplierForm).eq('id', editingSupplierId);
      } else {
        await supabase.from('suppliers').insert([supplierForm]);
      }
      setSupplierForm({ name: '', telegram_chat_id: '', wb_api_token: '', wb_adv_api_token: '' });
      setEditingSupplierId(null);
      await fetchSuppliers(); // Ensure list is updated
    } catch (error: any) {
      showToast('Ошибка: ' + error.message, 'error');
    } finally {
      setSubmittingSupplier(false);
    }
  };

  const handleEditSupplier = (supplier: Supplier) => {
    setSupplierForm({ name: supplier.name, telegram_chat_id: supplier.telegram_chat_id || '', wb_api_token: supplier.wb_api_token || '', wb_adv_api_token: (supplier as any).wb_adv_api_token || '' });
    setEditingSupplierId(supplier.id);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  const handleDeleteSupplier = async (id: string) => {
    if (!await confirmDialog('Вы уверены?')) return;
    await softDeleteWithActor('suppliers', id);
  };

  // Products Functions
  const fetchProducts = async (supplierId: string = '') => {
    setLoadingProducts(true);
    let query = supabase.from('products').select('*').is('deleted_at', null).order('created_at', { ascending: false });

    if (supplierId) {
      query = query.eq('supplier_id', supplierId);
    }

    const { data, error } = await query;
    if (error) console.error(error);
    else setProducts(data || []);
    setLoadingProducts(false);
  };

  const handleSupplierSelect = (id: string) => {
    setSelectedSupplierId(id);
    setLastImportedIds([]); // Clear undo history on supplier change
    fetchProducts(id || '');
  };

  const checkBarcodeExists = async (barcode: string, supplierId: string) => {
    if (!barcode || !supplierId) return false;
    const { data } = await supabase.from('products').select('id').eq('barcode', barcode).eq('supplier_id', supplierId).maybeSingle();
    return !!data;
  };

  const handleAddProduct = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedSupplierId) return;

    // Check barcode
    if (newProduct.barcode) {
      const exists = await checkBarcodeExists(newProduct.barcode, selectedSupplierId);
      if (exists) {
        showToast(`Товар с баркодом ${newProduct.barcode} уже существует у этого поставщика!`, 'error');
        return;
      }
    }

    const { error } = await supabase.from('products').insert([{
      ...newProduct,
      supplier_id: selectedSupplierId
    }]);

    if (error) showToast('Ошибка: ' + error.message, 'error');
    else {
      showToast('Товар успешно добавлен', 'success');
      setShowAddProductModal(false);
      setNewProduct({ name: '', wb_sku: '', barcode: '', size: '', color: '' });
    }
  };

  const handleDeleteProduct = (product: Product) => {
    setProductToDelete(product);
  };

  const confirmDeleteProduct = async () => {
    if (!productToDelete) return;

    // Delete related supply items first to avoid FK constraint error
    await supabase.from('supply_items').update({ deleted_at: new Date().toISOString() }).eq('product_id', productToDelete.id);

    const { error } = await softDeleteWithActor('products', productToDelete.id);
    if (error) showToast('Ошибка удаления: ' + error.message, 'error');
    else showToast('Товар удален', 'success');
    setProductToDelete(null);
  };

  const getValue = (row: any, keys: string[]) => {
    const rowKeys = Object.keys(row);
    for (const k of keys) {
      const foundKey = rowKeys.find(rk => rk.toLowerCase().trim() === k.toLowerCase().trim());
      if (foundKey) return row[foundKey];
    }
    return '';
  };

  const handleFileUpload = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file || !selectedSupplierId) return;
    const fileSizeError = ensureExcelFileSize(file);
    if (fileSizeError) {
      showToast(fileSizeError, 'error');
      return;
    }

    const buff = await file.arrayBuffer();
    const data = await readFirstSheetAsJson<any>(buff) as any[];
    const rowLimitError = ensureExcelRowLimit(data.length);
    if (rowLimitError) {
      showToast(rowLimitError, 'error');
      return;
    }

    if (!data.length) {
      showToast('Файл пустой', 'error');
      return;
    }

    const productsColumnsError = ensureRequiredColumns(Object.keys(data[0] || {}), [
      { label: 'Barcode', aliases: ['Barcode', 'Баркод', 'Штрихкод'] },
    ]);
    if (productsColumnsError) {
      showToast(productsColumnsError, 'error');
      return;
    }

    try {
      const productsToInsert: any[] = [];
      let duplicatesCount = 0;

      // Fetch all existing barcodes to check against
      const { data: existingProducts } = await supabase.from('products').select('barcode');
      const existingBarcodes = new Set(existingProducts?.map(p => p.barcode).filter(Boolean));

      for (const row of data) {
        const barcode = getValue(row, ['Barcode', 'Баркод', 'barcode', 'Штрихкод']);

        if (barcode && existingBarcodes.has(String(barcode))) {
          duplicatesCount++;
          continue;
        }

        productsToInsert.push({
          supplier_id: selectedSupplierId,
          name: getValue(row, ['Name', 'Наименование', 'name', 'Название']) || 'Unknown',
          wb_sku: getValue(row, ['SKU', 'WB Артикул', 'sku', 'Артикул', 'Артикул WB']),
          barcode: String(barcode || ''),
          size: String(getValue(row, ['Size', 'Размер', 'size', 'Tech Size', 'Размер товара']) || ''),
          color: getValue(row, ['Color', 'Цвет', 'color'])
        });
      }

      if (productsToInsert.length > 0) {
        const { data: insertedData, error } = await supabase
          .from('products')
          .insert(productsToInsert)
          .select('id');

        if (error) {
          showToast('Ошибка импорта: ' + error.message, 'error');
        } else {
          setLastImportedIds(insertedData.map(d => d.id));
          showToast(`Импортировано ${productsToInsert.length} товаров. Пропущено дубликатов: ${duplicatesCount}`, 'success');
        }
      } else {
        showToast(`Нет новых товаров для импорта. Пропущено дубликатов: ${duplicatesCount}`, 'info');
      }

      // Reset file input
      if (fileInputRef.current) fileInputRef.current.value = '';
    } catch (error: any) {
      showToast('Ошибка чтения файла: ' + (error?.message || 'неизвестно'), 'error');
    }
  };

  const handleSyncProductsFromWbCache = async () => {
    if (syncingProductsFromWb) return;

    setSyncingProductsFromWb(true);
    try {
      const { data: suppliersData, error: suppliersError } = await supabase.from('suppliers').select('id');
      if (suppliersError) throw suppliersError;

      const validSuppliers = new Set((suppliersData || []).map((s: any) => s.id));

      const pageSize = 200;
      let from = 0;
      const sourceRows: Array<{ supplier_id: string; product_json: any }> = [];

      while (true) {
        const { data, error } = await supabase
          .from('wb_products_cache')
          .select('supplier_id, product_json')
          .range(from, from + pageSize - 1);

        if (error) throw error;
        const chunk = data || [];
        sourceRows.push(...chunk as any);
        if (chunk.length < pageSize) break;
        from += pageSize;
      }

      const extractColor = (p: any) => {
        const arr = Array.isArray(p?.characteristics) ? p.characteristics : [];
        for (const c of arr) {
          const n = String(c?.name || c?.Name || '').toLowerCase();
          if (n === 'цвет') {
            const v = c?.value ?? c?.Value;
            return Array.isArray(v) ? String(v[0] || '').trim() : String(v || '').trim();
          }
        }
        return '';
      };

      const nextProducts: Array<{ supplier_id: string; name: string; wb_sku: string; barcode: string; size: string; color: string }> = [];

      sourceRows.forEach((row) => {
        const p = row.product_json || {};
        const supplierId = row.supplier_id;
        if (!validSuppliers.has(supplierId)) return;

        const name = String(p.title || '').trim() || 'Unknown';
        const wbSku = String(p.vendorCode || p.nmID || '').trim();
        const color = extractColor(p);
        const sizes = Array.isArray(p.sizes) && p.sizes.length ? p.sizes : [{ techSize: '', wbSize: '', skus: [''] }];

        sizes.forEach((sz: any) => {
          const size = String(sz?.techSize || sz?.wbSize || '').trim();
          const skus = Array.isArray(sz?.skus) && sz.skus.length ? sz.skus : [''];
          skus.forEach((sku: any) => {
            nextProducts.push({
              supplier_id: supplierId,
              name,
              wb_sku: wbSku,
              barcode: String(sku || '').trim(),
              size,
              color,
            });
          });
        });
      });

      const deduped: typeof nextProducts = [];
      const seen = new Set<string>();
      for (const p of nextProducts) {
        const key = `${p.supplier_id}|${p.wb_sku}|${p.barcode}|${p.size}|${p.color}`.toLowerCase();
        if (seen.has(key)) continue;
        seen.add(key);
        deduped.push(p);
      }

      const { error: clearError } = await supabase.from('products').delete().not('id', 'is', null);
      if (clearError) throw clearError;

      const insertChunk = 500;
      for (let i = 0; i < deduped.length; i += insertChunk) {
        const batch = deduped.slice(i, i + insertChunk);
        const { error } = await supabase.from('products').insert(batch);
        if (error) throw error;
      }

      showToast(`Синхронизация завершена: загружено ${deduped.length} товаров из Товары WB`, 'success');
      setLastImportedIds([]);
      await fetchProducts();
    } catch (error: any) {
      showToast(`Ошибка синхронизации из Товары WB: ${error?.message || 'неизвестно'}`, 'error');
    } finally {
      setSyncingProductsFromWb(false);
    }
  };

  const handleUndoImport = async () => {
    if (lastImportedIds.length === 0) return;
    if (!(await confirmDialog({ title: 'Отмена импорта', tone: 'warning', confirmText: 'Отменить импорт', message: 'Отменить последний импорт? Это удалит все добавленные товары.' }))) return;

    const batchSize = 100;
    let hasError = false;

    for (let i = 0; i < lastImportedIds.length; i += batchSize) {
      const batch = lastImportedIds.slice(i, i + batchSize);
      const { error } = await supabase.from('products').delete().in('id', batch);
      if (error) {
        showToast('Ошибка отмены: ' + error.message, 'error');
        hasError = true;
        break;
      }
    }

    if (!hasError) {
      showToast('Импорт отменен', 'success');
      setLastImportedIds([]);
    }
  };

  const handleToggleSupplyLockList = async (supply: Supply) => {
    if (supply.status === 'closed') {
        setSupplyToUnlock(supply);
        setShowUnlockConfirmation(true);
    } else {
        // Lock immediately
        const { error } = await supabase
          .from('supplies')
          .update({ status: 'closed' })
          .eq('id', supply.id);

        if (error) {
          showToast('Ошибка обновления статуса: ' + error.message, 'error');
        } else {
          setSuppliesList(suppliesList.map(s => s.id === supply.id ? { ...s, status: 'closed' } : s));
          if (currentSupply && currentSupply.id === supply.id) {
            setCurrentSupply({ ...currentSupply, status: 'closed' });
          }
          logAction('Блокировка поставки', `Поставка «${supply.name}»`, currentEmployee?.id);
          showToast('Поставка заблокирована', 'success');
        }
    }
  };

  const confirmUnlockSupply = async () => {
    if (!supplyToUnlock) return;

    const { error } = await supabase
      .from('supplies')
      .update({ status: 'active' })
      .eq('id', supplyToUnlock.id);

    if (error) {
      showToast('Ошибка обновления статуса: ' + error.message, 'error');
    } else {
      setSuppliesList(suppliesList.map(s => s.id === supplyToUnlock.id ? { ...s, status: 'active' } : s));
      if (currentSupply && currentSupply.id === supplyToUnlock.id) {
        setCurrentSupply({ ...currentSupply, status: 'active' });
      }
      showToast('Поставка разблокирована', 'success');
      setShowUnlockConfirmation(false);
      setSupplyToUnlock(null);
    }
  };

  // Reception State
  const [receptionStep, setReceptionStep] = useState<'LIST' | 'EDIT'>('LIST');
  const [receptionSupplierId, setReceptionSupplierId] = useState('');
  const [receptionPhotos, setReceptionPhotos] = useState<{id: string, url: string, quantity: string}[]>([]);
  const [sendingReception, setSendingReception] = useState(false);
  const [receptionsList, setReceptionsList] = useState<any[]>([]);
  const [receptionsListAll, setReceptionsListAll] = useState<any[]>([]);
  const [receptionMetaMap, setReceptionMetaMap] = useState<Record<string, { count: number; quantity: number; preview?: string }>>({});
  const [receptionMetaRefreshing, setReceptionMetaRefreshing] = useState(false);
  const [receptionPhotoUploading, setReceptionPhotoUploading] = useState(0);
  const receptionMetaLoadedRef = useRef(false);
  const [currentReception, setCurrentReception] = useState<any | null>(null);
  const [receptionDate, setReceptionDate] = useState(mskTodayYmd());
  const fileInputRefReception = useRef<HTMLInputElement>(null);

  // Telegram Reception Token
  const [telegramReceptionBotToken, setTelegramReceptionBotToken] = useState('');
  const [isReceptionTokenLocked, setIsReceptionTokenLocked] = useState(true);

  // Fetch global settings (tokens)
  useEffect(() => {
    const fetchSettings = async () => {
      const { data, error } = await supabase
        .from('app_settings')
        .select('key, value')
        .in('key', ['telegram_bot_token', 'telegram_reception_bot_token']);

      if (data && !error) {
        const botToken = data.find(s => s.key === 'telegram_bot_token')?.value;
        const receptionToken = data.find(s => s.key === 'telegram_reception_bot_token')?.value;

        if (botToken) setTelegramBotToken(botToken);
        if (receptionToken) setTelegramReceptionBotToken(receptionToken);
      }
    };
    fetchSettings();
  }, []);

  // Removed localStorage effect for telegramReceptionBotToken

  const persistReceptionMeta = useCallback(async (next: Record<string, { count: number; quantity: number; preview?: string }>) => {
    try {
      const raw = JSON.stringify(next || {});
      const { data: updatedRows, error: updateError } = await supabase
        .from('app_settings')
        .update({ value: raw })
        .eq('key', 'reception_meta_v1')
        .select('key');
      if (updateError) throw updateError;
      if (!updatedRows || updatedRows.length === 0) {
        const { error: insertError } = await supabase.from('app_settings').insert({ key: 'reception_meta_v1', value: raw });
        if (insertError) throw insertError;
      }
    } catch (e) {
      console.error('Failed to persist reception meta:', e);
    }
  }, []);

  /*
   * Счётчики приёмок грузим, только когда открыт раздел «Приёмка».
   *
   * Раньше это шло при старте дашборда у каждого сотрудника, а в настройке
   * лежали превью — целые фото в base64, 7 МБ на каждый вход.
   */
  useEffect(() => {
    if (activeTab !== 'reception' || receptionMetaLoadedRef.current) return;
    receptionMetaLoadedRef.current = true;
    const loadReceptionMeta = async () => {
      try {
        const { data } = await supabase.from('app_settings').select('value').eq('key', 'reception_meta_v1').limit(1);
        const row = Array.isArray(data) ? data[0] : null;
        const parsed = row?.value ? (typeof row.value === 'string' ? JSON.parse(row.value) : row.value) : {};
        if (parsed && typeof parsed === 'object') setReceptionMetaMap(parsed as Record<string, { count: number; quantity: number; preview?: string }>);
      } catch {
        // noop
      }
    };
    loadReceptionMeta();
  }, [activeTab]);

  const updateReceptionMetaByPhotos = useCallback((receptionId: string, photos: Array<{ url?: string; quantity?: string }> = []) => {
    setReceptionMetaMap((prev) => {
      const quantity = photos.reduce((sum, p: any) => sum + (parseInt(String(p?.quantity || '0'), 10) || 0), 0);
      const next = {
        ...(prev || {}),
        // Без превью: оно нигде не показывалось, а весило как само фото.
        [receptionId]: { count: photos.length, quantity },
      };
      persistReceptionMeta(next);
      return next;
    });
  }, [persistReceptionMeta]);

  const fillReceptionMetaCounts = useCallback(async (receptionIds: string[]) => {
    if (!receptionIds.length) return;
    try {
      const { data } = await supabase.from('receptions').select('id, photos').in('id', receptionIds as any);
      if (!data) return;
      setReceptionMetaMap((prev) => {
        const next = { ...(prev || {}) };
        (data || []).forEach((row: any) => {
          const photos = Array.isArray(row?.photos) ? row.photos : [];
          const quantity = photos.reduce((sum: number, p: any) => sum + (parseInt(String(p?.quantity || '0'), 10) || 0), 0);
          next[String(row.id)] = { count: photos.length, quantity };
        });
        persistReceptionMeta(next);
        return next;
      });
    } catch (e) {
      console.error('Failed to fetch reception counts:', e);
    }
  }, [persistReceptionMeta]);

  const fetchReceptions = async (supplierId?: string) => {
    const limit = supplierId ? 80 : 120;

    const run = async (selectClause: string) => {
      let q = supabase
        .from('receptions')
        .select(selectClause)
        .is('deleted_at', null)
        .order('created_at', { ascending: false })
        .limit(limit);
      if (supplierId) q = q.eq('supplier_id', supplierId);
      return q;
    };

    // 1) Preferred fast query with stats + supplier name
    let result = await run('id, supplier_id, status, created_at, updated_at, photos_count, items_quantity, supplier:suppliers(name)');

    // 2) Fallback without stats columns
    if (result.error) {
      result = await run('id, supplier_id, status, created_at, updated_at, supplier:suppliers(name)');
    }

    // 3) Hard fallback without relation join (in case FK/relation issue)
    if (result.error) {
      result = await run('id, supplier_id, status, created_at, updated_at');
    }

    if (result.error) {
      console.error('Error fetching receptions:', result.error);
      showToast('Ошибка загрузки истории приемок: ' + (result.error.message || 'неизвестно'), 'error');
      setReceptionsList([]);
      if (!supplierId) setReceptionsListAll([]);
      return;
    }

    const rows = result.data || [];
    if (!supplierId) {
      setReceptionsListAll(rows);
      setReceptionsList(rows);
      return;
    }

    if (receptionsListAll.length > 0) {
      setReceptionsList(receptionsListAll.filter((r: any) => String(r.supplier_id) === String(supplierId)));
    }
    setReceptionsList(rows);
  };

  useEffect(() => {
    if (activeTab === 'reception') fetchReceptions(receptionSupplierId);
  }, [activeTab, receptionSupplierId]);

  const refreshVisibleReceptionMeta = useCallback(async () => {
    const ids = (receptionsList || []).map((r: any) => String(r.id || '')).filter(Boolean).slice(0, 25);
    if (!ids.length) return;
    setReceptionMetaRefreshing(true);
    try {
      const patch: Record<string, { count: number; quantity: number; preview?: string }> = {};
      // Single query for all visible receptions instead of one request per id (N+1).
      const { data: rows } = await supabase.from('receptions').select('id, photos').in('id', ids); // photos — лишь ссылки
      (rows || []).forEach((row: any) => {
        const id = String(row?.id || '');
        if (!id) return;
        const photos = Array.isArray(row?.photos) ? row.photos : [];
        const quantity = photos.reduce((sum: number, p: any) => sum + (parseInt(String(p?.quantity || '0'), 10) || 0), 0);
        patch[id] = { count: photos.length, quantity };
      });

      if (Object.keys(patch).length > 0) {
        setReceptionMetaMap((prev) => {
          const next = { ...(prev || {}), ...patch };
          persistReceptionMeta(next);
          return next;
        });
      }
    } finally {
      setReceptionMetaRefreshing(false);
    }
  }, [receptionsList, persistReceptionMeta]);

  const handleCreateReception = async () => {
    if (!receptionSupplierId) {
      showToast('Выберите поставщика', 'error');
      return;
    }

    let { data, error } = await supabase.from('receptions').insert([{
      supplier_id: receptionSupplierId,
      status: 'active',
      photos: [],
      photos_count: 0,
      items_quantity: 0,
    } as any]).select('*, supplier:suppliers(name)').single();

    if (error && String((error as any)?.message || '').includes('photos_count')) {
      const fallback = await supabase.from('receptions').insert([{
        supplier_id: receptionSupplierId,
        status: 'active',
        photos: []
      }]).select('*, supplier:suppliers(name)').single();
      data = fallback.data as any;
      error = fallback.error as any;
    }

    if (error) {
      showToast('Ошибка создания: ' + error.message, 'error');
      return;
    }

    setCurrentReception(data);
    setReceptionPhotos([]);
    setReceptionDate(data?.created_at ? mskYmd(new Date(data.created_at)) : mskTodayYmd());
    setReceptionStep('EDIT');
    updateReceptionMetaByPhotos(data.id, [] as any);
    await logAssemblyChange('receptions', 'create', null, data);
  };

  const handleOpenReception = async (reception: any) => {
    // Open immediately with whatever is already in list (including photos when supplier selected)
    setCurrentReception(reception);
    setReceptionSupplierId(reception.supplier_id);
    setReceptionDate(reception?.created_at ? mskYmd(new Date(reception.created_at)) : mskTodayYmd());
    setReceptionPhotos(Array.isArray(reception?.photos) ? reception.photos : []);
    setReceptionStep('EDIT');

    // Refresh full object in background
    const { data } = await supabase
      .from('receptions')
      .select('*, supplier:suppliers(name)')
      .eq('id', reception.id)
      .maybeSingle();

    if (data) {
      setCurrentReception(data);
      setReceptionPhotos(data.photos || []);
      setReceptionDate(data?.created_at ? mskYmd(new Date(data.created_at)) : mskTodayYmd());
      updateReceptionMetaByPhotos(String(data.id), Array.isArray(data.photos) ? data.photos : []);
    }
  };

  const calcReceptionStats = (photos: Array<{ quantity?: string }> = []) => {
    const photosCount = photos.length;
    const itemsQuantity = photos.reduce((sum: number, p: any) => sum + (parseInt(String(p?.quantity || '0'), 10) || 0), 0);
    return { photosCount, itemsQuantity };
  };

  const handleSaveReception = async () => {
    if (!currentReception) return;

    const normalizedReceptionDate = receptionDate && /^\d{4}-\d{2}-\d{2}$/.test(receptionDate)
      ? new Date(`${receptionDate}T12:00:00`).toISOString()
      : currentReception.created_at;

    const stats = calcReceptionStats(receptionPhotos as any);

    let { error } = await supabase.from('receptions').update({
      photos: receptionPhotos,
      photos_count: stats.photosCount,
      items_quantity: stats.itemsQuantity,
      created_at: normalizedReceptionDate,
      updated_at: new Date().toISOString()
    } as any).eq('id', currentReception.id);

    if (error && String((error as any)?.message || '').includes('photos_count')) {
      const fallback = await supabase.from('receptions').update({
        photos: receptionPhotos,
        created_at: normalizedReceptionDate,
        updated_at: new Date().toISOString()
      }).eq('id', currentReception.id);
      error = fallback.error;
    }

    if (error) {
      showToast('Ошибка сохранения: ' + error.message, 'error');
    } else {
      const before = { ...currentReception };
      const after = { ...currentReception, created_at: normalizedReceptionDate, photos: receptionPhotos, photos_count: stats.photosCount, items_quantity: stats.itemsQuantity };
      setCurrentReception((prev: any) => prev ? { ...prev, created_at: normalizedReceptionDate, photos: receptionPhotos } : prev);
      setReceptionsList(prev => prev.map(r => r.id === currentReception.id ? { ...r, created_at: normalizedReceptionDate, photos: receptionPhotos } : r));
      updateReceptionMetaByPhotos(currentReception.id, receptionPhotos as any);
      await logAssemblyChange('receptions', 'update', before, after);
      showToast('Сохранено', 'success');
    }
  };

  /**
   * Фото приёмки — в хранилище файлов, в строку приёмки идёт только ссылка.
   *
   * Раньше фото ложилось в базу base64: приёмки занимали 92 МБ, одна открывалась
   * до 10 МБ, и каждое сохранение копировало все фото ещё и в журнал действий.
   * Снимок с телефона ужимаем до 2000 px — для сверки количества этого хватает.
   */
  const shrinkReceptionPhoto = async (file: File): Promise<{ blob: Blob; ext: string; type: string }> => {
    try {
      const bitmap = await createImageBitmap(file);
      const scale = Math.min(1, 2000 / Math.max(bitmap.width, bitmap.height));
      const canvas = document.createElement('canvas');
      canvas.width = Math.round(bitmap.width * scale);
      canvas.height = Math.round(bitmap.height * scale);
      canvas.getContext('2d')!.drawImage(bitmap, 0, 0, canvas.width, canvas.height);
      bitmap.close?.();
      const blob = await new Promise<Blob | null>((resolve) => canvas.toBlob(resolve, 'image/jpeg', 0.85));
      if (blob && blob.size < file.size) return { blob, ext: 'jpg', type: 'image/jpeg' };
    } catch {
      // формат, который браузер не декодирует (например HEIC), — грузим как есть
    }
    const ext = (file.name.split('.').pop() || 'jpg').toLowerCase().replace(/[^a-z0-9]/g, '') || 'jpg';
    return { blob: file, ext, type: file.type || 'image/jpeg' };
  };

  const handleReceptionPhoto = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const input = e.target;
    const files = Array.from(input.files || []);
    input.value = '';
    if (!files.length) return;

    const receptionId = String(currentReception?.id || 'no-reception');
    setReceptionPhotoUploading((n) => n + files.length);
    for (const file of files) {
      const id = Math.random().toString(36).slice(2, 11);
      try {
        const { blob, ext, type } = await shrinkReceptionPhoto(file);
        const objectPath = `${receptionId}/${Date.now()}-${id}.${ext}`;
        const { error } = await supabase.storage
          .from('reception-photos')
          .upload(objectPath, blob, { contentType: type, cacheControl: '31536000', upsert: false });
        if (error) throw error;
        const url = supabase.storage.from('reception-photos').getPublicUrl(objectPath).data.publicUrl;
        setReceptionPhotos((prev) => [...prev, { id, url, quantity: '' }]);
      } catch (err: any) {
        showToast(`Фото «${file.name}» не загрузилось: ${err?.message || 'ошибка сети'}`, 'error');
      } finally {
        setReceptionPhotoUploading((n) => Math.max(0, n - 1));
      }
    }
  };

  const sendCurrentReceptionToTelegram = async (supplierInput?: any) => {
    if (receptionPhotos.length === 0) {
      showToast('Добавьте хотя бы одно фото', 'error');
      return;
    }

    const supplier = supplierInput || suppliers.find(s => s.id === receptionSupplierId) || currentReception?.supplier;
    if (!supplier) {
      showToast('Поставщик не найден', 'error');
      return;
    }

    let chatId = supplier.telegram_chat_id;
    if (!chatId) {
      const { data } = await supabase.from('suppliers').select('telegram_chat_id').eq('id', receptionSupplierId).single();
      chatId = data?.telegram_chat_id;
    }

    if (!chatId) {
      showToast('У поставщика нет Telegram Chat ID', 'error');
      return;
    }

    let token = String(telegramReceptionBotToken || '').trim();
    if (!token) {
        const { data } = await supabase.from('app_settings').select('value').eq('key', 'telegram_reception_bot_token').maybeSingle();
        if (data?.value) {
            token = String(data.value).trim();
            setTelegramReceptionBotToken(token);
        }
    }
    if (!token) token = String(telegramBotToken || '').trim();
    if (!token) {
      showToast('Не настроен токен бота для приемки', 'error');
      return;
    }

    let totalQuantity = 0;
    for (const photo of receptionPhotos) {
      const qty = parseInt(photo.quantity) || 0;
      totalQuantity += qty;
      const res = await fetch(photo.url);
      const blob = await res.blob();
      await telegramService.sendPhoto(token, String(chatId), blob, `Количество: ${qty} шт`);
    }

    const receptionDateText = receptionDate && /^\d{4}-\d{2}-\d{2}$/.test(receptionDate)
      ? new Date(`${receptionDate}T12:00:00`).toLocaleDateString('ru-RU')
      : new Date().toLocaleDateString('ru-RU');
    const text = `Приемка товаров на склад\nПоставщик: ${supplier.name}\nДата: ${receptionDateText}\nИтого товара: ${totalQuantity} шт`;
    await telegramService.sendMessage(token, String(chatId), text);
  };

  const handleFinishReception = async () => {
    if (receptionPhotos.length === 0) {
      showToast('Добавьте хотя бы одно фото', 'error');
      return;
    }

    const supplier = suppliers.find(s => s.id === receptionSupplierId) || currentReception?.supplier;
    if (!supplier) {
      showToast('Поставщик не найден', 'error');
      return;
    }

    setSendingReception(true);
    try {
      // 1. Save to DB first
      const normalizedReceptionDate = receptionDate && /^\d{4}-\d{2}-\d{2}$/.test(receptionDate)
        ? new Date(`${receptionDate}T12:00:00`).toISOString()
        : currentReception.created_at;

      const stats = calcReceptionStats(receptionPhotos as any);

      let closeRes = await supabase.from('receptions').update({
        photos: receptionPhotos,
        photos_count: stats.photosCount,
        items_quantity: stats.itemsQuantity,
        status: 'closed',
        created_at: normalizedReceptionDate,
        updated_at: new Date().toISOString()
      } as any).eq('id', currentReception.id);

      if (closeRes.error && String((closeRes.error as any)?.message || '').includes('photos_count')) {
        closeRes = await supabase.from('receptions').update({
          photos: receptionPhotos,
          status: 'closed',
          created_at: normalizedReceptionDate,
          updated_at: new Date().toISOString()
        }).eq('id', currentReception.id);
      }

      updateReceptionMetaByPhotos(currentReception.id, receptionPhotos as any);

      await logAction('Приемка', `Завершена приемка от ${supplier.name}`, currentEmployee?.id);
      await logAssemblyChange('receptions', 'update', currentReception, {
        ...currentReception,
        status: 'closed',
        created_at: normalizedReceptionDate,
        photos: receptionPhotos,
        photos_count: stats.photosCount,
        items_quantity: stats.itemsQuantity,
        supplier_name: supplier.name,
      });

      // 2. Send to Telegram
      await sendCurrentReceptionToTelegram(supplier);

      showToast('Приемка завершена и отправлена', 'success');
      setReceptionPhotos([]);
      setReceptionSupplierId('');
      setCurrentReception(null);
      setReceptionDate(mskTodayYmd());
      setReceptionStep('LIST');
      fetchReceptions();
    } catch (error: any) {
      showToast('Ошибка: ' + error.message, 'error');
    } finally {
      setSendingReception(false);
    }
  };

  const handleOpenSupplierHistory = async (supplier: Supplier, type: 'supplies' | 'receptions' = 'supplies') => {
    setHistorySupplier(supplier);
    setHistoryType(type);
    setShowSupplierHistory(true);

    if (type === 'supplies') {
      const { data } = await supabase.from('supplies').select('*').eq('supplier_id', supplier.id).order('created_at', { ascending: false });

      if (data) {
        // Single server-side aggregation instead of an N+1 (boxes + supply_items per supply).
        const countsBySupply = new Map<string, number>();
        const { data: counts, error: countsError } = await supabase
          .rpc('supplier_supply_item_counts', { p_supplier_id: supplier.id });
        if (!countsError && Array.isArray(counts)) {
          for (const row of counts as Array<{ supply_id: string; total_items: number }>) {
            countsBySupply.set(String(row.supply_id), Number(row.total_items) || 0);
          }
        }
        setHistorySupplies(data.map((s) => ({ ...s, total_items: countsBySupply.get(String(s.id)) || 0 })));
      } else {
        setHistorySupplies([]);
      }
    } else {
      const { data } = await supabase
        .from('receptions')
        .select('id, supplier_id, status, created_at, updated_at')
        .eq('supplier_id', supplier.id)
        .order('created_at', { ascending: false })
        .limit(150);
      setHistoryReceptions(data || []);
    }
  };

