  const BARTER_PUBLISHED_FLAGS_KEY = 'barter_published_flags_v1';

  const loadBarterPublishedFlags = async () => {
    const { data, error } = await supabase
      .from('app_settings')
      .select('value')
      .eq('key', BARTER_PUBLISHED_FLAGS_KEY)
      .maybeSingle();
    if (error) return {};
    try {
      const parsed = data?.value ? (typeof data.value === 'string' ? JSON.parse(String(data.value)) : data.value) : {};
      return parsed && typeof parsed === 'object' ? parsed : {};
    } catch {
      return {};
    }
  };

  const applyBarterPublishedFlags = (rowsInput: any[], flagsInput: any) => (rowsInput || []).map((row: any) => {
    const flags = flagsInput?.[String(row?.id || '')] || {};
    return normalizeBarterRow({
      ...row,
      barter_published: Array.isArray(row?.barter_published) && row.barter_published.some(Boolean) ? row.barter_published : flags?.barter_published,
      ad_published: Array.isArray(row?.ad_published) && row.ad_published.some(Boolean) ? row.ad_published : flags?.ad_published,
    });
  });

  const saveBarterPublishedFlags = async (rowsInput: any[]) => {
    try {
      const existing = await loadBarterPublishedFlags();
      const next = { ...(existing || {}) };
      (rowsInput || []).forEach((row: any) => {
        const id = String(row?.id || '').trim();
        if (!id) return;
        next[id] = {
          barter_published: Array.isArray(row?.barter_published) ? row.barter_published.map(Boolean) : [],
          ad_published: Array.isArray(row?.ad_published) ? row.ad_published.map(Boolean) : [],
        };
      });
      await supabase.from('app_settings').upsert([{ key: BARTER_PUBLISHED_FLAGS_KEY, value: JSON.stringify(next) }], { onConflict: 'key' });
    } catch (e) {
      console.warn('saveBarterPublishedFlags failed', e);
    }
  };

  const stripBarterPublishedDbFields = (row: any) => {
    const { barter_published, ad_published, ...rest } = row || {};
    return rest;
  };

  const isBarterPublishedColumnError = (error: any) => /barter_published|ad_published|schema cache|column/i.test(String(error?.message || ''));

  const mergeBarterRowsIntoSingle = (rows: any[], options?: { barterExtra?: number; adExtra?: number }) => {
    const sourceRows = (rows || []).filter(Boolean);
    if (!sourceRows.length) return null;
    const base = sourceRows[0] || {};
    const baseBarterSize = 5 + Number(options?.barterExtra ?? barterGlobalExtra ?? 0);
    const baseAdSize = 2 + Number(options?.adExtra ?? adGlobalExtra ?? 0);
    const productIds = Array.from(new Set(sourceRows.flatMap((row: any) => {
      if (Array.isArray(row?.product_ids) && row.product_ids.length) return row.product_ids.map((id: any) => String(id || '')).filter(Boolean);
      return [String(row?.product_id || '')].filter(Boolean);
    })));
    const variantLabels = Array.from(new Set(sourceRows.flatMap((row: any) => {
      if (Array.isArray(row?.product_variant_labels) && row.product_variant_labels.length) return row.product_variant_labels.map((label: any) => String(label || '')).filter(Boolean);
      const fallback = getBarterVariantLabel(row);
      return fallback ? [fallback] : [];
    })));
    const productPhotos = Array.from(new Set(sourceRows.flatMap((row: any) => {
      const photos = Array.isArray(row?.product_photos) && row.product_photos.length
        ? row.product_photos
        : [row?.product_photo];
      return photos.map((photo: any) => normalizeBarterPhotoUrl(photo)).filter(Boolean);
    })));
    const productPhoto = productPhotos[0] || sourceRows.map((row: any) => normalizeBarterPhotoUrl(row?.product_photo || '')).find(Boolean) || '';
    const uniqueNames = Array.from(new Set(sourceRows.map((row: any) => String(row?.product_name || getBarterProductGroupName(row) || '').trim()).filter(Boolean)));
    const displayName = uniqueNames[0] || getBarterProductGroupName(base);
    return {
      ...base,
      id: getSafeId(),
      month: String(base?.month || currentBarterMonth),
      supplier_id: String(base?.supplier_id || ''),
      supplier_name: String(base?.supplier_name || 'Поставщик'),
      product_id: String(productIds[0] || base?.product_id || ''),
      product_name: displayName,
      product_group_key: getBarterProductGroupKey(base),
      product_group_name: displayName,
      product_photo: productPhoto,
      product_photos: productPhotos,
      product_ids: productIds,
      product_variant_labels: variantLabels,
      product_variants_count: Math.max(sourceRows.length, productIds.length, variantLabels.length, 1),
      ...mergeBarterSlotFields(sourceRows, 'barter', baseBarterSize),
      ...mergeBarterSlotFields(sourceRows, 'ad', baseAdSize),
    };
  };

  /*
   * «Живая синхронизация между устройствами» удалена 13.09.2026.
   *
   * Канал подписывался на 15 таблиц, 6 из которых в realtime не включены, и
   * поэтому не регистрировался вовсе: в realtime.subscription его не было ни
   * разу, то есть он не работал. Будь он рабочим, было бы хуже: на каждое
   * изменение любой из таблиц, включая отметку «онлайн» раз в 45 секунд и
   * запись сканов в app_settings, все открытые вкладки перезапрашивали бы
   * поставщиков и сотрудников. Нужные живые обновления остались точечными:
   * поставщики, сотрудники, задачи.
   */

  // Global Scan Listener for NEW_BOX
  useEffect(() => {
    let buffer = '';
    let lastKeyTime = Date.now();

    const handleGlobalScan = (e: KeyboardEvent) => {
      const char = e.key;
      const now = Date.now();

      if (now - lastKeyTime > 100) {
        buffer = '';
      }
      lastKeyTime = now;

      if (char === 'Enter') {
        let code = buffer;
        if (/[\p{Script=Cyrillic}]/u.test(code)) {
            code = fixLayout(code);
        }

        if (tryHandleWorkerBadge(code)) { buffer = ''; return; }

        // Check for Supplier QR
        const supplierId = code.startsWith('SUPPLIER:') ? code.split(':')[1] : code;
        const supplier = suppliers.find(s => s.id === supplierId);

        if (supplier) {
            switchTab('supplies');
            setSelectedSupplierId(supplier.id);
            setSupplyStep('LIST');
            showToast(`Выбран поставщик: ${supplier.name}`, 'success');
            buffer = '';
            return;
        }

        if (code.trim() === 'ACTION:NEW_BOX' || code.includes('NEW_BOX') || code.includes('ACTION;NEW_BOX')) {
           setSupplyStep('SUPPLY');
           setCurrentBox(null);
           setScannedItem(null);
           setShowNewBoxQR(false);
           if (itemInputRef.current) itemInputRef.current.value = '';
           if (honestSignInputRef.current) honestSignInputRef.current.value = '';
           showToast('Коробка закрыта (QR)', 'success');
        }
        if (code.trim() === 'ACTION:GENERATE_BOX' || code.includes('GENERATE_BOX') || code.includes('ACTION;GENERATE_BOX')) {
           setShowGenerateBoxQR(false);
           createNextBoxInCurrentSupply().catch((err) => console.error('QR generate box failed', err));
        }
        buffer = '';
      } else if (char.length === 1) {
        buffer += char;
      }
    };

    window.addEventListener('keydown', handleGlobalScan);
    return () => window.removeEventListener('keydown', handleGlobalScan);
  }, [suppliers, employees, activeScannerEmployee]);

  useEffect(() => {
    if (activeTab !== 'completed' || employees.length === 0) return;

    const currentId = String(currentEmployee?.id || '').trim();
    const currentRole = String(currentEmployee?.role || currentEmployee?.login || '').toLowerCase();
    const isCurrentAdmin = currentRole === 'admin';

    // For non-admin employees, auto-pick themselves in calendar/form.
    if (currentId && !isCurrentAdmin) {
      const me = employees.find(e => String(e.id) === currentId);
      if (me && String(cwSelectedEmployee?.id || '') !== String(me.id)) {
        setCwSelectedEmployee(me);
      }
      return;
    }

    // Fallback: first non-admin employee.
    if (!cwSelectedEmployee) {
      const eligible = employees.find(e => String(e.role || '').toLowerCase() !== 'admin' && String(e.login || '').toLowerCase() !== 'admin');
      if (eligible) setCwSelectedEmployee(eligible);
    }
  }, [activeTab, employees, cwSelectedEmployee, currentEmployee]);

  // Sync selected employee with updated employees list
  useEffect(() => {
    if (cwSelectedEmployee && employees.length > 0) {
      const updated = employees.find(e => e.id === cwSelectedEmployee.id);
      if (updated && updated !== cwSelectedEmployee) {
        setCwSelectedEmployee(updated);
      }
    }
  }, [employees, cwSelectedEmployee]);

  const parseLoginDevice = (details: string) => {
    try {
      const parsed = JSON.parse(details || '{}');
      if (parsed?.kind === 'login_device') return parsed;
      return null;
    } catch {
      return null;
    }
  };

  useEffect(() => {
    if (!showDevicesModal) return;
    const loadDevices = async () => {
      try {
        setLoadingEmployeeDevices(true);
        const { data } = await supabase
          .from('activity_logs')
          .select('id, details, created_at')
          .eq('employee_id', showDevicesModal.id)
          .eq('action', 'Вход в систему')
          .order('created_at', { ascending: false })
          .limit(100);

        const rawList = (data || []).map((row: any) => {
          const meta = parseLoginDevice(row.details || '');
          return {
            id: row.id,
            created_at: row.created_at,
            session_id: meta?.session_id || '',
            device_id: meta?.device_id || '',
            platform: meta?.platform || '-',
            browser: meta?.browser || '-',
            ip: meta?.ip || '-',
          };
        });
        const seen = new Set<string>();
        const list = rawList.filter((d: any) => {
          const key = String(d.device_id || `${d.platform}|${d.browser}|${d.ip}`);
          if (seen.has(key)) return false;
          seen.add(key);
          return true;
        });
        setEmployeeDevices(list);
      } finally {
        setLoadingEmployeeDevices(false);
      }
    };
    loadDevices();
  }, [showDevicesModal]);

  const revokeEmployeeDeviceSession = async (employeeId: string, sessionId: string) => {
    if (!sessionId) return;
    try {
      setRevokingDeviceSessionId(sessionId);
      const key = 'revoked_employee_sessions_v1';
      const { data: row } = await supabase.from('app_settings').select('value').eq('key', key).maybeSingle();
      let map: Record<string, string[]> = {};
      try { map = row?.value ? JSON.parse(String(row.value)) : {}; } catch {}
      const current = Array.isArray(map[employeeId]) ? map[employeeId] : [];
      if (!current.includes(sessionId)) current.push(sessionId);
      map[employeeId] = current;

      const { error } = await supabase.from('app_settings').upsert([{ key, value: JSON.stringify(map) }], { onConflict: 'key' });
      if (error) throw error;

      showToast('Сессия устройства завершена', 'success');
      await logAction('Завершение сессии устройства', `Сотрудник ${showDevicesModal?.full_name || employeeId}, session: ${sessionId}`, currentEmployee?.id);
    } catch (e: any) {
      showToast('Ошибка завершения сессии: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setRevokingDeviceSessionId(null);
    }
  };

  const revokeEmployeeDevice = async (employeeId: string, deviceId: string) => {
    if (!deviceId) return;
    try {
      setRevokingDeviceSessionId(deviceId);
      const key = 'revoked_employee_devices_v1';
      const { data: row } = await supabase.from('app_settings').select('value').eq('key', key).maybeSingle();
      let map: Record<string, string[]> = {};
      try { map = row?.value ? JSON.parse(String(row.value)) : {}; } catch {}
      const current = Array.isArray(map[employeeId]) ? map[employeeId] : [];
      if (!current.includes(deviceId)) current.push(deviceId);
      map[employeeId] = current;
      const { error } = await supabase.from('app_settings').upsert([{ key, value: JSON.stringify(map) }], { onConflict: 'key' });
      if (error) throw error;
      showToast('Устройство завершено', 'success');
      await logAction('Завершение устройства', `Сотрудник ${showDevicesModal?.full_name || employeeId}, device: ${deviceId}`, currentEmployee?.id);
    } catch (e: any) {
      showToast('Ошибка завершения устройства: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setRevokingDeviceSessionId(null);
    }
  };

  const clearEmptyDeviceLogs = async (employeeId: string) => {
    try {
      setLoadingEmployeeDevices(true);
      const { data } = await supabase
        .from('activity_logs')
        .select('id, details')
        .eq('employee_id', employeeId)
        .eq('action', 'Вход в систему')
        .order('created_at', { ascending: false })
        .limit(300);

      const toDelete = (data || []).filter((row: any) => {
        const meta = parseLoginDevice(String(row?.details || ''));
        if (!meta) return true; // old plain-string entries
        const hasUseful = Boolean(meta?.device_id || meta?.session_id || meta?.platform || meta?.browser);
        return !hasUseful;
      }).map((r: any) => r.id);

      if (!toDelete.length) {
        showToast('Пустых входов не найдено', 'info');
        return;
      }

      const { error } = await supabase.from('activity_logs').delete().in('id', toDelete as any);
      if (error) throw error;

      showToast(`Удалено пустых входов: ${toDelete.length}`, 'success');

      const { data: fresh } = await supabase
        .from('activity_logs')
        .select('id, details, created_at')
        .eq('employee_id', employeeId)
        .eq('action', 'Вход в систему')
        .order('created_at', { ascending: false })
        .limit(100);
      const rawList = (fresh || []).map((row: any) => {
        const meta = parseLoginDevice(row.details || '');
        return {
          id: row.id,
          created_at: row.created_at,
          session_id: meta?.session_id || '',
          device_id: meta?.device_id || '',
          platform: meta?.platform || '-',
          browser: meta?.browser || '-',
          ip: meta?.ip || '-',
        };
      });
      const seen = new Set<string>();
      const list = rawList.filter((d: any) => {
        const key = String(d.device_id || `${d.platform}|${d.browser}|${d.ip}`);
        if (seen.has(key)) return false;
        seen.add(key);
        return true;
      });
      setEmployeeDevices(list);
    } catch (e: any) {
      showToast('Ошибка очистки: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setLoadingEmployeeDevices(false);
    }
  };

  useEffect(() => {
    const employeeId = String(currentEmployee?.id || '');
    const sessionId = String(localStorage.getItem('employee_session_id') || '');
    const deviceId = String(localStorage.getItem('employee_device_id') || '');
    if (!employeeId || (!sessionId && !deviceId)) return;

    let mounted = true;
    const forceLogout = () => {
      localStorage.removeItem('current_employee');
      localStorage.removeItem('employee_session_id');
      localStorage.removeItem('employee_device_id');
      window.location.href = '/login';
    };

    const check = async () => {
      try {
        // Один запрос на оба ключа вместо двух.
        const { data: rows } = await supabase
          .from('app_settings')
          .select('key, value')
          .in('key', ['revoked_employee_sessions_v1', 'revoked_employee_devices_v1']);
        const rowSessions = (rows || []).find((r: any) => r.key === 'revoked_employee_sessions_v1');
        const rowDevices = (rows || []).find((r: any) => r.key === 'revoked_employee_devices_v1');

        let mapSessions: Record<string, string[]> = {};
        let mapDevices: Record<string, string[]> = {};
        try { mapSessions = rowSessions?.value ? JSON.parse(String(rowSessions.value)) : {}; } catch {}
        try { mapDevices = rowDevices?.value ? JSON.parse(String(rowDevices.value)) : {}; } catch {}

        const revokedSessions = Array.isArray(mapSessions[employeeId]) ? mapSessions[employeeId] : [];
        const revokedDevices = Array.isArray(mapDevices[employeeId]) ? mapDevices[employeeId] : [];

        if (mounted && ((sessionId && revokedSessions.includes(sessionId)) || (deviceId && revokedDevices.includes(deviceId)))) {
          forceLogout();
        }
      } catch {}
    };

    /*
     * Раз в 10 минут и при каждом возврате во вкладку.
     *
     * Раньше — раз в минуту двумя запросами: 9,5 тысячи обращений в сутки
     * (22% трафика, замер 13.09.2026) к настройкам, которых в базе даже не
     * было — сеанс ни разу не отзывали. Отозванного сотрудника выкинет, как
     * только он вернётся к вкладке, а в фоне — не позже чем через 10 минут.
     */
    const onVisible = () => {
      if (document.visibilityState === 'visible') void check();
    };
    check();
    const t = setInterval(onVisible, 10 * 60_000);
    document.addEventListener('visibilitychange', onVisible);
    return () => {
      mounted = false;
      clearInterval(t);
      document.removeEventListener('visibilitychange', onVisible);
    };
  }, [currentEmployee?.id]);

  useEffect(() => {
    const loadExternalAdsBase = async () => {
      try {
        const { data } = await supabase.from('app_settings').select('value').eq('key', 'external_ads_base_v1').maybeSingle();
        if (data?.value) {
          const parsed = typeof data.value === 'string' ? JSON.parse(data.value) : data.value;
          const rows = Array.isArray(parsed) ? parsed : (Array.isArray(parsed?.rows) ? parsed.rows : []);
          setExternalAdsBase((rows || []).map((r: any, idx: number) => ({
            id: String(r?.id || `ext-ads-${idx}-${Date.now()}`),
            nickname: String(r?.nickname || ''),
            socialLinks: Array.isArray(r?.socialLinks) && r.socialLinks.length
              ? r.socialLinks.map((s: any) => ({
                  url: String(s?.url || ''),
                  followers: String(s?.followers || ''),
                  platform: String(s?.platform || parseExternalBloggerLink(String(s?.url || ''))?.platform || ''),
                }))
              : [{ url: '', followers: '', platform: '' }],
            history: Array.isArray(r?.history)
              ? r.history.map((h: any, historyIdx: number) => ({
                  id: String(h?.id || `ext-ads-history-${idx}-${historyIdx}`),
                  kind: String(h?.kind || 'barter') === 'ad' ? 'ad' : 'barter',
                  supplier_id: String(h?.supplier_id || ''),
                  supplier_name: String(h?.supplier_name || ''),
                  product_id: String(h?.product_id || ''),
                  product_name: String(h?.product_name || ''),
                  month: String(h?.month || ''),
                  url: String(h?.url || ''),
                  normalizedUrl: String(h?.normalizedUrl || normalizeExternalUrl(String(h?.url || ''))),
                  platform: String(h?.platform || parseExternalBloggerLink(String(h?.url || ''))?.platform || ''),
                  date: String(h?.date || ''),
                  price: String(h?.price || ''),
                  views: String(h?.views || ''),
                  rating: String(h?.rating || ''),
                  published: Boolean(h?.published || h?.is_published || h?.done),
                  createdAt: String(h?.createdAt || r?.createdAt || new Date().toISOString()),
                }))
              : [],
            overallRating: String(r?.overallRating || ''),
            comment: String(r?.comment || ''),
            status: normalizeExternalAdsStatus(String(r?.status || 'new')),
            createdAt: String(r?.createdAt || new Date().toISOString()),
          })));
        }
      } catch {}
    };
    loadExternalAdsBase();
  }, []);

  const saveExternalAdsBase = async (rows: ExternalAdsBaseEntry[]) => {
    try {
      setExternalAdsBaseSaving(true);
      const normalizedRows = (rows || []).map((row) => ({
        ...row,
        nickname: String(row?.nickname || '').trim(),
        socialLinks: (row?.socialLinks || [])
          .map((social) => ({
            url: String(social?.url || '').trim(),
            followers: String(social?.followers || '').trim(),
            platform: String(social?.platform || parseExternalBloggerLink(String(social?.url || ''))?.platform || ''),
          }))
          .filter((social) => social.url || social.followers),
        history: (row?.history || [])
          .map((history) => ({
            ...history,
            id: String(history?.id || getSafeId()),
            kind: String(history?.kind || 'barter') === 'ad' ? 'ad' : 'barter',
            supplier_id: String(history?.supplier_id || ''),
            supplier_name: String(history?.supplier_name || ''),
            product_id: String(history?.product_id || ''),
            product_name: String(history?.product_name || ''),
            month: String(history?.month || ''),
            url: String(history?.url || '').trim(),
            normalizedUrl: String(history?.normalizedUrl || normalizeExternalUrl(String(history?.url || ''))),
            platform: String(history?.platform || parseExternalBloggerLink(String(history?.url || ''))?.platform || ''),
            date: String(history?.date || ''),
            price: String(history?.price || ''),
            views: String(history?.views || ''),
            rating: String(history?.rating || ''),
            published: Boolean(history?.published),
            createdAt: String(history?.createdAt || row?.createdAt || new Date().toISOString()),
          }))
          .sort((a, b) => String(b.date || b.createdAt || '').localeCompare(String(a.date || a.createdAt || ''))),
        overallRating: String(row?.overallRating || '').trim(),
        status: normalizeExternalAdsStatus(String(row?.status || 'new')),
      }));
      const payload = { rows: normalizedRows };
      const { error } = await supabase.from('app_settings').upsert([{ key: 'external_ads_base_v1', value: JSON.stringify(payload) }], { onConflict: 'key' });
      if (error) throw error;
      setExternalAdsBase(normalizedRows);
      return true;
    } catch (e: any) {
      showToast('Ошибка сохранения базы внешней рекламы: ' + (e?.message || 'неизвестно'), 'error');
      return false;
    } finally {
      setExternalAdsBaseSaving(false);
    }
  };

  const filteredExternalAdsBase = useMemo(() => {
    const q = externalAdsBaseSearch.trim().toLowerCase();
    const platformFilter = String(externalAdsBasePlatformFilter || 'all');
    const supplierFilter = String(externalAdsBaseSupplierFilter || 'all');
    let rows = (externalAdsBase || []).filter((item) => {
      if (supplierFilter !== 'all') {
        const hasSupplierMatch = (item.history || []).some((history) => String(history?.supplier_id || '') === supplierFilter);
        if (!hasSupplierMatch) return false;
      }
      if (platformFilter === 'all') return true;
      const socialPlatforms = (item.socialLinks || []).map((s) => String(s.platform || '').trim());
      const historyPlatforms = (item.history || []).map((h) => String(h.platform || '').trim());
      const allPlatforms = [...socialPlatforms, ...historyPlatforms].filter(Boolean);
      if (platformFilter === 'other') {
        return allPlatforms.some((platform) => !['Instagram', 'TikTok', 'Telegram', 'YouTube', 'VK', 'OK'].includes(platform));
      }
      return allPlatforms.includes(platformFilter);
    });

    rows = !q ? rows : rows.filter((item) => {
      const socialHay = (item.socialLinks || []).map((s) => `${s.url || ''} ${s.followers || ''} ${s.platform || ''}`).join(' ');
      const historyHay = (item.history || []).map((h) => `${h.supplier_name || ''} ${h.product_name || ''} ${h.url || ''} ${h.rating || ''} ${h.platform || ''}`).join(' ');
      const hay = `${item.nickname || ''} ${item.comment || ''} ${item.status || ''} ${item.overallRating || ''} ${socialHay} ${historyHay}`.toLowerCase();
      return hay.includes(q);
    });

    const maxFollowers = (item: any) => Math.max(0, ...(item?.socialLinks || []).map((s: any) => Number(String(s?.followers || '').replace(/\s+/g, '').replace(',', '.')) || 0));

    rows.sort((a: any, b: any) => {
      if (externalAdsBaseSort === 'date_asc') return String(a.createdAt || '').localeCompare(String(b.createdAt || ''));
      if (externalAdsBaseSort === 'nickname_asc') return String(a.nickname || '').localeCompare(String(b.nickname || ''), 'ru');
      if (externalAdsBaseSort === 'followers_desc') return maxFollowers(b) - maxFollowers(a);
      return String(b.createdAt || '').localeCompare(String(a.createdAt || ''));
    });

    return rows;
  }, [externalAdsBase, externalAdsBasePlatformFilter, externalAdsBaseSearch, externalAdsBaseSort, externalAdsBaseSupplierFilter]);

  const externalAdsBaseSupplierOptions = useMemo(() => {
    const options = new Map<string, string>();
    (suppliers || []).forEach((supplier: any) => {
      const id = String(supplier?.id || '').trim();
      if (!id) return;
      options.set(id, String(supplier?.name || 'Поставщик'));
    });
    (externalAdsBase || []).forEach((item) => {
      (item.history || []).forEach((history) => {
        const id = String(history?.supplier_id || '').trim();
        if (!id) return;
        if (!options.has(id)) options.set(id, String(history?.supplier_name || 'Поставщик'));
      });
    });
    return Array.from(options.entries())
      .map(([id, name]) => ({ id, name }))
      .sort((a, b) => String(a.name || '').localeCompare(String(b.name || ''), 'ru'));
  }, [externalAdsBase, suppliers]);

  const externalAdsBaseHasActiveFilters = useMemo(() => {
    return Boolean(externalAdsBaseSearch.trim()) || String(externalAdsBasePlatformFilter || 'all') !== 'all' || String(externalAdsBaseSupplierFilter || 'all') !== 'all';
  }, [externalAdsBasePlatformFilter, externalAdsBaseSearch, externalAdsBaseSupplierFilter]);

  const syncExternalAdsBaseFromBarterRows = async (sourceRowsInput: any[], options?: { showToast?: boolean; skipEmptyChecks?: boolean; successMessage?: string; emptyMessage?: string }) => {
    const sourceRows = Array.isArray(sourceRowsInput) ? sourceRowsInput : [];
    if (!sourceRows.length) {
      if (!options?.skipEmptyChecks) showToast(options?.emptyMessage || 'Нет данных для синхронизации', 'error');
      return { ok: false, created: 0, updated: 0, alreadyAdded: [] as string[] };
    }

    const nicknameMap = new Map<string, {
      nickname: string;
      links: Array<{ url: string; normalizedUrl: string; platform: string }>;
      history: ExternalAdsHistoryItem[];
    }>();

    const appendEntry = (row: any, kind: 'barter' | 'ad', index: number, linkValue: string, dateValue: string, priceValue: string, viewsValue: string, ratingValue: string, publishedValue?: boolean) => {
      const parsed = parseExternalBloggerLink(linkValue);
      if (!parsed) return;
      const key = String(parsed.nickname || '').trim().toLowerCase();
      if (!key) return;
      const current = nicknameMap.get(key) || { nickname: parsed.nickname, links: [], history: [] };
      if (!current.links.some((link) => link.normalizedUrl === parsed.normalizedUrl)) {
        current.links.push({ url: parsed.url, normalizedUrl: parsed.normalizedUrl, platform: parsed.platform });
      }
      current.history.push({
        id: `${kind}:${String(row?.id || getSafeId())}:${index}`,
        kind,
        supplier_id: String(row?.supplier_id || ''),
        supplier_name: String(row?.supplier_name || ''),
        product_id: String(row?.product_id || ''),
        product_name: String(row?.product_name || ''),
        month: String(row?.month || barterMonth || ''),
        url: parsed.url,
        normalizedUrl: parsed.normalizedUrl,
        platform: parsed.platform,
        date: String(dateValue || ''),
        price: String(priceValue || ''),
        views: String(viewsValue || ''),
        rating: String(ratingValue || ''),
        published: Boolean(publishedValue),
        createdAt: new Date().toISOString(),
      });
      nicknameMap.set(key, current);
    };

    sourceRows.forEach((row: any) => {
      (row?.barter_links || []).forEach((link: string, index: number) => appendEntry(row, 'barter', index, link, row?.barter_dates?.[index], row?.barter_prices?.[index], row?.barter_views?.[index], row?.barter_ratings?.[index], row?.barter_published?.[index]));
      (row?.ad_links || []).forEach((link: string, index: number) => appendEntry(row, 'ad', index, link, row?.ad_dates?.[index], row?.ad_prices?.[index], row?.ad_views?.[index], row?.ad_ratings?.[index], row?.ad_published?.[index]));
    });

    if (!nicknameMap.size) {
      if (!options?.skipEmptyChecks) showToast(options?.emptyMessage || 'Нет заполненных ссылок в бартере или рекламе', 'error');
      return { ok: false, created: 0, updated: 0, alreadyAdded: [] as string[] };
    }

    const existingRows: ExternalAdsBaseEntry[] = [...(externalAdsBase || [])];
    let created = 0;
    let updated = 0;
    const alreadyAddedNames: string[] = [];

    nicknameMap.forEach((entry) => {
      const matchIndex = existingRows.findIndex((item) => {
        const sameNickname = String(item?.nickname || '').trim().toLowerCase() === String(entry.nickname || '').trim().toLowerCase();
        const sameUrl = (item?.socialLinks || []).some((social) => {
          const normalized = normalizeExternalUrl(String(social?.url || ''));
          return entry.links.some((link) => link.normalizedUrl === normalized);
        });
        return sameNickname || sameUrl;
      });

      if (matchIndex >= 0) {
        const current = existingRows[matchIndex];
        const currentLinks = Array.isArray(current?.socialLinks) ? [...current.socialLinks] : [];
        const currentHistory = Array.isArray(current?.history) ? [...current.history] : [];
        let changed = false;

        entry.links.forEach((link) => {
          const currentLinkIndex = currentLinks.findIndex((social) => normalizeExternalUrl(String(social?.url || '')) === link.normalizedUrl);
          if (currentLinkIndex >= 0) {
            const nextPlatform = String(currentLinks[currentLinkIndex]?.platform || link.platform || '');
            if (String(currentLinks[currentLinkIndex]?.platform || '') !== nextPlatform) {
              currentLinks[currentLinkIndex] = { ...currentLinks[currentLinkIndex], platform: nextPlatform };
              changed = true;
            }
            return;
          }
          currentLinks.push({ url: link.url, followers: '', platform: link.platform });
          changed = true;
        });

        entry.history.forEach((historyItem) => {
          const historyIndex = currentHistory.findIndex((item) => String(item.id) === String(historyItem.id));
          if (historyIndex >= 0) {
            const prevSerialized = JSON.stringify(currentHistory[historyIndex]);
            const nextSerialized = JSON.stringify({ ...currentHistory[historyIndex], ...historyItem });
            if (prevSerialized !== nextSerialized) {
              currentHistory[historyIndex] = { ...currentHistory[historyIndex], ...historyItem };
              changed = true;
            }
          } else {
            currentHistory.unshift(historyItem);
            changed = true;
          }
        });

        if (changed) {
          existingRows[matchIndex] = {
            ...current,
            socialLinks: currentLinks,
            history: currentHistory.sort((a, b) => String(b.date || b.createdAt || '').localeCompare(String(a.date || a.createdAt || ''))),
            comment: String(current?.comment || '').trim() ? current.comment : 'Автодобавлено из бартеров/рекламы',
          };
          updated += 1;
        } else {
          alreadyAddedNames.push(entry.nickname);
        }
        return;
      }

      existingRows.unshift({
        id: `ext-ads-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`,
        nickname: entry.nickname,
        socialLinks: entry.links.map((link) => ({ url: link.url, followers: '', platform: link.platform })),
        history: [...entry.history].sort((a, b) => String(b.date || b.createdAt || '').localeCompare(String(a.date || a.createdAt || ''))),
        overallRating: '',
        comment: 'Автодобавлено из бартеров/рекламы',
        status: 'new',
        createdAt: new Date().toISOString(),
      });
      created += 1;
    });

    const uniqueAlreadyAdded = Array.from(new Set(alreadyAddedNames.map((name) => String(name || '').trim()).filter(Boolean)));
    if (!created && !updated) {
      if (options?.showToast) {
        const shortList = uniqueAlreadyAdded.slice(0, 6).join(', ');
        showToast(uniqueAlreadyAdded.length ? `Уже были в базе: ${shortList}${uniqueAlreadyAdded.length > 6 ? ` и ещё ${uniqueAlreadyAdded.length - 6}` : ''}` : 'Все блогеры из ссылок уже есть в базе', 'info');
      }
      return { ok: true, created, updated, alreadyAdded: uniqueAlreadyAdded };
    }

    const ok = await saveExternalAdsBase(existingRows);
    if (!ok) return { ok: false, created, updated, alreadyAdded: uniqueAlreadyAdded };

    if (options?.showToast) {
      const duplicateSuffix = uniqueAlreadyAdded.length
        ? `. Уже были: ${uniqueAlreadyAdded.slice(0, 5).join(', ')}${uniqueAlreadyAdded.length > 5 ? ` и ещё ${uniqueAlreadyAdded.length - 5}` : ''}`
        : '';
      showToast(options?.successMessage || `База обновлена: добавлено ${created}, обновлено ${updated}${duplicateSuffix}`, 'success');
    }

    return { ok: true, created, updated, alreadyAdded: uniqueAlreadyAdded };
  };

  const importBloggersFromBarterLinks = async () => {
    if (!barterTopSupplierId) {
      showToast('Сначала выберите поставщика', 'error');
      return;
    }

    const sourceRows = (monthRows || []).filter((row: any) => String(row?.supplier_id || '') === String(barterTopSupplierId));
    if (!sourceRows.length) {
      showToast('Нет карточек для выбранного поставщика и месяца', 'error');
      return;
    }

    await syncExternalAdsBaseFromBarterRows(sourceRows, { showToast: true });
  };

  const groupedAssemblyButtons = useMemo(() => {
    const q = String(assemblyAccessSearch || '').trim().toLowerCase();
    const filtered = ASSEMBLY_BUTTONS.filter((btn) => {
      if (!q) return true;
      return String(btn.label || '').toLowerCase().includes(q) || String(btn.id || '').toLowerCase().includes(q);
    });

    const sectionOrder = ['Склад', 'Сборка', 'График', 'Календарь', 'Форма'];
    const groups = new Map<string, typeof filtered>();

    filtered.forEach((btn) => {
      const label = String(btn.label || '').trim();
      const prefix = label.includes(':') ? label.split(':')[0].trim() : 'Прочее';
      if (!groups.has(prefix)) groups.set(prefix, []);
      groups.get(prefix)!.push(btn);
    });

    return Array.from(groups.entries())
      .sort((a, b) => {
        const ai = sectionOrder.indexOf(a[0]);
        const bi = sectionOrder.indexOf(b[0]);
        if (ai !== -1 || bi !== -1) return (ai === -1 ? 999 : ai) - (bi === -1 ? 999 : bi);
        return a[0].localeCompare(b[0], 'ru');
      })
      .map(([title, items]) => ({ title, items }));
  }, [assemblyAccessSearch]);

  useEffect(() => {
    const loadBarters = async () => {
      try {
        const hasTableStorage = await detectBarterCardsTable();
        if (!hasTableStorage) {
          console.error('barter_cards table is not available');
          setBarterRows([]);
          setBarterDbReady(true);
          return;
        }

        const tableRows = await fetchBarterRowsFromTable();
        const flags = await loadBarterPublishedFlags();
        const rowsWithFlags = applyBarterPublishedFlags(tableRows, flags);
        const nextExtra = getBarterExtraStateFromRows(rowsWithFlags);
        setBarterGlobalExtra(nextExtra.barterExtra);
        setAdGlobalExtra(nextExtra.adExtra);
        setBarterRows(rowsWithFlags);
      } catch (e) {
        console.error('loadBarters error:', e);
      }
      setBarterDbReady(true);
    };
    loadBarters();
  }, []);

  const loadBarterMoneyHistoryFromSettings = async (supplierId: string) => {
    const { data, error } = await supabase
      .from('app_settings')
      .select('value')
      .eq('key', 'supplier_marketing_money_log_v1')
      .maybeSingle();

    if (error) throw error;

    let parsed: Record<string, any[]> = {};
    try {
      parsed = data?.value ? JSON.parse(String(data.value)) : {};
    } catch {
      parsed = {};
    }

    const supplierRows = Array.isArray(parsed?.[supplierId]) ? parsed[supplierId] : [];
    const normalized = supplierRows.map((row: any) => ({
      id: String(row?.id || getSafeId()),
      supplier_id: String(row?.supplier_id || supplierId),
      amount: Number(row?.amount || 0),
      comment: String(row?.comment || ''),
      created_at: String(row?.created_at || ''),
    })).sort((a: any, b: any) => String(b.created_at || '').localeCompare(String(a.created_at || '')));

    setBarterMoneyHistory(normalized);
    return { parsed, normalized };
  };

  const saveBarterMoneyHistoryToSettings = async (supplierId: string, rows: Array<{ id: string; supplier_id: string; amount: number; comment: string; created_at: string }>) => {
    const { data, error } = await supabase
      .from('app_settings')
      .select('value')
      .eq('key', 'supplier_marketing_money_log_v1')
      .maybeSingle();

    if (error) throw error;

    let parsed: Record<string, any[]> = {};
    try {
      parsed = data?.value ? JSON.parse(String(data.value)) : {};
    } catch {
      parsed = {};
    }

    const normalized = rows
      .map((row) => ({
        id: String(row.id || getSafeId()),
        supplier_id: String(row.supplier_id || supplierId),
        amount: Number(row.amount || 0),
        comment: String(row.comment || ''),
        created_at: String(row.created_at || new Date().toISOString()),
      }))
      .filter((row) => Number.isFinite(Number(row.amount || 0)) && Number(row.amount || 0) !== 0)
      .sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')));

    const nextPayload = { ...parsed, [supplierId]: normalized };
    const { error: upsertError } = await supabase
      .from('app_settings')
      .upsert([{ key: 'supplier_marketing_money_log_v1', value: JSON.stringify(nextPayload) }], { onConflict: 'key' });

    if (upsertError) throw upsertError;

    setBarterMoneyHistory(normalized);
  };

  const fetchBarterMoneyHistory = async (supplierId?: string) => {
    const targetSupplierId = String(supplierId || barterSelectedSupplierId || '').trim();
    if (!targetSupplierId) {
      setBarterMoneyHistory([]);
      return;
    }

    setBarterMoneyLoading(true);
    const { data, error } = await supabase
      .from('supplier_marketing_money_log')
      .select('id, supplier_id, amount, comment, created_at')
      .eq('supplier_id', targetSupplierId)
      .order('created_at', { ascending: false });

    if (error) {
      if (/relation .* does not exist|schema cache/i.test(String(error.message || ''))) {
        try {
          await loadBarterMoneyHistoryFromSettings(targetSupplierId);
        } catch (settingsError: any) {
          showToast('Ошибка загрузки баланса поставщика: ' + (settingsError?.message || 'неизвестно'), 'error');
          setBarterMoneyHistory([]);
        }
      } else {
        console.error('fetchBarterMoneyHistory error:', error);
        showToast('Ошибка загрузки баланса поставщика: ' + (error.message || 'неизвестно'), 'error');
        setBarterMoneyHistory([]);
      }
      setBarterMoneyLoading(false);
      return;
    }

    setBarterMoneyHistory(Array.isArray(data) ? data.map((row: any) => ({
      id: String(row.id),
      supplier_id: String(row.supplier_id || targetSupplierId),
      amount: Number(row.amount || 0),
      comment: String(row.comment || ''),
      created_at: String(row.created_at || ''),
    })) : []);
    setBarterMoneyLoading(false);
  };

  const handleAddBarterMoneyOperation = async (mode: 'add' | 'writeoff') => {
    if (!barterSelectedSupplierId) {
      showToast('Сначала выберите поставщика', 'error');
      return;
    }

    const amount = Math.abs(Number(barterMoneyForm.amount || 0));
    if (!Number.isFinite(amount) || amount === 0) {
      showToast('Введите сумму', 'error');
      return;
    }

    if (mode === 'writeoff' && barterMoneyBalance < amount) {
      showToast('Недостаточно денег на балансе поставщика', 'error');
      return;
    }

    try {
      setBarterMoneySaving(true);
      const payload = {
        supplier_id: barterSelectedSupplierId,
        amount: mode === 'add' ? amount : -amount,
        comment: barterMoneyForm.comment.trim(),
      };

      const { error } = await supabase.from('supplier_marketing_money_log').insert([payload]);

      if (error) {
        if (/relation .* does not exist|schema cache/i.test(String(error.message || ''))) {
          const nextRow = {
            id: getSafeId(),
            supplier_id: barterSelectedSupplierId,
            amount: Number(payload.amount || 0),
            comment: String(payload.comment || ''),
            created_at: new Date().toISOString(),
          };
          await saveBarterMoneyHistoryToSettings(barterSelectedSupplierId, [nextRow, ...(barterMoneyHistory || [])]);
        } else {
          throw error;
        }
      } else {
        await fetchBarterMoneyHistory(barterSelectedSupplierId);
      }

      setBarterMoneyForm({ amount: '', comment: '' });
      logAction(mode === 'add' ? 'Бартер: пополнение баланса' : 'Бартер: списание', `${suppliers.find((s:any)=>String(s.id)===barterSelectedSupplierId)?.name || barterSelectedSupplierId} · ${amount.toLocaleString('ru-RU')} ₽${payload.comment ? ` · ${payload.comment}` : ''}`, currentEmployee?.id);
      showToast(mode === 'add' ? 'Баланс пополнен' : 'Списание сохранено', 'success');
    } catch (e: any) {
      showToast('Ошибка сохранения операции: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setBarterMoneySaving(false);
    }
  };

  const handleDeleteBarterMoneyOperation = (row: { id: string }) => {
    openConfirmModal(
      'Удалить операцию?',
      'Запись будет удалена из баланса поставщика. Продолжить?',
      async () => {
        try {
          const { error } = await supabase.from('supplier_marketing_money_log').delete().eq('id', row.id);
          if (error) {
            if (/relation .* does not exist|schema cache/i.test(String(error.message || ''))) {
              await saveBarterMoneyHistoryToSettings(
                barterSelectedSupplierId,
                (barterMoneyHistory || []).filter((item) => String(item.id) !== String(row.id))
              );
            } else {
              showToast('Ошибка удаления операции: ' + (error.message || 'неизвестно'), 'error');
              return;
            }
          } else {
            await fetchBarterMoneyHistory(barterSelectedSupplierId);
          }

          logAction('Бартер: удаление операции', `${suppliers.find((s:any)=>String(s.id)===barterSelectedSupplierId)?.name || barterSelectedSupplierId} · удалена запись баланса`, currentEmployee?.id);
          showToast('Операция удалена', 'success');
        } finally {
          setConfirmModal(prev => ({ ...prev, isOpen: false }));
        }
      }
    );
  };

  useEffect(() => {
    if (activeTab !== 'barters' || barterSection !== 'barters_main') return;
    if (!barterSelectedSupplierId) {
      setBarterMoneyHistory([]);
      return;
    }

    fetchBarterMoneyHistory(barterSelectedSupplierId);
  }, [activeTab, barterSection, barterSelectedSupplierId]);

  const persistBarterRowsForSupplier = async (rowsInput: any[], currentSupplierId: string, options?: { removedIds?: string[]; successMessage?: string; refreshFromDb?: boolean }) => {
    const normalizedSupplierId = String(currentSupplierId || '').trim();
    if (!normalizedSupplierId) throw new Error('Сначала выберите поставщика');

    const localRows = (rowsInput || []).map((row: any) => normalizeBarterRow(row));
    const hasTableStorage = await detectBarterCardsTable();
    if (!hasTableStorage) throw new Error('Таблица barter_cards недоступна');

    const supplierRows = localRows.filter((row: any) => String(row?.supplier_id || '') === normalizedSupplierId);
    const removedIds = (options?.removedIds || []).map((id) => String(id || '')).filter(Boolean);
    const shouldRefreshFromDb = options?.refreshFromDb !== false;

    if (removedIds.length) {
      const { error: deleteError } = await supabase
        .from('barter_cards')
        .delete()
        .eq('supplier_id', normalizedSupplierId)
        .in('id', removedIds);
      if (deleteError) throw deleteError;
    }

    if (supplierRows.length) {
      const dbRows = supplierRows.map((row: any) => mapBarterRowToDbCard(row));
      const { error: upsertError } = await supabase
        .from('barter_cards')
        .upsert(dbRows, { onConflict: 'id' });
      if (upsertError) {
        if (!isBarterPublishedColumnError(upsertError)) throw upsertError;
        const { error: retryError } = await supabase
          .from('barter_cards')
          .upsert(dbRows.map(stripBarterPublishedDbFields), { onConflict: 'id' });
        if (retryError) throw retryError;
      }
      await saveBarterPublishedFlags(supplierRows);
    }

    if (shouldRefreshFromDb) {
      const refreshedRowsRaw = await fetchBarterRowsFromTable();
      const flags = await loadBarterPublishedFlags();
      const refreshedRows = applyBarterPublishedFlags(refreshedRowsRaw, flags);
      const nextExtra = getBarterExtraStateFromRows(refreshedRows);
      setBarterGlobalExtra(nextExtra.barterExtra);
      setAdGlobalExtra(nextExtra.adExtra);
      setBarterRows(refreshedRows as any);
      setBarterExplicitlyRemovedIds([]);
      await syncExternalAdsBaseFromBarterRows(refreshedRows || [], { showToast: false, skipEmptyChecks: true });
      if (options?.successMessage) showToast(options.successMessage, 'success');
      return refreshedRows;
    }

    await saveBarterPublishedFlags(supplierRows);
    await syncExternalAdsBaseFromBarterRows(localRows || [], { showToast: false, skipEmptyChecks: true });
    if (options?.successMessage) showToast(options.successMessage, 'success');
    return localRows;
  };

  const saveBartersToDb = async () => {
    const currentSupplierId = String(barterTopSupplierId || barterSupplierId || '').trim();
    if (!currentSupplierId) {
      showToast('Сначала выберите поставщика', 'error');
      return;
    }
    try {
      setBarterSaving(true);
      await persistBarterRowsForSupplier(barterRows || [], currentSupplierId, {
        removedIds: barterExplicitlyRemovedIds,
        successMessage: 'Сохранено в отдельные записи БД',
      });
    } catch (e: any) {
      showToast('Ошибка сохранения: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setBarterSaving(false);
    }
  };


  const saveInstagramSettings = async () => {
    try {
      setInstagramSaving(true);
      const cfg = { appId: instagramConfig.appId.trim(), redirectUri: instagramConfig.redirectUri.trim() };
      const upserts: any[] = [{ key: 'instagram_oauth_config_v1', value: JSON.stringify(cfg) }];
      if (instagramAccessToken.trim()) upserts.push({ key: 'instagram_access_token_v1', value: instagramAccessToken.trim() });
      const { error } = await supabase.from('app_settings').upsert(upserts, { onConflict: 'key' });
      if (error) throw error;
      showToast('Instagram настройки сохранены', 'success');
    } catch (e: any) {
      showToast('Ошибка сохранения Instagram: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setInstagramSaving(false);
    }
  };

  const connectInstagramOAuth = () => {
    const appId = instagramConfig.appId.trim();
    const redirectUri = instagramConfig.redirectUri.trim();
    if (!appId || !redirectUri) {
      showToast('Укажите App ID и Redirect URI', 'error');
      return;
    }
    const scope = encodeURIComponent('instagram_basic,instagram_manage_messages,pages_show_list,pages_manage_metadata');
    const url = `https://www.facebook.com/v20.0/dialog/oauth?client_id=${encodeURIComponent(appId)}&redirect_uri=${encodeURIComponent(redirectUri)}&scope=${scope}&response_type=code`;
    window.open(url, '_blank', 'noopener,noreferrer');
  };

  const loadInstagramChats = async () => {
    const token = instagramAccessToken.trim();
    if (!token) return showToast('Укажите Access Token', 'error');

    try {
      setInstagramLoadingChats(true);
      setInstagramChats([]);

      // 1) Get pages available for the token
      const pagesRes = await fetch(`https://graph.facebook.com/v20.0/me/accounts?fields=id,name,access_token&access_token=${encodeURIComponent(token)}`);
      const pagesJson = await pagesRes.json();
      const page = (pagesJson?.data || [])[0];
      if (!page?.id) throw new Error('Не найдена страница Facebook для токена');

      // 2) Find connected IG business account
      const igRes = await fetch(`https://graph.facebook.com/v20.0/${page.id}?fields=instagram_business_account{id,username}&access_token=${encodeURIComponent(page.access_token || token)}`);
      const igJson = await igRes.json();
      const igId = igJson?.instagram_business_account?.id;
      if (!igId) throw new Error('Instagram Business аккаунт не найден (проверьте привязку к Facebook Page)');

      // 3) Load conversations
      const convRes = await fetch(`https://graph.facebook.com/v20.0/${igId}/conversations?fields=id,updated_time,participants&access_token=${encodeURIComponent(page.access_token || token)}`);
      const convJson = await convRes.json();
      const convs = convJson?.data || [];

      setInstagramChats(convs);
      showToast(`Загружено диалогов: ${convs.length}`, 'success');
    } catch (e: any) {
      showToast('Ошибка загрузки диалогов: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setInstagramLoadingChats(false);
    }
  };

  const barterFilteredProducts = useMemo(() => {
    const term = barterProductSearch.trim().toLowerCase();
    return (barterCatalogProducts || []).filter((p: any) => {
      if (!term) return true;
      const hay = `${p?.name || ''} ${p?.title || ''} ${p?.nmID || p?.nmId || ''} ${p?.vendorCode || p?.wb_sku || ''} ${p?.supplierArticle || p?.article || ''} ${p?.barcode || ''} ${p?.size || ''} ${p?.color || ''}`.toLowerCase();
      return hay.includes(term);
    });
  }, [barterCatalogProducts, barterProductSearch]);

  useEffect(() => {
    const run = async () => {
      if (activeTab !== 'barters') return;
      if (!barterSupplierId) {
        setBarterCatalogProducts([]);
        return;
      }
      try {
        setBarterCatalogLoading(true);
        const { data, error } = await fetchAllPages((__a, __b) => supabase
          .from('wb_products_cache')
          .select('supplier_id, nm_id, product_json')
          .eq('supplier_id', barterSupplierId)
          .order('nm_id').range(__a, __b));
        if (error) throw error;
        const rows = (data || []).map((r: any, idx: number) => {
          const p = r?.product_json || {};
          const nm = String(p?.nmID || p?.nmId || p?.nm_id || '');
          const vendorCode = String(p?.vendorCode || p?.article || '');
          const title = String(p?.title || p?.name || '');
          const supplierArticle = String(p?.supplierArticle || '');
          return {
            id: String(r?.nm_id || `${barterSupplierId}-${nm || vendorCode || idx}`),
            supplier_id: String(barterSupplierId),
            name: title,
            title,
            nmID: nm,
            vendorCode,
            supplierArticle,
            groupKey: getBarterProductGroupKey({ title, supplierArticle, vendorCode, id: r?.nm_id || nm || vendorCode || idx }),
            groupName: title || vendorCode || supplierArticle || String(r?.nm_id || ''),
            variantLabel: vendorCode || supplierArticle || nm,
            wb_sku: String(p?.vendorCode || ''),
            photos: Array.isArray(p?.photos) ? p.photos : [],
            photoUrl: String(p?.photos?.[0]?.big || p?.photos?.[0]?.tm || ''),
          };
        });
        setBarterCatalogProducts(rows);
      } catch {
        setBarterCatalogProducts([]);
      } finally {
        setBarterCatalogLoading(false);
      }
    };
    run();
  }, [activeTab, barterSupplierId]);

  const refreshBarterPhotos = async () => {
    const supplierId = barterSupplierId || selectedSupplierId;
    if (!supplierId) return showToast('Сначала выберите поставщика', 'error');
    try {
      setBarterPhotoLoading(true);
      const next: Record<string, string> = {};
      const norm = (v: any) => String(v ?? '').replace(/\D+/g, '').replace(/^0+/, '');

      const { data: cacheRows, error } = await fetchAllPages((__a, __b) => supabase
        .from('wb_products_cache')
        .select('product_json')
        .eq('supplier_id', supplierId)
        .order('nm_id').range(__a, __b));
      if (error) throw error;

      const byNm: Record<string, string> = {};
      const byVendor: Record<string, string> = {};

      (cacheRows || []).forEach((row: any) => {
        const p = row?.product_json || {};
        const nm = norm(p?.nmID || p?.nm_id || p?.nmId || '');
        const vendorCode = String(p?.vendorCode || p?.supplierArticle || p?.article || '').trim();
        const first = (Array.isArray(p?.photos) && p.photos[0]) || (Array.isArray(p?.mediaFiles) && p.mediaFiles[0]) || '';
        let src = typeof first === 'string' ? first : (first?.big || first?.c246x328 || first?.tm || '');
        src = String(src || '').trim();
        if (src && src.startsWith('//')) src = `https:${src}`;
        if (!/^https?:\/\//i.test(src)) return;
        if (nm) byNm[nm] = src;
        if (vendorCode) byVendor[vendorCode.toLowerCase()] = src;
      });

      (barterCatalogProducts || []).forEach((p: any) => {
        if (String(p?.supplier_id || '') !== String(supplierId)) return;
        const pid = String(p.id || '');
        if (!pid) return;
        const nm = norm(p?.wb_sku || p?.nmID || p?.nmId || '');
        const vendor = String(p?.vendorCode || p?.article || p?.wb_sku || '').toLowerCase().trim();
        const src = (nm && byNm[nm]) || (vendor && byVendor[vendor]) || '';
        if (src) next[pid] = src;
      });

      setBarterPhotoMap((prev) => ({ ...(prev || {}), ...(next || {}) }));
      showToast(`Фото обновлены: ${Object.keys(next).length}`, 'success');
    } catch (e: any) {
      showToast('Ошибка обновления фото: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setBarterPhotoLoading(false);
    }
  };

  const refreshBarterPhotosInCards = async () => {
    const supplierIds = Array.from(new Set((monthRows || []).map((r: any) => String(r?.supplier_id || '')).filter(Boolean)));
    if (!supplierIds.length) return showToast('Нет карточек для обновления фото', 'info');
    try {
      setBarterPhotoLoading(true);
      const { data, error } = await fetchAllPages((__a, __b) => supabase
        .from('wb_products_cache')
        .select('supplier_id, nm_id, product_json')
        .in('supplier_id', supplierIds)
        .order('supplier_id').order('nm_id').range(__a, __b));
      if (error) throw error;

      const photoByKey: Record<string, string> = {};
      (data || []).forEach((row: any) => {
        const p = row?.product_json || {};
        const nm = String(row?.nm_id || p?.nmID || p?.nmId || '').trim();
        const first = (Array.isArray(p?.photos) && p.photos[0]) || '';
        let src = typeof first === 'string' ? first : (first?.big || first?.tm || first?.c246x328 || '');
        src = String(src || '').trim();
        if (src && src.startsWith('//')) src = `https:${src}`;
        if (!nm || !/^https?:\/\//i.test(src)) return;
        photoByKey[`${String(row?.supplier_id)}__${nm}`] = src;
      });

      let updated = 0;
      setBarterRows((prev) => (prev || []).map((r: any) => {
        if (String(r?.month || '') !== String(barterMonth)) return r;
        const productIds = Array.isArray(r?.product_ids) && r.product_ids.length ? r.product_ids.map((id: any) => String(id || '')).filter(Boolean) : [String(r?.product_id || '')].filter(Boolean);
        const nextPhotos = Array.from(new Set(productIds.map((id: string) => photoByKey[`${String(r?.supplier_id || '')}__${id}`] || '').filter(Boolean)));
        const fallback = normalizeBarterPhotoUrl(r?.product_photo || '');
        if (fallback && !nextPhotos.length) nextPhotos.push(fallback);
        const prevPhotos = Array.isArray(r?.product_photos) ? r.product_photos.map((photo: any) => normalizeBarterPhotoUrl(photo)).filter(Boolean) : (fallback ? [fallback] : []);
        const nextPrimary = nextPhotos[0] || fallback;
        if (nextPrimary !== fallback || nextPhotos.join('|') !== prevPhotos.join('|')) {
          updated += 1;
          return { ...r, product_photo: nextPrimary, product_photos: nextPhotos };
        }
        return r;
      }));
      showToast(`Фото в карточках обновлены: ${updated}`, 'success');
    } catch (e: any) {
      showToast('Ошибка обновления фото: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setBarterPhotoLoading(false);
    }
  };

  const monthNamesRu = ['янв', 'фев', 'мар', 'апр', 'май', 'июн', 'июл', 'авг', 'сен', 'окт', 'ноя', 'дек'];

  useEffect(() => {
    const y = Number(String(barterMonth || '').split('-')[0]);
    if (Number.isFinite(y) && y > 2000) setBarterMonthYear(y);
  }, [barterMonth]);

  const monthRows = useMemo(() => {
    if (!barterTopSupplierId) return [];
    return (barterRows || []).filter((r: any) => {
      if (String(r?.month || '') !== String(barterMonth)) return false;
      if (String(r?.supplier_id || '') !== String(barterTopSupplierId)) return false;
      return true;
    });
  }, [barterRows, barterMonth, barterTopSupplierId]);

  useEffect(() => {
    setBarterMergeSelectedIds((prev) => prev.filter((id) => (monthRows || []).some((row: any) => String(row?.id || '') === String(id))));
  }, [monthRows]);

  useEffect(() => {
    if (!barterTopSupplierId) return;
    setBarterMonth(currentBarterMonth);
    setBarterMonthYear(currentBarterYear);
    setBarterDuplicateModal((prev) => ({ ...prev, targetMonth: currentBarterMonth }));
    setBarterMergeMode(false);
    setBarterMergeSelectedIds([]);
    setBarterExplicitlyRemovedIds([]);
  }, [barterTopSupplierId]);

  const mergeSelectedBarterCards = async () => {
    const selectedSet = new Set((barterMergeSelectedIds || []).map((id) => String(id)));
    const selectedRows = (monthRows || []).filter((row: any) => selectedSet.has(String(row?.id || '')));
    if (selectedRows.length < 2) {
      showToast('Выбери минимум 2 карточки для объединения', 'error');
      return;
    }
    const mergedRow = mergeBarterRowsIntoSingle(selectedRows);
    if (!mergedRow) {
      showToast('Не удалось объединить карточки', 'error');
      return;
    }

    const currentSupplierId = String(selectedRows[0]?.supplier_id || barterTopSupplierId || barterSupplierId || '').trim();
    if (!currentSupplierId) {
      showToast('Сначала выберите поставщика', 'error');
      return;
    }

    const prevRows = barterRows || [];
    const prevRemovedIds = barterExplicitlyRemovedIds || [];
    const firstIndex = prevRows.findIndex((row: any) => selectedSet.has(String(row?.id || '')));
    const nextRows = prevRows.filter((row: any) => !selectedSet.has(String(row?.id || '')));
    nextRows.splice(firstIndex >= 0 ? firstIndex : nextRows.length, 0, mergedRow as any);
    const nextRemovedIds = Array.from(new Set([...(prevRemovedIds || []), ...Array.from(selectedSet)]));

    setBarterRows(nextRows as any);
    setBarterExplicitlyRemovedIds(nextRemovedIds);
    setBarterMergeMode(false);
    setBarterMergeSelectedIds([]);

    try {
      setBarterSaving(true);
      await persistBarterRowsForSupplier(nextRows, currentSupplierId, {
        removedIds: nextRemovedIds,
        successMessage: 'Карточка создана',
      });
    } catch (e: any) {
      setBarterRows(prevRows as any);
      setBarterExplicitlyRemovedIds(prevRemovedIds);
      setBarterMergeMode(true);
      setBarterMergeSelectedIds(Array.from(selectedSet));
      showToast('Не удалось автосохранить объединение: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setBarterSaving(false);
    }
  };

  const deleteBarterRow = async (row: any) => {
    const currentSupplierId = String(row?.supplier_id || barterTopSupplierId || barterSupplierId || '').trim();
    if (!currentSupplierId) {
      showToast('Сначала выберите поставщика', 'error');
      return;
    }

    const prevRows = barterRows || [];
    const prevRemovedIds = barterExplicitlyRemovedIds || [];
    const rowPersistKey = getBarterRowPersistKey(row);
    const nextRows = prevRows.filter((x: any) => String(x?.id || '') !== String(row?.id || ''));
    const nextRemovedIds = Array.from(new Set([...(prevRemovedIds || []), rowPersistKey]));

    setBarterRows(nextRows as any);
    setBarterExplicitlyRemovedIds(nextRemovedIds);

    try {
      setBarterSaving(true);
      await persistBarterRowsForSupplier(nextRows, currentSupplierId, {
        removedIds: nextRemovedIds,
        successMessage: 'Карточка удалена',
      });
      logAction('Бартер: удаление карточки', `${suppliers.find((s:any)=>String(s.id)===currentSupplierId)?.name || currentSupplierId} · «${row?.product_name || row?.product_group_name || row?.id}» · месяц ${row?.month || barterMonth}`, currentEmployee?.id);
    } catch (e: any) {
      setBarterRows(prevRows as any);
      setBarterExplicitlyRemovedIds(prevRemovedIds);
      showToast('Не удалось автосохранить удаление: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setBarterSaving(false);
    }
  };

  const monthStats = useMemo(() => {
    const rows = monthRows || [];
    const barterDone = rows.reduce((s: number, r: any) => s + (r?.barter_published || []).filter(Boolean).length, 0);
    const adDone = rows.reduce((s: number, r: any) => s + (r?.ad_published || []).filter(Boolean).length, 0);
    const barterCost = rows.reduce((sum: number, r: any) => sum + (r?.barter_prices || []).reduce((acc: number, v: string) => acc + (parseFloat(String(v || '0')) || 0), 0), 0);
    const adCost = rows.reduce((sum: number, r: any) => sum + (r?.ad_prices || []).reduce((acc: number, v: string) => acc + (parseFloat(String(v || '0')) || 0), 0), 0);
    const barterTotal = rows.reduce((sum: number, r: any) => sum + getBarterRowPlanCount(r, 'barter'), 0);
    const adTotal = rows.reduce((sum: number, r: any) => sum + getBarterRowPlanCount(r, 'ad'), 0);
    const planDone = barterDone + adDone;
    const planTotal = barterTotal + adTotal;
    const planPercent = planTotal > 0 ? Math.round((planDone / planTotal) * 100) : 0;
    return { cards: rows.length, barterDone, barterTotal, adDone, adTotal, barterCost, adCost, planDone, planTotal, planPercent };
  }, [monthRows]);

  const closeBarterAddModal = (options?: { resetSelection?: boolean }) => {
    setBarterModalOpen(false);
    setBarterCreateMergedCard(false);
    if (options?.resetSelection) {
      setBarterCheckedProductIds([]);
      setBarterProductSearch('');
    }
  };

  const openBarterPreviewGallery = (images: string[], startIndex = 0) => {
    const safeImages = (images || []).map((src) => String(src || '').trim()).filter(Boolean);
    if (!safeImages.length) return;
    const normalizedIndex = Math.max(0, Math.min(startIndex, safeImages.length - 1));
    setBarterPreviewGallery({ images: safeImages, index: normalizedIndex, closing: false, closeMode: 'fade' });
  };

  const closeBarterPreviewGallery = (mode: 'fade' | 'down' = 'fade') => {
    setBarterPreviewGallery((prev) => {
      if (!prev || prev.closing) return prev;
      return { ...prev, closing: true, closeMode: mode };
    });
    window.setTimeout(() => {
      setBarterPreviewGallery((prev) => prev?.closing ? null : prev);
    }, 180);
  };

  const showPreviousBarterPreviewImage = () => {
    setBarterPreviewGallery((prev) => prev ? ({ ...prev, index: prev.index > 0 ? prev.index - 1 : prev.images.length - 1, closing: false }) : prev);
  };

  const showNextBarterPreviewImage = () => {
    setBarterPreviewGallery((prev) => prev ? ({ ...prev, index: prev.index < prev.images.length - 1 ? prev.index + 1 : 0, closing: false }) : prev);
  };

  const scheduleBarterRowsAutosave = (rowsInput: any[], supplierIdInput?: string, changedRowIds?: string[]) => {
    const targetSupplierId = String(supplierIdInput || barterTopSupplierId || barterSupplierId || '').trim();
    if (!targetSupplierId) return;
    const safeChangedIds = Array.from(new Set((changedRowIds || []).map((id) => String(id || '')).filter(Boolean)));
    if (safeChangedIds.length) {
      setBarterCardSaveState((prev) => ({
        ...(prev || {}),
        ...Object.fromEntries(safeChangedIds.map((id) => [id, 'saving']))
      }));
    }
    if (barterAutosaveTimeoutRef.current) window.clearTimeout(barterAutosaveTimeoutRef.current);
    barterAutosaveTimeoutRef.current = window.setTimeout(async () => {
      try {
        setBarterSaving(true);
        await persistBarterRowsForSupplier(rowsInput, targetSupplierId, { refreshFromDb: false });
        if (safeChangedIds.length) {
          setBarterCardSaveState((prev) => ({
            ...(prev || {}),
            ...Object.fromEntries(safeChangedIds.map((id) => [id, 'saved']))
          }));
          window.setTimeout(() => {
            setBarterCardSaveState((prev) => {
              const next = { ...(prev || {}) };
              safeChangedIds.forEach((id) => {
                if (next[id] === 'saved') delete next[id];
              });
              return next;
            });
          }, 2200);
        }
      } catch (e: any) {
        if (safeChangedIds.length) {
          setBarterCardSaveState((prev) => ({
            ...(prev || {}),
            ...Object.fromEntries(safeChangedIds.map((id) => [id, 'error']))
          }));
        }
        showToast('Не удалось автосохранить правки: ' + (e?.message || 'неизвестно'), 'error');
      } finally {
        setBarterSaving(false);
        barterAutosaveTimeoutRef.current = null;
      }
    }, 700);
  };

  const applyBarterRowsEdit = (nextRows: any[], supplierIdInput?: string, changedRowIds?: string[]) => {
    setBarterRows(nextRows as any);
    scheduleBarterRowsAutosave(nextRows, supplierIdInput, changedRowIds);
  };

  const addSelectedBarterProducts = async () => {
    const currentSupplierId = String(barterSupplierId || barterTopSupplierId || '').trim();
    const selectedMap = new Map((barterCatalogProducts || []).map((p: any) => [String(p.id), p]));
    const supplier = suppliers.find((s: any) => String(s.id) === String(currentSupplierId));
    const bCount = Math.max(0, Math.floor(Number(barterCreateBarterCount) || 0));
    const aCount = Math.max(0, Math.floor(Number(barterCreateAdCount) || 0));
    const newRows = barterCheckedProductIds
      .map((pid) => selectedMap.get(String(pid)))
      .filter(Boolean)
      .map((p: any) => ({
        id: getSafeId(),
        month: barterMonth,
        supplier_id: String(p.supplier_id || currentSupplierId || ''),
        supplier_name: String(suppliers.find((s: any) => String(s.id) === String(p.supplier_id || currentSupplierId))?.name || supplier?.name || 'Поставщик'),
        product_id: String(p.id),
        product_name: String(p.name || p.title || p.wb_sku || p.barcode || p.id),
        product_group_key: String(p.groupKey || getBarterProductGroupKey(p)),
        product_group_name: String(p.groupName || getBarterProductGroupName(p)),
        product_ids: [String(p.id)],
        product_photos: [String(p?.photoUrl || p?.photos?.[0]?.big || p?.photos?.[0]?.tm || '')].map((photo) => normalizeBarterPhotoUrl(photo)).filter(Boolean),
        product_variant_labels: getBarterVariantLabel(p) ? [getBarterVariantLabel(p)] : [],
        product_variants_count: 1,
        product_photo: String(p?.photoUrl || p?.photos?.[0]?.big || p?.photos?.[0]?.tm || ''),
        barter_links: Array(bCount).fill(''),
        barter_dates: Array(bCount).fill(''),
        barter_prices: Array(bCount).fill(''),
        barter_views: Array(bCount).fill(''),
        barter_ratings: Array(bCount).fill(''),
        barter_published: Array(bCount).fill(false),
        ad_links: Array(aCount).fill(''),
        ad_dates: Array(aCount).fill(''),
        ad_prices: Array(aCount).fill(''),
        ad_views: Array(aCount).fill(''),
        ad_ratings: Array(aCount).fill(''),
        ad_published: Array(aCount).fill(false),
      }));

    const prevRows = barterRows || [];
    const append = newRows.filter((r) => !prevRows.some((x: any) => {
      if (String(x?.month || '') !== String(r.month)) return false;
      if (String(x?.supplier_id || '') !== String(r.supplier_id)) return false;
      const ids = Array.isArray(x?.product_ids) && x.product_ids.length
        ? x.product_ids.map((id: any) => String(id || '')).filter(Boolean)
        : [String(x?.product_id || '')].filter(Boolean);
      return ids.includes(String(r.product_id || ''));
    }));

    let mergedCreated = false;
    let nextRows = [...prevRows];
    if (barterCreateMergedCard && append.length >= 2) {
      const mergedRow = mergeBarterRowsIntoSingle(append, { barterExtra: bCount - 5, adExtra: aCount - 2 });
      if (mergedRow) {
        mergedCreated = true;
        nextRows = [...prevRows, mergedRow as any];
      } else {
        nextRows = [...prevRows, ...append];
      }
    } else {
      nextRows = [...prevRows, ...append];
    }

    setBarterRows(nextRows as any);
    closeBarterAddModal({ resetSelection: true });

    if (newRows.length > 0 && append.length === 0) {
      showToast('Все выбранные товары уже есть в карточках этого месяца', 'info');
      return;
    }

    if (!append.length) return;

    try {
      setBarterSaving(true);
      await persistBarterRowsForSupplier(nextRows, currentSupplierId, {
        successMessage: 'Карточка создана',
      });
      logAction('Бартер: создание карточек', `${supplier?.name || currentSupplierId} · месяц ${barterMonth} · товаров: ${append.length}${mergedCreated ? ' (объединённая)' : ''}: ${append.slice(0,5).map((r:any)=>r.product_name).join(', ')}${append.length>5?'…':''}`, currentEmployee?.id);
    } catch (e: any) {
      setBarterRows(nextRows as any);
      showToast('Карточки добавлены локально, но автосохранение не удалось: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setBarterSaving(false);
    }
  };

  const filteredActivityLogs = useMemo(() => {
    if (!activityLogsUsefulOnly) return activityLogs || [];
    return (activityLogs || []).filter((log: any) => {
      const change = parseEmployeeChange(log?.details || '');
      const assemblyChange = parseAssemblyChange(log?.details || '');
      if (change || assemblyChange) return true; // всегда оставляем откатываемые действия
      const action = String(log?.action || '').toLowerCase();
      const details = String(log?.details || '').toLowerCase();
      return [
        'удал', 'создан', 'измен', 'откат', 'ошиб', 'восстанов', 'закрыт', 'отправ'
      ].some((k) => action.includes(k) || details.includes(k));
    });
  }, [activityLogs, activityLogsUsefulOnly]);

  useEffect(() => {
    if (showActivityLogModal) {
      const fetchLogs = async () => {
        setLoadingLogs(true);
        const { data, error } = await supabase
          .from('activity_logs')
          .select('*')
          .eq('employee_id', showActivityLogModal.id)
          .order('created_at', { ascending: false });

        if (error) {
            console.error('Error fetching logs:', error);
            showToast('Ошибка загрузки логов: ' + error.message, 'error');
        } else {
            setActivityLogs(data || []);
        }
        setLoadingLogs(false);
      };
      fetchLogs();
      // Подтягиваем справочник операций, чтобы в логе показывать названия, а не UUID.
      if (!cwWorkRates.length) {
        supabase.from('work_rates').select('*').is('deleted_at', null).then(({ data }) => { if (data) setCwWorkRates(data); });
      }
    }
  }, [showActivityLogModal]);

  const createPermanentAuthToken = () => {
      const randomPart = Math.random().toString(36).slice(2) + Math.random().toString(36).slice(2);
      return `auth_${Date.now().toString(36)}_${randomPart}`;
  };

  const generateAndSendQR = async (employee: any, isNew = false, plainPassword = '') => {
    await ensurePdfLibs();
      let authToken = employee.auth_token;
      if (!authToken) {
          authToken = createPermanentAuthToken();
          const { error } = await supabase
            .from('employees')
            .update({ auth_token: authToken, qr_code: `AUTH:${authToken}` })
            .eq('id', employee.id);
          if (error) throw error;
      }

      const qrData = `AUTH:${authToken}`;

      const doc = new lazyLibs.jsPDF();
      const qrImageUrl = `https://api.qrserver.com/v1/create-qr-code/?size=300x300&data=${encodeURIComponent(qrData)}`;
      const qrImage = await fetch(qrImageUrl).then(res => res.blob());

      const reader = new FileReader();
      reader.readAsDataURL(qrImage);

      await new Promise(resolve => {
        reader.onloadend = () => {
            if (reader.result) {
                const pageWidth = doc.internal.pageSize.getWidth();
                const pageHeight = doc.internal.pageSize.getHeight();
                const imgWidth = 100;
                const imgHeight = 100;
                const x = (pageWidth - imgWidth) / 2;
                const y = (pageHeight - imgHeight) / 2;
                doc.addImage(reader.result as string, 'PNG', x, y, imgWidth, imgHeight);
            }
            resolve(null);
        }
      });

      const pdfBlob = doc.output('blob');

      if (employee.telegram_chat_id) {
          const formData = new FormData();
          formData.append('chat_id', employee.telegram_chat_id);
          formData.append('caption', isNew
            ? `Ваш аккаунт зарегистрирован.\nЛогин: ${employee.login}\nПароль: ${plainPassword || '(задан администратором)'}\nQR постоянный (без срока действия).`
            : `Ваш постоянный QR код для входа (без срока действия).`);
          formData.append('document', pdfBlob, 'QR_для_входа.pdf');

          const token = String((telegramBotToken || '').trim());
          if (token) {
            await fetch(`https://api.telegram.org/bot${token}/sendDocument`, {
              method: 'POST',
              body: formData
            });
          }
      }
  };

  const handleAddEmployee = async (e: React.FormEvent) => {
    e.preventDefault();
    setAddingEmployee(true);

    try {
      const normalizedLogin = newEmployee.login.trim().toLowerCase();
      const normalizedPassword = newEmployee.password.trim();
      const authToken = createPermanentAuthToken();
      const qrData = `AUTH:${authToken}`;

      /*
       * Пароль ставим ВТОРЫМ шагом, а не в той же вставке.
       *
       * Триггер хэширования срабатывает BEFORE INSERT и пишет в
       * employee_credentials ссылку на сотрудника, которого ещё нет, — внешний
       * ключ такую вставку отклоняет («violates foreign key constraint
       * employee_credentials_employee_id_fkey»). При обновлении строка уже
       * существует, и хэш ложится нормально.
       */
      const { data: created, error } = await supabase
        .from('employees')
        .upsert([{
          full_name: newEmployee.fullName,
          login: normalizedLogin,
          telegram_chat_id: newEmployee.chatId,
          role: newEmployee.role,
          qr_code: qrData,
          auth_token: authToken,
          permissions: newEmployee.permissions,
          can_access_database: newEmployee.can_access_database,
          deleted_at: null
        }], { onConflict: 'login' })
        .select()
        .single();

      if (error) throw error;

      const { data: withPassword, error: passwordError } = await supabase
        .from('employees')
        .update({ password: normalizedPassword })
        .eq('id', created.id)
        .select()
        .single();

      // Без пароля запись бесполезна: логин занят, а войти нельзя.
      if (passwordError) {
        await supabase.from('employees').delete().eq('id', created.id);
        throw new Error(`пароль не сохранился, сотрудник не создан: ${passwordError.message}`);
      }

      const data = withPassword;

      await logEmployeeChange('create', null, data);
      await generateAndSendQR(data, true, normalizedPassword);

      showToast('Сотрудник добавлен и уведомлен', 'success');
      setShowAddEmployeeModal(false);
      setNewEmployee({
        fullName: '',
        login: '',
        password: '',
        chatId: '',
        role: 'Сборщик',
        can_access_database: false,
        permissions: {
          map: true, cameras: true, products: true, wb_products: true, fbs: true, supplies: true, reception: true,
          suppliers: true, honest_sign: true, assembly: true,
          completed: true, telegram: true, employees: true,
          reports: false, trash: false, orders: true, analytics: true, instagram: true, barters: true, database: false
        }
      });
      fetchEmployees();

    } catch (error: any) {
      showToast('Ошибка: ' + error.message, 'error');
    } finally {
      setAddingEmployee(false);
    }
  };

  const handleUpdateEmployee = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!editingEmployee) return;
    setAddingEmployee(true);

    try {
      const before = employees.find(emp => emp.id === editingEmployee.id) || null;
      const nextData: Record<string, any> = {
        full_name: editingEmployee.full_name,
        login: editingEmployee.login,
        telegram_chat_id: editingEmployee.telegram_chat_id,
        role: editingEmployee.role,
        permissions: editingEmployee.permissions,
        can_access_database: editingEmployee.can_access_database
      };
      // Only set the password when the admin typed a new one; blank = keep current hash.
      const newPassword = String(editingEmployee.password || '').trim();
      if (newPassword) nextData.password = newPassword;

      const { error } = await supabase.from('employees').update(nextData).eq('id', editingEmployee.id);

      if (error) throw error;

      await logEmployeeChange('update', before, { ...(before || {}), ...nextData, id: editingEmployee.id });
      showToast('Данные сотрудника обновлены', 'success');
      setEditingEmployee(null);
      fetchEmployees();
    } catch (error: any) {
      showToast('Ошибка: ' + error.message, 'error');
    } finally {
      setAddingEmployee(false);
    }
  };

  const handleSendQR = async () => {
    if (!showSendQRModal) return;
    setSendingQR(true);
    try {
      await generateAndSendQR(showSendQRModal);
      showToast('QR код отправлен', 'success');
      setShowSendQRModal(null);
    } catch (error: any) {
      showToast('Ошибка отправки: ' + error.message, 'error');
    } finally {
      setSendingQR(false);
    }
  };

  // Print State
  const [printFiles, setPrintFiles] = useState<{id: string, name: string, type: string, url: string, printed_at?: string, supplier_id?: string}[]>([]);
  const [printSupplierId, setPrintSupplierId] = useState('');
  const [printBotDiagnostics, setPrintBotDiagnostics] = useState('');
  const [printBotDiagnosticsOpen, setPrintBotDiagnosticsOpen] = useState(false);
  const printFileInputRef = useRef<HTMLInputElement>(null);

  const handlePrintFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (e.target.files) {
      const files = Array.from(e.target.files);
      files.forEach(file => {
        const reader = new FileReader();
        reader.onload = (e) => {
          if (e.target?.result) {
            setPrintFiles(prev => [...prev, {
              id: Math.random().toString(36).substr(2, 9),
              name: file.name,
              type: file.type,
              url: e.target!.result as string,
              supplier_id: printSupplierId
            }]);
          }
        };
        reader.readAsDataURL(file);
      });
    }
    if (printFileInputRef.current) printFileInputRef.current.value = '';
  };

  const handlePrintFile = (id: string) => {
    setPrintFiles(prev => prev.map(f => f.id === id ? { ...f, printed_at: new Date().toLocaleString('ru-RU') } : f));

    const file = printFiles.find(f => f.id === id);
    if (!file) return;
    logAction('Печать файла', `Распечатан файл: ${file.name}`, currentEmployee?.id);

    const isImage = String(file.type || '').includes('image');
    const safeName = String(file.name || 'Документ').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    // Tablet-friendly preview window: shows the file + a big Печать button.
    // window.print() opens the OS print dialog where a Bluetooth/Wi-Fi printer can be chosen.
    const win = window.open('', '_blank');
    if (!win) { showToast('Разрешите всплывающие окна для печати', 'warning'); return; }
    const body = isImage
      ? `<img id="pf" src="${file.url}" alt="${safeName}" />`
      : `<iframe id="pf" src="${file.url}" title="${safeName}"></iframe>`;
    const printJs = isImage
      ? `window.focus(); window.print();`
      : `try{ var f=document.getElementById('pf'); f.focus(); (f.contentWindow||window).print(); }catch(e){ window.print(); }`;
    win.document.write(`
      <!doctype html><html><head><meta charset="utf-8"/>
        <meta name="viewport" content="width=device-width, initial-scale=1"/>
        <title>${safeName}</title>
        <style>
          *{box-sizing:border-box} body{margin:0;font-family:-apple-system,system-ui,sans-serif;background:#0f172a;color:#fff;height:100vh;display:flex;flex-direction:column}
          .bar{display:flex;gap:10px;align-items:center;padding:12px 16px;background:#111827;position:sticky;top:0;z-index:5}
          .bar .name{flex:1;font-size:15px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
          .btn{appearance:none;border:0;border-radius:12px;padding:14px 22px;font-size:17px;font-weight:700;cursor:pointer}
          .print{background:#4f46e5;color:#fff} .close{background:#374151;color:#fff}
          .stage{flex:1;display:flex;align-items:center;justify-content:center;overflow:auto;background:#1e293b}
          #pf{width:100%;height:100%;border:0;background:#fff}
          img#pf{max-width:100%;max-height:100%;width:auto;height:auto;object-fit:contain}
          @media print{.bar{display:none}.stage{background:#fff}body{background:#fff}}
        </style></head>
      <body>
        <div class="bar">
          <span class="name">${safeName}</span>
          <button class="btn print" onclick="${printJs.replace(/"/g, '&quot;')}">🖨 Печать</button>
          <button class="btn close" onclick="window.close()">Закрыть</button>
        </div>
        <div class="stage">${body}</div>
        <script>
          var el=document.getElementById('pf');
          var go=function(){ setTimeout(function(){ ${printJs} }, 600); };
          if(el){ if(el.tagName==='IFRAME'){ el.addEventListener('load', go); } else { el.addEventListener('load', go); } }
        </script>
      </body></html>
    `);
    win.document.close();
  };

  const handleDeletePrintFile = async (id: string) => {
    if (!await confirmDialog('Удалить файл?')) return;

    try {
        const file = printFiles.find(f => f.id === id);
        const { error } = await supabase.from('print_files').delete().eq('id', id);

        if (error) throw error;

        if (file) {
            await logAction('Удаление файла', `Удален файл: ${file.name}`, currentEmployee?.id);
        }

        setPrintFiles(prev => prev.filter(f => f.id !== id));
        showToast('Файл удален', 'success');
    } catch (e: any) {
        showToast('Ошибка удаления: ' + e.message, 'error');
    }
  };

  const getFileIcon = (type: string) => {
    if (type.includes('pdf')) return <FileText className="h-6 w-6 text-red-500" />;
    if (type.includes('sheet') || type.includes('excel')) return <FileSpreadsheet className="h-6 w-6 text-green-500" />;
    if (type.includes('image')) return <Camera className="h-6 w-6 text-blue-500" />;
    return <File className="h-6 w-6 text-slate-400" />;
  };

  const waitForDatabaseBackupRetry = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

  const runDatabaseBackupQuery = async <T,>(factory: () => Promise<T>, attempts = 4): Promise<T> => {
    let lastError: any = null;
    for (let attempt = 1; attempt <= attempts; attempt += 1) {
      try {
        return await factory();
      } catch (error: any) {
        lastError = error;
        const message = String(error?.message || error || '');
        const isTransient = /fetch failed|statement timeout|web server is down|error code 521|timeout/i.test(message.toLowerCase());
        if (!isTransient || attempt === attempts) throw error;
        await waitForDatabaseBackupRetry(attempt * 1500);
      }
    }
    throw lastError;
  };

  const parseDatabaseLogsValue = (value: any) => {
    if (!value) return [] as Array<{ version: string; date: string; details: string; created_at?: string; status?: string; source?: string; file_name?: string }>;
    try {
      const parsed = typeof value === 'string' ? JSON.parse(value) : value;
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  };

  const loadDatabaseBackupMeta = async (showSuccessToast = false) => {
    setDatabaseLogsLoading(true);
    try {
      const { data, error } = await supabase
        .from('app_settings')
        .select('key, value')
        .in('key', ['database_backup_logs', 'database_backup_schedule'])
        .limit(20);

      if (error) throw error;

      const logsSetting = (data || []).find((row: any) => row.key === 'database_backup_logs');
      const scheduleSetting = (data || []).find((row: any) => row.key === 'database_backup_schedule');
      const parsedLogs = parseDatabaseLogsValue(logsSetting?.value);
      setDatabaseLogs(parsedLogs);

      if (scheduleSetting?.value) {
        const value = typeof scheduleSetting.value === 'string' ? scheduleSetting.value : JSON.stringify(scheduleSetting.value);
        setDatabaseBackupScheduleLabel(value || 'Ежедневно в 09:00 (Europe/Moscow)');
      } else {
        setDatabaseBackupScheduleLabel('Ежедневно в 09:00 (Europe/Moscow)');
      }

      if (showSuccessToast) showToast('История обновлена', 'success');
    } catch (e) {
      console.error('Failed to load database backup meta', e);
      showToast('Ошибка обновления истории', 'error');
    } finally {
      setDatabaseLogsLoading(false);
    }
  };

  const refreshDatabaseLogs = async () => {
    await loadDatabaseBackupMeta(true);
  };

  const fetchAllRowsForDatabaseBackup = async (table: string) => {
    const pageSizeByTable: Record<string, number> = {
      activity_logs: 200,
      analytics_upload_reports_raw: 3,
      products: 200,
      receptions: 100,
      unified_honest_sign_codes: 200,
      wb_products_cache: 200,
      work_logs: 200,
    };
    const pageSize = pageSizeByTable[table] || 500;
    const rows: any[] = [];

    if (table === 'app_settings' || table === 'wb_products_cache') {
      let from = 0;
      while (true) {
        const to = from + pageSize - 1;
        const { data, error } = await runDatabaseBackupQuery(() => supabase.from(table).select('*').range(from, to));
        if (error) throw error;
        if (!data || data.length === 0) break;
        rows.push(...data);
        if (data.length < pageSize) break;
        from += pageSize;
      }
      return rows;
    }

    let lastId: string | null = null;
    while (true) {
      let query = supabase.from(table).select('*').order('id', { ascending: true }).limit(pageSize);
      if (lastId) query = query.gt('id', lastId);
      const { data, error } = await runDatabaseBackupQuery(() => query);
      if (error) {
        if (String(error.message || '').includes('does not exist')) {
          let from = rows.length;
          while (true) {
            const to = from + pageSize - 1;
            const fallback = await runDatabaseBackupQuery(() => supabase.from(table).select('*').range(from, to));
            if (fallback.error) throw fallback.error;
            if (!fallback.data || fallback.data.length === 0) break;
            rows.push(...fallback.data);
            if (fallback.data.length < pageSize) break;
            from += pageSize;
          }
          break;
        }
        throw error;
      }
      if (!data || data.length === 0) break;
      rows.push(...data);
      if (data.length < pageSize) break;
      lastId = String(data[data.length - 1]?.id || '');
      if (!lastId) break;
    }

    return rows;
  };

  const buildDatabaseBackupFileName = (prefix = 'database_backup_full') => {
    const now = new Date();
    const yyyy = now.getFullYear();
    const mm = String(now.getMonth() + 1).padStart(2, '0');
    const dd = String(now.getDate()).padStart(2, '0');
    const hh = String(now.getHours()).padStart(2, '0');
    const mi = String(now.getMinutes()).padStart(2, '0');
    const ss = String(now.getSeconds()).padStart(2, '0');
    return `${prefix}_${yyyy}-${mm}-${dd}_${hh}-${mi}-${ss}.json`;
  };

  const downloadDatabaseBackupBlob = (payload: any, fileName: string) => {
    const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = fileName;
    link.click();
    URL.revokeObjectURL(url);
  };

  const appendDatabaseBackupLog = async (entry: { version: string; date: string; details: string; created_at?: string; status?: string; source?: string; file_name?: string }) => {
    const { data, error } = await supabase
      .from('app_settings')
      .select('value')
      .eq('key', 'database_backup_logs')
      .maybeSingle();

    if (error) throw error;

    const currentLogs = parseDatabaseLogsValue(data?.value);
    const updatedLogs = [entry, ...currentLogs].slice(0, 200);

    const { error: upsertError } = await supabase.from('app_settings').upsert({
      key: 'database_backup_logs',
      value: JSON.stringify(updatedLogs),
    });

    if (upsertError) throw upsertError;
    setDatabaseLogs(updatedLogs);
  };

  const createFullDatabaseBackupSnapshot = async () => {
    const startedAt = new Date();
    const dbData: Record<string, any[]> = {};
    const summary: Array<{ table: string; rows: number; status: string }> = [];

    for (const table of DATABASE_BACKUP_TABLES) {
      try {
        const rows = await fetchAllRowsForDatabaseBackup(table);
        dbData[table] = rows;
        summary.push({ table, rows: rows.length, status: 'ok' });
      } catch (e: any) {
        dbData[table] = [];
        summary.push({ table, rows: 0, status: `error: ${e?.message || 'unknown'}` });
      }
    }

    const totalRows = summary.reduce((acc, row) => acc + Number(row.rows || 0), 0);
    return {
      generated_at: startedAt.toISOString(),
      source: 'dashboard_manual',
      summary,
      total_tables: DATABASE_BACKUP_TABLES.length,
      total_rows: totalRows,
      data: dbData,
    };
  };

  // Загружаем бэкап в приватный бакет db-backups, чтобы его можно было скачать из истории.
  const DB_BACKUP_BUCKET = 'db-backups';
  const uploadDatabaseBackupToStorage = async (payload: any, fileName: string) => {
    const blob = new Blob([JSON.stringify(payload)], { type: 'application/json' });
    const path = `backups/${fileName}`;
    const { error } = await supabase.storage.from(DB_BACKUP_BUCKET).upload(path, blob, { contentType: 'application/json', upsert: true });
    if (error) throw error;
    return path;
  };

  const handleCreateDatabaseBackup = async () => {
    setDatabaseBackupLoading(true);
    try {
      const payload = await createFullDatabaseBackupSnapshot();
      const fileName = buildDatabaseBackupFileName('database_backup_manual');
      // Сохраняем в облако (для скачивания из истории) и сразу отдаём локально.
      let storedPath = '';
      try { storedPath = await uploadDatabaseBackupToStorage(payload, fileName); }
      catch (e: any) { showToast('Бэкап создан, но не загрузился в облако: ' + (e?.message || ''), 'warning'); }
      downloadDatabaseBackupBlob(payload, fileName);

      await appendDatabaseBackupLog({
        version: `Backup ${new Date().toLocaleString('ru-RU')}`,
        date: new Date().toLocaleDateString('ru-RU'),
        details: `Ручной полный бэкап БД. Таблиц: ${payload.total_tables}, строк: ${payload.total_rows}`,
        created_at: new Date().toISOString(),
        status: 'success',
        source: 'dashboard_manual',
        file_name: fileName,
        ...(storedPath ? { file_path: storedPath, bucket: DB_BACKUP_BUCKET } : {}),
      } as any);

      showToast(`Полный бэкап создан, таблиц: ${payload.total_tables}, строк: ${payload.total_rows}`, 'success');
    } catch (e: any) {
      showToast('Ошибка создания бэкапа: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setDatabaseBackupLoading(false);
    }
  };

  const [databaseDownloadingPath, setDatabaseDownloadingPath] = useState<string | null>(null);
  const handleDownloadBackupFromHistory = async (log: any) => {
    const path = String(log?.file_path || '').trim();
    const bucket = String(log?.bucket || DB_BACKUP_BUCKET).trim();
    if (!path) { showToast('Для этого бэкапа нет сохранённого файла (старая запись)', 'error'); return; }
    setDatabaseDownloadingPath(path);
    try {
      const { data, error } = await supabase.storage.from(bucket).createSignedUrl(path, 120, { download: log?.file_name || true });
      if (error || !data?.signedUrl) throw error || new Error('Не удалось получить ссылку');
      const a = document.createElement('a');
      a.href = data.signedUrl;
      a.download = log?.file_name || 'backup.json';
      document.body.appendChild(a); a.click(); a.remove();
    } catch (e: any) {
      showToast('Не удалось скачать бэкап: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setDatabaseDownloadingPath(null);
    }
  };

  const handleClearDatabaseLogs = async () => {
    if (!await confirmDialog('Очистить всю историю бэкапов? Файлы в облаке не удаляются.')) return;
    try {
      const { error } = await supabase.from('app_settings').upsert({ key: 'database_backup_logs', value: '[]' });
      if (error) throw error;
      setDatabaseLogs([]);
      showToast('История бэкапов очищена', 'success');
    } catch (e: any) {
      showToast('Ошибка очистки истории: ' + (e?.message || 'неизвестно'), 'error');
    }
  };

  const handleDownloadDatabase = async () => {
    setDatabaseDownloadLoading(true);
    try {
      const payload = await createFullDatabaseBackupSnapshot();
      const fileName = buildDatabaseBackupFileName('database_export');
      downloadDatabaseBackupBlob(payload, fileName);
      showToast(`База данных скачана, таблиц: ${payload.total_tables}, строк: ${payload.total_rows}`, 'success');
    } catch (e: any) {
      showToast('Ошибка скачивания базы: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setDatabaseDownloadLoading(false);
    }
  };

  const fetchPrintFiles = async () => {
    if (!printSupplierId) {
      setPrintFiles([]);
      return;
    }

    const { data, error } = await supabase
      .from('print_files')
      .select('*')
      .eq('supplier_id', printSupplierId)
      .order('created_at', { ascending: false });

    if (error) {
      showToast('Ошибка загрузки файлов: ' + error.message, 'error');
    } else {
      setPrintFiles(data || []);
    }
  };

  useEffect(() => {
    fetchPrintFiles();
  }, [printSupplierId]);

  const runPrintBotDiagnostics = async () => {
    if (!printSupplierId) return showToast('Выберите поставщика', 'error');
    const supplier = suppliers.find(s => String(s.id) === String(printSupplierId));
    const chatId = String((supplier as any)?.telegram_chat_id || '').trim();
    if (!chatId) return showToast('У поставщика не заполнен Telegram Chat ID', 'error');

    const token = String((telegramBotToken || '').trim());
    if (!token) return showToast('Не задан Telegram Bot Token', 'error');

    try {
      const updatesJson = await telegramService.getUpdates(token, 100);
      if (!updatesJson?.ok) throw new Error(updatesJson?.description || 'Telegram getUpdates error');

      const updates = (updatesJson.result || [])
        .map((u: any) => u?.message)
        .filter((m: any) => m && String(m?.chat?.id) === chatId)
        .sort((a: any, b: any) => (b?.date || 0) - (a?.date || 0))
        .slice(0, 20);

      const lines = updates.map((m: any, idx: number) => {
        const dt = m?.date ? new Date(m.date * 1000).toLocaleString('ru-RU') : '-';
        const text = String(m?.text || '').slice(0, 120);
        const doc = m?.document ? `doc:${m.document.file_name || m.document.file_id}` : '';
        const btn = m?.reply_markup?.keyboard ? 'keyboard' : (m?.reply_markup?.inline_keyboard ? 'inline_keyboard' : '');
        return `${idx + 1}) ${dt} | ${text || '-'} ${doc ? '| ' + doc : ''} ${btn ? '| ' + btn : ''}`;
      });

      const report = [
        `Поставщик: ${supplier?.name || '-'}`,
        `Chat ID: ${chatId}`,
        `Найдено сообщений: ${updates.length}`,
        '',
        ...lines,
      ].join('\n');

      setPrintBotDiagnostics(report);
      setPrintBotDiagnosticsOpen(true);
      showToast('Диагностика бота готова', 'success');
    } catch (e: any) {
      showToast('Ошибка диагностики бота: ' + (e?.message || 'неизвестно'), 'error');
    }
  };

  const fetchReportMetric = async (metric: string, start?: string, end?: string) => {
    const { data: stats, error } = await supabase.rpc('get_supplier_stats', {
        p_start_date: start || null,
        p_end_date: end || null
    });

    if (error) {
        console.error(`Error fetching ${metric}:`, error);
        return;
    }

    if (metric === 'stock') {
        setReportStockData(stats.map((s: any) => ({ name: s.supplier_name, value: s.received - s.shipped })));
    } else if (metric === 'payment') {
        setReportPaymentData(stats.map((s: any) => ({ name: s.supplier_name, value: s.total_payment })));
    } else if (metric === 'boxes') {
        setReportBoxData(stats.map((s: any) => ({ name: s.supplier_name, value: s.boxes })));
    } else if (metric === 'packaging') {
        setReportPackagingData(stats.map((s: any) => ({ name: s.supplier_name, value: s.packaging_cost })));
    }
  };

  const fetchReportsData = async () => {
    setLoadingReports(true);
    try {
        // Prepare all promises
        const itemsCountPromise = supabase.from('supply_items').select('*', { count: 'exact', head: true }).is('deleted_at', null);
        const suppliesCountPromise = supabase.from('supplies').select('*', { count: 'exact', head: true }).is('deleted_at', null);
        const boxDataPromise = supabase.rpc('get_box_stats');
        const allStatsPromise = supabase.rpc('get_supplier_stats', {
            p_start_date: '2000-01-01',
            p_end_date: '2099-12-31'
        });
        const suppliersDataPromise = supabase.from('suppliers').select('id, name').is('deleted_at', null);

        // Prepare metrics promises
        const metrics = ['stock', 'payment', 'boxes', 'packaging'];
        const uniqueRanges = new Map<string, string[]>();

        metrics.forEach(metric => {
            const start = reportDates[metric]?.start ?? '';
            const end = reportDates[metric]?.end ?? '';
            const key = `${start}|${end}`;
            if (!uniqueRanges.has(key)) {
                uniqueRanges.set(key, []);
            }
            uniqueRanges.get(key)?.push(metric);
        });

        const metricsPromises = Array.from(uniqueRanges.entries()).map(async ([key, metricList]) => {
            const [rawStart, rawEnd] = key.split('|');
            const start = rawStart && rawStart !== 'undefined' ? rawStart : null;
            const end = rawEnd && rawEnd !== 'undefined' ? rawEnd : null;

            const { data: stats, error } = await supabase.rpc('get_supplier_stats', {
                p_start_date: start,
                p_end_date: end
            });

            if (error) {
                console.error(`Error fetching stats for ${key}:`, error);
                return null;
            }
            return { metricList, stats };
        });

        // Execute all promises in parallel
        const [
            { count: itemsCount },
            { count: suppliesCount },
            { data: boxData },
            { data: allStats },
            { data: suppliersData },
            metricsResults
        ] = await Promise.all([
            itemsCountPromise,
            suppliesCountPromise,
            boxDataPromise,
            allStatsPromise,
            suppliersDataPromise,
            Promise.all(metricsPromises)
        ]);

        // Process Box Stats
        let avgBoxPrice = 0;
        if (boxData && boxData.length > 0) {
            avgBoxPrice = boxData[0].avg_price || 0;
            setBoxStats({
                totalAdded: boxData[0].total_added || 0,
                totalUsed: boxData[0].total_used || 0,
                currentStock: boxData[0].current_stock || 0,
                avgPrice: boxData[0].avg_price || 0
            });
        }

        // Process Global Stats
        let totalPayments = 0;
        let totalPackaging = 0;
        let totalBoxesCount = 0;

        if (allStats) {
            totalPayments = allStats.reduce((sum: number, s: any) => sum + (s.total_payment || 0), 0);
            totalPackaging = allStats.reduce((sum: number, s: any) => sum + (s.packaging_cost || 0), 0);
            totalBoxesCount = allStats.reduce((sum: number, s: any) => sum + (s.boxes || 0), 0);
        }

        const totalBoxesCost = totalBoxesCount * avgBoxPrice;
        const totalCost = totalPayments + totalPackaging + totalBoxesCost;
        const avgPriceInStock = (itemsCount || 0) > 0 ? totalCost / (itemsCount || 0) : 0;

        setReportTotals({ items: itemsCount || 0, supplies: suppliesCount || 0, avgPriceInStock });

        // Process Metrics Results
        metricsResults.forEach((result: any) => {
            if (!result) return;
            const { metricList, stats } = result;
            metricList.forEach((metric: string) => {
                if (metric === 'stock') {
                    setReportStockData(stats.map((s: any) => ({ name: s.supplier_name, value: s.received - s.shipped })));
                } else if (metric === 'payment') {
                    setReportPaymentData(stats.map((s: any) => ({ name: s.supplier_name, value: s.total_payment })));
                } else if (metric === 'boxes') {
                    setReportBoxData(stats.map((s: any) => ({ name: s.supplier_name, value: s.boxes })));
                } else if (metric === 'packaging') {
                    setReportPackagingData(stats.map((s: any) => ({ name: s.supplier_name, value: s.packaging_cost })));
                }
            });
        });

        // Process Suppliers All Time Stats
        if (suppliersData) {
            const results = suppliersData.map((supplier: any) => {
                const supplierStats = allStats ? allStats.find((s: any) => s.supplier_id === supplier.id || s.supplier_name === supplier.name) : null;
                return {
                    id: supplier.id,
                    name: supplier.name,
                    stats: supplierStats || null,
                    avgBoxPrice: avgBoxPrice
                };
            });
            setSuppliersAllTimeStats(results);
        }

    } catch (e) {
        console.error('Error fetching reports:', e);
        showToast('Ошибка загрузки отчетов', 'error');
    } finally {
        setLoadingReports(false);
    }
  };



  const validateUploadedReportSupplier = async (rows: any[], supplierId: string) => {
    try {
      const reportCodes = Array.from(new Set(
        (rows || [])
          .map((r: any) => String(r?.['Код номенклатуры'] ?? '').trim())
          .filter((x: string) => !!x)
      )).slice(0, 1000);
      if (!reportCodes.length) return true;

      // Раньше выкачивали ДО 20 000 товаров поставщика и сверяли множества — медленно.
      // Теперь два лёгких индексных count по кодам отчёта (wb_sku / article), без переноса строк.
      const [r1, r2] = await Promise.all([
        supabase.from('products').select('id', { count: 'exact', head: true }).eq('supplier_id', supplierId).is('deleted_at', null).in('wb_sku', reportCodes),
        supabase.from('products').select('id', { count: 'exact', head: true }).eq('supplier_id', supplierId).is('deleted_at', null).in('article', reportCodes),
      ]);
      if (r1.error && r2.error) throw (r1.error || r2.error);
      if (Number(r1.count || 0) > 0 || Number(r2.count || 0) > 0) return true;

      /*
       * Карточки WB — второй источник принадлежности.
       *
       * У ИП Власенко А С раздел «Товары» пуст (0 строк), а карточки кабинета
       * лежат в кэше WB — 234 штуки. Еженедельный отчёт кабинета отклонялся
       * как чужой, хотя все его коды номенклатуры есть в этом кэше.
       */
      const nmIds = reportCodes
        .map((code) => Number(code))
        .filter((nm) => Number.isFinite(nm) && nm > 0);
      if (nmIds.length) {
        const { count: cacheCount } = await supabase
          .from('wb_products_cache')
          .select('nm_id', { count: 'exact', head: true })
          .eq('supplier_id', supplierId)
          .in('nm_id', nmIds);
        if (Number(cacheCount || 0) > 0) return true;
      }

      /*
       * О товарах кабинета не знаем ничего — сверять не с чем.
       *
       * Блокировать загрузку в этом случае неправильно: отчёт, скорее всего,
       * свой, а база товаров просто ещё не заполнена.
       */
      const [allProducts, allCards] = await Promise.all([
        supabase.from('products').select('id', { count: 'exact', head: true }).eq('supplier_id', supplierId).is('deleted_at', null),
        supabase.from('wb_products_cache').select('nm_id', { count: 'exact', head: true }).eq('supplier_id', supplierId),
      ]);
      if (!Number(allProducts.count || 0) && !Number(allCards.count || 0)) return true;

      return false;
    } catch (e) {
      console.error('validateUploadedReportSupplier error', e);
      return true; // при ошибке проверки не блокируем загрузку
    }
  };


  const loadUploadedCostsForSupplier = async (supplierId: string) => {
    if (!supplierId) {
      setUploadedPersistedCostByCode({});
      return;
    }
    try {
      const { data } = await supabase.from('app_settings').select('value').eq('key', 'analytics_costs_v1').maybeSingle();
      let parsed: any = {};
      const raw = data?.value;
      if (typeof raw === 'string') {
        try { parsed = JSON.parse(raw); } catch { parsed = {}; }
      } else if (raw && typeof raw === 'object') {
        parsed = raw;
      }
      const map = (parsed?.[supplierId] && typeof parsed[supplierId] === 'object') ? parsed[supplierId] : {};
      const normalized: Record<string, number> = {};
      Object.entries(map || {}).forEach(([k, v]) => {
        const num = Number(v as any);
        if (Number.isFinite(num)) normalized[String(k)] = num;
      });
      setUploadedPersistedCostByCode(normalized);

      if ((uploadedReportAnalytics || []).length > 0) {
        const seeded: Record<string, string> = {};
        (uploadedReportAnalytics || []).forEach((r: any) => {
          const code = String(r?.code || '').trim();
          const key = `${code}|${r?.name || ''}`;
          if (code && normalized[code] != null) seeded[key] = String(normalized[code]);
        });
        setUploadedCostByKey((prev) => ({ ...seeded, ...(prev || {}) }));
      }
    } catch (e) {
      console.error('loadUploadedCostsForSupplier error', e);
      setUploadedPersistedCostByCode({});
    }
  };

  const persistUploadedCostsByCode = async (nextByCode: Record<string, number>) => {
    const { data } = await supabase.from('app_settings').select('value').eq('key', 'analytics_costs_v1').maybeSingle();
    let parsed: any = {};
    const raw = data?.value;
    if (typeof raw === 'string') {
      try { parsed = JSON.parse(raw); } catch { parsed = {}; }
    } else if (raw && typeof raw === 'object') {
      parsed = raw;
    }
    const merged = { ...(parsed || {}), [uploadedSelectedSupplierId]: nextByCode };
    const payload = JSON.stringify(merged);

    const { data: updatedRows, error: updateError } = await supabase
      .from('app_settings')
      .update({ value: payload })
      .eq('key', 'analytics_costs_v1')
      .select('key');
    if (updateError) throw updateError;
    if (!updatedRows || updatedRows.length === 0) {
      const { error: insertError } = await supabase.from('app_settings').insert({ key: 'analytics_costs_v1', value: payload });
      if (insertError) throw insertError;
    }
  };

  const saveUploadedCosts = async () => {
    if (!uploadedSelectedSupplierId) {
      showToast('Сначала выберите поставщика', 'error');
      return;
    }
    try {
      setUploadedSavingCosts(true);
      const nextByCode: Record<string, number> = { ...(uploadedPersistedCostByCode || {}) };
      Object.entries(uploadedCostByKey || {}).forEach(([key, val]) => {
        const num = Number(String(val ?? '').replace(',', '.'));
        if (key && Number.isFinite(num) && String(val).trim() !== '') nextByCode[key] = num;
      });
      await persistUploadedCostsByCode(nextByCode);
      setUploadedPersistedCostByCode(nextByCode);
      logAction('Аналитика: изменение себестоимости', `Поставщик ${suppliers.find((s:any)=>String(s.id)===uploadedSelectedSupplierId)?.name || uploadedSelectedSupplierId} · позиций: ${Object.keys(nextByCode).length}`, currentEmployee?.id);
      showToast('Себестоимость сохранена', 'success');
    } catch (e: any) {
      console.error('saveUploadedCosts error', e);
      showToast('Не удалось сохранить себестоимость', 'error');
    } finally {
      setUploadedSavingCosts(false);
    }
  };


  // Загрузка себестоимости файлом Excel (2–3 столбца: артикул поставщика + цена).
  // Матч по «Артикул поставщика» (vendor_code, напр. h156012816), fallback — «Код
  // номенклатуры» (code/nmId). Цена пишется в persistedCostByCode[code] и применяется live.
  const handleUploadCostFile = async (file: File) => {
    if (!Array.isArray(uploadedReportAnalytics) || uploadedReportAnalytics.length === 0) {
      showToast('Сначала загрузите отчёт, затем файл себестоимости', 'error');
      return;
    }
    try {
      setUploadedSavingCosts(true);
      const buf = await file.arrayBuffer();
      const aoa = await readFirstSheetAsJson<any[]>(buf, { header: 1, raw: false });
      const normArt = (v: any) => String(v ?? '').trim().toLowerCase().replace(/\s+/g, '');
      const parseMoney = (v: any) => {
        const n = Number(String(v ?? '').replace(/[^0-9.,-]/g, '').replace(/\s+/g, '').replace(',', '.'));
        return Number.isFinite(n) ? n : NaN;
      };
      const priceByArt = new Map<string, number>();
      (Array.isArray(aoa) ? aoa : []).forEach((rowArr: any) => {
        const cells = Array.isArray(rowArr) ? rowArr : Object.values(rowArr || {});
        let article = '';
        let price = NaN;
        for (const cell of cells) {
          const s = String(cell ?? '').trim();
          if (!s) continue;
          const digitsOnly = s.replace(/\s+/g, '');
          const isBigInt = /^\d{7,}$/.test(digitsOnly); // nmId-подобное — это не цена
          const hasLetter = /[a-zA-Zа-яА-Я]/.test(s);
          if (hasLetter && !article) { article = s; continue; }     // артикул поставщика (H…)
          if (!hasLetter && !isBigInt && Number.isNaN(price)) {
            const n = parseMoney(s);
            if (Number.isFinite(n) && n > 0) price = n;               // цена
          }
        }
        // Если букв нет (артикул чисто числовой) — ключом берём nmId-подобное число.
        if (!article) {
          for (const cell of cells) {
            const s = String(cell ?? '').trim();
            if (/^\d{7,}$/.test(s.replace(/\s+/g, ''))) { article = s; break; }
          }
        }
        if (article && Number.isFinite(price) && price > 0) priceByArt.set(normArt(article), price);
      });
      if (priceByArt.size === 0) {
        showToast('В файле не найдено пар «артикул + цена». Нужны столбцы: артикул поставщика и цена.', 'error');
        return;
      }
      const nextByCode: Record<string, number> = { ...(uploadedPersistedCostByCode || {}) };
      const used = new Set<string>();
      let matched = 0;
      (uploadedReportAnalytics || []).forEach((r: any) => {
        const code = String(r?.code || '').trim();
        if (!code) return;
        const vc = normArt(r?.vendor_code);
        const cd = normArt(r?.code);
        let price: number | undefined;
        let hitKey = '';
        if (vc && priceByArt.has(vc)) { price = priceByArt.get(vc); hitKey = vc; }
        else if (cd && priceByArt.has(cd)) { price = priceByArt.get(cd); hitKey = cd; }
        if (price !== undefined && price > 0) { nextByCode[code] = price; matched += 1; if (hitKey) used.add(hitKey); }
      });
      if (matched === 0) {
        showToast('Ни один артикул из файла не совпал с товарами отчёта (сверяется «Артикул поставщика»).', 'warning');
        return;
      }
      await persistUploadedCostsByCode(nextByCode);
      setUploadedPersistedCostByCode(nextByCode);
      const notMatched = priceByArt.size - used.size;
      logAction('Аналитика: себестоимость файлом', `совпало ${matched}, не совпало ${notMatched}`, currentEmployee?.id);
      showToast(`Себестоимость применена: ${matched} тов.${notMatched > 0 ? `, не совпало ${notMatched} строк файла` : ''}`, 'success');
    } catch (e: any) {
      console.error('handleUploadCostFile error', e);
      showToast('Ошибка чтения файла: ' + (e?.message || 'неизвестно'), 'error');
    } finally {
      setUploadedSavingCosts(false);
    }
  };

  const getUploadedCostKeyCandidates = (row: any) => {
    const code = String(row?.code || '').trim();
    const name = String(row?.name || '').trim();
    return Array.from(new Set([code, name ? `name:${name}` : '', code && name ? `${code}|${name}` : ''].filter(Boolean)));
  };

  const getUploadedCostValue = (row: any, persistedMap?: Record<string, number>, rowMap?: Record<string, string>) => {
    const keyMap = rowMap || uploadedCostByKey;
    for (const candidate of getUploadedCostKeyCandidates(row)) {
      const fromKey = keyMap[candidate];
      if (fromKey !== undefined && String(fromKey).trim() !== '') {
        const n = Number(String(fromKey).replace(',', '.'));
        if (Number.isFinite(n) && n > 0) return n;
      }
    }
    const persistedSource = persistedMap || uploadedPersistedCostByCode;
    for (const candidate of getUploadedCostKeyCandidates(row)) {
      const persisted = persistedSource[candidate];
      if (Number.isFinite(Number(persisted)) && Number(persisted) > 0) return Number(persisted);
    }

    const directCandidates = [
      row?.cost,
      row?.unit_cost,
      row?.unitCost,
      row?.cost_price,
      row?.costPrice,
      row?.purchase_cost,
      row?.purchaseCost,
      row?.prime_cost,
      row?.primeCost,
      row?.sebestoimost,
      row?.['Себестоимость'],
    ];
    for (const candidate of directCandidates) {
      if (candidate === undefined || candidate === null || String(candidate).trim() === '') continue;
      const n = Number(String(candidate).replace(/\s+/g, '').replace(',', '.'));
      if (Number.isFinite(n) && n > 0) return n;
    }

    return 0;
  };

  const uploadedCostEditorItems = useMemo(() => {
    const map = new Map<string, any>();
    (uploadedReportAnalytics || []).forEach((r: any) => {
      const code = String(r?.code || '').trim();
      if (!code) return;
      if (!map.has(code)) map.set(code, r);
    });
    const q = uploadedCostEditorSearch.trim().toLowerCase();
    let rows = Array.from(map.values())
      .filter((r: any) => {
        const editorKey = `${String(r?.code || '').trim()}|${String(r?.name || '').trim()}`;
        if (Array.isArray(uploadedCostEditorLockedKeys) && uploadedCostEditorLockedKeys.length > 0) {
          if (!uploadedCostEditorLockedKeys.includes(editorKey)) return false;
        } else {
          const hasPrice = getUploadedCostValue(r) > 0;
          if (uploadedCostEditorFilter === 'with_price' && !hasPrice) return false;
          if (uploadedCostEditorFilter === 'without_price' && hasPrice) return false;
        }
        if (!q) return true;
        return String(r?.code || '').toLowerCase().includes(q) || String(r?.name || '').toLowerCase().includes(q) || String(r?.vendor_code || '').toLowerCase().includes(q);
      })
      .sort((a: any, b: any) => String(a?.name || '').localeCompare(String(b?.name || ''), 'ru'));

    if (Array.isArray(uploadedCostEditorLockedKeys) && uploadedCostEditorLockedKeys.length > 0) {
      const order = new Map(uploadedCostEditorLockedKeys.map((k, idx) => [k, idx]));
      rows = rows.sort((a: any, b: any) => {
        const ak = `${String(a?.code || '').trim()}|${String(a?.name || '').trim()}`;
        const bk = `${String(b?.code || '').trim()}|${String(b?.name || '').trim()}`;
        return Number(order.get(ak) ?? 999999) - Number(order.get(bk) ?? 999999);
      });
    }
    return rows;
  }, [uploadedReportAnalytics, uploadedCostEditorSearch, uploadedCostEditorFilter, uploadedCostByKey, uploadedPersistedCostByCode]);

  const openUploadedCostEditor = () => {
    const init: Record<string, string> = {};
    (uploadedReportAnalytics || []).forEach((r: any) => {
      const v = getUploadedCostValue(r);
      if (v > 0) {
        const code = String(r?.code || '').trim();
        const name = String(r?.name || '').trim();
        if (code) init[`${code}|${name}`] = String(v);
      }
    });
    setUploadedCostEditorValues(init);
    setUploadedCostEditorSearch('');
    setUploadedCostEditorFilter('all');
    setUploadedCostEditorLockedKeys(null);
    setUploadedCostEditorOpen(true);
  };

  const saveUploadedCostsFromEditor = async () => {
    if (!uploadedSelectedSupplierId) {
      showToast('Сначала выберите поставщика', 'error');
      return;
    }
    try {
      setUploadedSavingCosts(true);
      const nextByCode: Record<string, number> = { ...(uploadedPersistedCostByCode || {}) };
      Object.entries(uploadedCostEditorValues || {}).forEach(([code, val]) => {
        const c = String(code || '').trim();
        const num = Number(String(val ?? '').replace(',', '.'));
        if (c && Number.isFinite(num) && String(val).trim() !== '') {
          nextByCode[c] = num;                                    // ключ «код|название»
          const bare = c.split('|')[0].trim();                    // и голый «код» — чтобы
          if (bare) nextByCode[bare] = num;                       // перебить устаревшее значение
        }
      });
      await persistUploadedCostsByCode(nextByCode);
      setUploadedPersistedCostByCode(nextByCode);
      const seeded: Record<string, string> = {};
      (uploadedReportAnalytics || []).forEach((r: any) => {
        const value = getUploadedCostValue(r, nextByCode);
        const code = String(r?.code || '').trim();
        const key = `${code}|${r?.name || ''}`;
        if (value > 0) seeded[key] = String(value);
      });
      setUploadedCostByKey(seeded);
      setUploadedCostEditorOpen(false);
      showToast('Себестоимость сохранена', 'success');
    } catch (e: any) {
      console.error('saveUploadedCostsFromEditor error', e);
      showToast('Не удалось сохранить себестоимость', 'error');
    } finally {
      setUploadedSavingCosts(false);
    }
  };

  // Закрытие редактора = применить + сохранить введённую себестоимость
  // (иначе при перезагрузке отчёта вернётся пустое значение из БД).
  const closeUploadedCostEditor = async () => {
    if (uploadedSelectedSupplierId) {
      try { await saveUploadedCostsFromEditor(); return; } catch { /* fallthrough */ }
    }
    setUploadedCostEditorOpen(false);
  };

  const processUploadedWbReport = (rows: any[], opts?: { turbo?: boolean }) => {
    const turbo = Boolean(opts?.turbo);
    const toNum = (v: any) => {
      // Быстрый путь: xlsx-воркер часто отдаёт числовые ячейки уже как number —
      // не гоняем String()+regex на каждой из сотен тысяч ячеек.
      if (typeof v === 'number') return Number.isFinite(v) ? v : 0;
      if (v == null || v === '') return 0;
      const n = Number(String(v).replace(/\s+/g, '').replace(',', '.'));
      return Number.isFinite(n) ? n : 0;
    };

    const salesKeys = ['Вайлдберриз реализовал Товар (Пр)', 'Продажи', 'Сумма розничной цены', 'Сумма продаж'];
    const logisticsKeys = ['Услуги по доставке товара покупателю', 'Логистика', 'Логистика (руб)', 'Стоимость логистики'];
    const payoutKeys = ['К перечислению Продавцу за реализованный Товар', 'К перечислению', 'К перечислению продавцу за товар'];
    const fineKeys = ['Общая сумма штрафов', 'Штрафы'];
    const storageKeys = ['Хранение', 'Хранение (руб)', 'Платное хранение'];
    const withholdKeys = ['Удержания', 'Прочие удержания', 'Дедукции'];
    // НДС с комиссии WB — берём прямо из колонки отчёта (точнее, чем выделять ×22/122).
    const commissionVatKeys = ['НДС с Вознаграждения Вайлдберриз', 'НДС с вознаграждения Вайлдберриз', 'НДС с Вознаграждения ВВ'];
    const commissionNetKeys = ['Вознаграждение Вайлдберриз (ВВ), без НДС', 'Вознаграждение Вайлдберриз (ВВ) без НДС', 'Вознаграждение Вайлдберриз (ВВ)'];

    const pickNum = (row: any, keys: string[]) => {
      for (const k of keys) {
        if (row?.[k] !== undefined && row?.[k] !== null && String(row?.[k]).trim() !== '') return toNum(row[k]);
      }
      return 0;
    };

    const parseAnyDate = (v: any): Date | null => {
      if (v == null || String(v).trim() === '') return null;
      if (v instanceof Date && !Number.isNaN(v.getTime())) return v;
      if (typeof v === 'number' && Number.isFinite(v)) {
        // Excel serial date support
        const excelEpoch = new Date(Date.UTC(1899, 11, 30));
        const dt = new Date(excelEpoch.getTime() + v * 24 * 60 * 60 * 1000);
        return Number.isNaN(dt.getTime()) ? null : dt;
      }
      const str = String(v).trim();

      // dd.mm.yyyy [h:mm[:ss]]
      const dmY = str.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})(?:\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?$/);
      if (dmY) {
        const [, d, m, y, hh = '0', mm = '0', ss = '0'] = dmY;
        const dt = new Date(Number(y), Number(m) - 1, Number(d), Number(hh), Number(mm), Number(ss));
        return Number.isNaN(dt.getTime()) ? null : dt;
      }

      // yyyy-mm-dd [h:mm[:ss]]
      const ymd = str.match(/^(\d{4})-(\d{1,2})-(\d{1,2})(?:\s+(\d{1,2}):(\d{1,2})(?::(\d{1,2}))?)?$/);
      if (ymd) {
        const [, y, m, d, hh = '0', mm = '0', ss = '0'] = ymd;
        const dt = new Date(Number(y), Number(m) - 1, Number(d), Number(hh), Number(mm), Number(ss));
        return Number.isNaN(dt.getTime()) ? null : dt;
      }

      const iso = new Date(str);
      return Number.isNaN(iso.getTime()) ? null : iso;
    };

    const pickDate = (row: any, keys: string[]) => {
      for (const k of keys) {
        const dt = parseAnyDate(row?.[k]);
        if (dt) return dt;
      }
      return null;
    };

    const normalizeKey = (k: string) => String(k || '').toLowerCase().replace(/\s+/g, ' ').trim();
    const compareSizesAsc = (aSize: string, bSize: string) => {
      const prep = (v: string) => String(v || '').trim().toUpperCase();
      const a = prep(aSize);
      const b = prep(bSize);
      const rank = (v: string) => {
        if (!v || v === 'БЕЗ РАЗМЕРА' || v === 'БЕЗ Р-РА' || v === 'NONE' || v === 'NO SIZE') return 100000;

        const fixed: Record<string, number> = {
          XXS: 10,
          XS: 20,
          S: 30,
          M: 40,
          L: 50,
          XL: 60,
          XXL: 70,
          XXXL: 80,
          XXXXL: 90,
        };
        if (fixed[v] != null) return fixed[v];

        const xL = v.match(/^X+L$/i);
        if (xL) return 50 + String(v).replace(/[^X]/gi, '').length * 10;

        const numXL = v.match(/^(\d+)\s*XL$/i);
        if (numXL) return 60 + Number(numXL[1]) * 10;

        const pureNum = Number(v);
        if (!Number.isNaN(pureNum) && v !== '') return 500 + pureNum;

        return 90000;
      };
      const ra = rank(a);
      const rb = rank(b);
      if (ra !== rb) return ra - rb;
      return a.localeCompare(b, 'ru', { numeric: true });
    };
    const grouped = new Map<string, any>();
    const daily = new Map<string, any>();
    // Гео/время-агрегации (склад отгрузки, ПВЗ выдачи, страна, день — итоги по всем товарам).
    const geoBucket = () => ({ sales_net: 0, payout_net: 0, logistics_sum: 0, sold_qty: 0, return_qty: 0 });
    // «Наименование офиса доставки» → главный регион/город (без улицы и дома).
    // Сводим разные написания одного региона к одному названию (Москва/МО, СПб/ЛО и т.п.).
    const canonRegion = (r: string) => {
      const low = String(r || '').toLowerCase();
      if (!low) return r;
      if (low.includes('москов') || /^москва\b/.test(low) || low === 'москва') return 'Москва и область';
      if (low.includes('санкт-петербург') || low.includes('санкт петербург') || /\bспб\b/.test(low) || low.includes('ленинградск') || /^питер\b/.test(low)) return 'Санкт-Петербург и область';
      if (low.includes('севастополь')) return 'Севастополь';
      return r;
    };
    const extractRegion = (s: string) => {
      const t = String(s || '').trim();
      if (!t) return '';
      // «Республика Татарстan», «Респ. Коми» — название идёт ПОСЛЕ слова.
      let m = t.match(/^(респ(?:ублика)?\.?\s+[А-Яа-яЁё-]+)/i);
      if (m) return canonRegion(m[1].replace(/\s+/g, ' ').trim());
      // «Томская область», «Краснодарский край», «ХМАО» — название ПЕРЕД ключевым словом.
      m = t.match(/^(.*?\b(?:область|обл\.?|край|округ|АО))/i);
      if (m) return canonRegion(m[1].trim());
      // Города фед. значения / прочее — до уличных маркеров, 1–2 слова.
      const cut = t.split(/\s+(?:улица|ул\.?|проспект|пр-?кт|пр\.?|переулок|пер\.?|шоссе|бульвар|б-р|набережная|наб\.?|площадь|пл\.?|проезд|тракт|микрорайон|мкр|д\.?\s*\d)/i)[0];
      return canonRegion(cut.split(/\s+/).slice(0, 2).join(' ').trim() || t);
    };
    const byWarehouse = new Map<string, any>();
    const byOffice = new Map<string, any>();
    const byCountry = new Map<string, any>();
    const dayTotals = new Map<string, any>();
    // Заказы/возвраты по «Виды логистики, штрафов и корректировок ВВ»:
    //   «К клиенту при продаже» = доставлено клиенту (заказ),
    //   «От клиента при возврате» = возврат от клиента.
    let orderedLegs = 0;
    let returnLegs = 0;
    let orderedRetailSum = 0;   // сумма «Цена розничная» по заказам (К клиенту при продаже)
    let periodStart: Date | null = null;
    let periodEnd: Date | null = null;
    let anyDateStart: Date | null = null;   // min/max любой даты продажи (запасной период)
    let anyDateEnd: Date | null = null;

    const reportNumberKeys = ['Номер отчета', 'Номер отчёта', '№ отчета', '№ отчёта', 'Номер документа', 'Отчет №', 'Отчёт №'];
    let reportNumber = '';
    for (const r of (rows || [])) {
      for (const k of reportNumberKeys) {
        const v = String(r?.[k] ?? '').trim();
        if (v) {
          reportNumber = v;
          break;
        }
      }
      if (reportNumber) break;
    }

    // Имена колонок определяем ОДИН раз по заголовку (а не Object.entries на каждую строку —
    // критично для отчётов на 100k+ строк).
    const headerKeys = Object.keys((rows && rows[0]) || {});
    // Период определяем ТОЛЬКО по столбцу «Дата продажи». Если столбца нет —
    // фронт предложит ручной выбор недели (флаг has_sale_date_column).
    const hasSaleDateColumn = headerKeys.some((k) => { const n = normalizeKey(String(k)); return n === 'дата продажи' || n.includes('дата продажи'); });
    // Резолвим «дорогие» колонки ОДИН раз по заголовку — на 50k+ строк сканирование всех
    // колонок строки (Object.entries) по каждой строке было главным тормозом (15–20 c).
    const matchHeader = (n: string, sets: string[][], opts?: { excludePct?: boolean; requirePct?: boolean }) => {
      if (opts?.excludePct && n.includes('%')) return false;
      if (opts?.requirePct && !n.includes('%')) return false;
      return sets.some((set) => set.every((p) => n.includes(p)));
    };
    const saleDateKeys = [
      ...headerKeys.filter((k) => normalizeKey(String(k)) === 'дата продажи'),
      ...headerKeys.filter((k) => { const n = normalizeKey(String(k)); return n !== 'дата продажи' && n.includes('дата продажи'); }),
    ];
    const acqKeys = headerKeys.filter((k) => matchHeader(normalizeKey(String(k)), [['компенсац', 'платеж'], ['комисс', 'интеграц'], ['комисс', 'организац', 'платеж'], ['эквайр']], { excludePct: true }));
    const acqPctKeys = headerKeys.filter((k) => matchHeader(normalizeKey(String(k)), [['компенсац', 'платеж'], ['комисс', 'интеграц'], ['комисс', 'эквайр']], { requirePct: true }));
    const officeKeys = headerKeys.filter((k) => matchHeader(normalizeKey(String(k)), [['наименован', 'офис', 'доставк']]));
    const pickTextKeys = (r: any, keys: string[]) => { for (const k of keys) { const t = String(r?.[k] ?? '').trim(); if (t) return t; } return ''; };
    // Налог по году — кешируем (годов в отчёте 1–2), не дёргаем getTaxRateByYear на каждой строке.
    const taxRateCache = new Map<number, number>();
    const taxRateFor = (y: number) => { let r = taxRateCache.get(y); if (r === undefined) { r = getTaxRateByYear(y); taxRateCache.set(y, r); } return r; };
    const sizeKey = headerKeys.find((k) => normalizeKey(String(k)) === 'размер') || 'Размер';
    const barcodeKey = headerKeys.find((k) => { const nk = normalizeKey(String(k)); return nk === 'баркод' || nk === 'штрихкод' || nk === 'barcode'; }) || 'Баркод';
    // Карта Баркод → Размер: у строк логистики размер часто пуст, но есть баркод.
    const getBarcode = (r: any) => String(r?.[barcodeKey] ?? r?.['Баркод'] ?? r?.['Штрихкод'] ?? '').trim();
    const getSizeRaw = (r: any) => String(r?.[sizeKey] ?? r?.['Размер'] ?? '').trim();
    const barcodeToSize = new Map<string, string>();
    (rows || []).forEach((r: any) => {
      const bc = getBarcode(r);
      const sz = getSizeRaw(r);
      if (bc && sz && !barcodeToSize.has(bc)) barcodeToSize.set(bc, sz);
    });

    (rows || []).forEach((row: any) => {
      const code = String(row?.['Код номенклатуры'] ?? row?.['nmID'] ?? '').trim();
      const name = String(row?.['Название'] ?? row?.['Предмет'] ?? row?.['Артикул поставщика'] ?? row?.['Бренд'] ?? '').trim() || 'Без названия';
      const key = `${code}|${name}`;

      const logKindRaw = String(row?.['Виды логистики, штрафов и корректировок ВВ'] ?? '').trim();
      const logKind = logKindRaw.toLowerCase();
      if (logKind.includes('к клиенту при продаже')) orderedLegs += 1;
      if (logKind.includes('от клиента при возврате')) returnLegs += 1;

      const docType = String(row?.['Тип документа'] ?? '').toLowerCase();
      const reasonRaw = String(row?.['Обоснование для оплаты'] ?? '').trim();
      const reason = reasonRaw.toLowerCase();
      const isReturnByText = docType.includes('возврат') || reason.includes('возврат');

      const sales = pickNum(row, salesKeys);
      const logistics = pickNum(row, logisticsKeys);
      const payout = pickNum(row, payoutKeys);
      const fine = pickNum(row, fineKeys);
      const storage = pickNum(row, storageKeys);
      const withhold = pickNum(row, withholdKeys);
      const qty = pickNum(row, ['Кол-во', 'Количество', 'Колво', 'Кол-во товаров', 'quantity']);
      let sizeRaw = String(row?.[sizeKey] ?? row?.['Размер'] ?? '').trim();
      // Нет размера, но есть баркод → подставляем размер по карте Баркод→Размер.
      if (!sizeRaw) { const bc = getBarcode(row); if (bc && barcodeToSize.has(bc)) sizeRaw = String(barcodeToSize.get(bc) || '').trim(); }
      const sizeValue = sizeRaw || 'Без размера';
      const acquiring = pickNum(row, acqKeys);
      const acquiringPercent = pickNum(row, acqPctKeys);
      const commissionVat = pickNum(row, commissionVatKeys);
      const commissionNet = pickNum(row, commissionNetKeys);

      const isReturn = isReturnByText || qty < 0 || sales < 0 || payout < 0;
      const isSale = !isReturn && (docType.includes('продажа') || qty > 0 || sales > 0 || payout > 0);

      const reasonIsService = [
        'логист',
        'хранен',
        'штраф',
        'удержан',
        'возмещен',
        'корректировк',
        'приемк',
        'эквайринг',
        'комисси',
      ].some((x) => reason.includes(x));

      // Qty for profit formula must be only real product ops, not service rows
      const isQtyEligibleSale = isSale && !reasonIsService;
      const isQtyEligibleReturn = isReturn && !reasonIsService;

      const hasCodeForPeriod = String(row?.['Код номенклатуры'] ?? '').trim() !== '';
      const isProductOperationForPeriod = hasCodeForPeriod && (isSale || isReturn);
      const opDate = pickDate(row, saleDateKeys);
      const opTaxRate = opDate && !Number.isNaN(opDate.getTime()) ? taxRateFor(opDate.getFullYear()) : 0;
      const signedSalesForTax = isReturn ? -Math.abs(sales) : (isSale ? Math.max(0, sales) : 0);
      const taxDelta = signedSalesForTax * opTaxRate;
      if (isProductOperationForPeriod && opDate) {
        if (!periodStart || opDate < periodStart) periodStart = opDate;
        if (!periodEnd || opDate > periodEnd) periodEnd = opDate;
      }
      if (opDate && !Number.isNaN(opDate.getTime())) {
        if (!anyDateStart || opDate < anyDateStart) anyDateStart = opDate;
        if (!anyDateEnd || opDate > anyDateEnd) anyDateEnd = opDate;
      }

      const item = grouped.get(key) || {
        code,
        name,
        vendor_code: String(row?.['Артикул поставщика'] ?? '').trim(),
        ordered_qty: 0,
        ordered_retail_sum: 0,
        sales_gross: 0,
        returns_gross: 0,
        sales_net: 0,
        logistics_sum: 0,
        logistics_forward: 0,
        logistics_logi: 0,
        logistics_return: 0,
        payout_sum: 0,
        payout_sales_sum: 0,
        payout_returns_sum: 0,
        fine_sum: 0,
        storage_sum: 0,
        withhold_sum: 0,
        sold_qty: 0,
        return_qty: 0,
        acquiring_sum: 0,
        tax_sum: 0,
        wb_commission_vat: 0,
        wb_commission_net: 0,
        acquiring_percent_sum: 0,
        acquiring_percent_count: 0,
        log_kinds: {} as Record<string, { sum: number; qty: number }>,
        size_stats: {},
      };

      // «Артикул поставщика» берём из ЛЮБОЙ строки товара, где он заполнен: группу может
      // создать служебная строка (логистика/удержание) с пустым артикулом, и тогда он терялся.
      if (!item.vendor_code) {
        const vcRow = String(row?.['Артикул поставщика'] ?? '').trim();
        if (vcRow) item.vendor_code = vcRow;
      }

      if (isReturn) {
        item.returns_gross += Math.abs(sales);
        item.payout_returns_sum += Math.abs(payout);
      } else if (isSale) {
        item.sales_gross += sales;
        item.payout_sales_sum += payout;
      }

      // Заказы по товару: шт — по легам «К клиенту при продаже»;
      // сумма заказа — «Цена розничная» со строк продажи (где «Виды логистики…» пусто и «Обоснование» = Продажа).
      if (logKind.includes('к клиенту при продаже')) item.ordered_qty += 1;
      if (logKindRaw === '' && reason.includes('продажа')) {
        const retail = pickNum(row, ['Цена розничная']);
        item.ordered_retail_sum += retail;
        orderedRetailSum += retail;
      }

      item.logistics_sum += logistics;
      // Три вида логистики. Сумма доставки лежит на строках «Логистика», а конкретный вид —
      // в столбце «Виды логистики, штрафов и корректировок ВВ»:
      //   «К клиенту при продаже»  → Продажа (доставка выкупленного товара)
      //   «...при отмене» (к/от)   → Логистика (доставка/возврат невыкупа — заказал, но не выкупил)
      //   «От клиента при возврате»→ Возврат
      if (logKind.includes('при продаже')) {
        item.logistics_forward += logistics;
      } else if (logKind.includes('при возврате')) {
        item.logistics_return += logistics;
      } else if (logKind.includes('отмен')) {
        item.logistics_logi += logistics;
      } else if (reason.includes('возврат')) {
        item.logistics_return += logistics;
      } else if (reason.includes('продажа')) {
        item.logistics_forward += logistics;
      } else {
        item.logistics_logi += logistics;
      }
      // Разбивка логистики по ВСЕМ видам из «Виды логистики…» (для детализации) + кол-во штук.
      if (logistics) {
        const lk = logKindRaw || reasonRaw || 'Прочее';
        const cur = item.log_kinds[lk] || { sum: 0, qty: 0 };
        cur.sum += logistics;
        cur.qty += Math.abs(qty) > 0 ? Math.abs(qty) : 1;
        item.log_kinds[lk] = cur;
      }
      item.payout_sum += payout;
      item.fine_sum += fine;
      item.storage_sum += storage;
      item.withhold_sum += withhold;
      item.acquiring_sum += acquiring;
      item.wb_commission_vat += commissionVat;
      item.wb_commission_net += commissionNet;
      item.tax_sum += taxDelta;
      if (acquiringPercent) {
        item.acquiring_percent_sum += acquiringPercent;
        item.acquiring_percent_count += 1;
      }

      // Размер привязываем и к сервисным строкам (логистика/хранение/штраф),
      // если в строке указан реальный размер — тогда логистика по размерам точная.
      const hasRealSize = !!sizeValue && sizeValue !== 'Без размера';
      if (isSale || isReturn || hasRealSize) {
        if (!item.size_stats[sizeValue]) {
          item.size_stats[sizeValue] = {
            sold: 0,
            ret: 0,
            sales_gross: 0,
            returns_gross: 0,
            logistics_sum: 0,
            payout_sales_sum: 0,
            payout_returns_sum: 0,
            fine_sum: 0,
            storage_sum: 0,
            withhold_sum: 0,
            acquiring_sum: 0,
            tax_sum: 0,
            acquiring_percent_sum: 0,
            acquiring_percent_count: 0,
            log_kinds: {} as Record<string, { sum: number; qty: number }>,
          };
        }

        const sizeStat = item.size_stats[sizeValue];
        sizeStat.logistics_sum += logistics;
        if (logistics) {
          const lk = logKindRaw || reasonRaw || 'Прочее';
          const cur = sizeStat.log_kinds[lk] || { sum: 0, qty: 0 };
          cur.sum += logistics;
          cur.qty += Math.abs(qty) > 0 ? Math.abs(qty) : 1;
          sizeStat.log_kinds[lk] = cur;
        }
        sizeStat.fine_sum += fine;
        sizeStat.storage_sum += storage;
        sizeStat.withhold_sum += withhold;
        sizeStat.acquiring_sum += acquiring;
        sizeStat.tax_sum += taxDelta;
        if (acquiringPercent) {
          sizeStat.acquiring_percent_sum += acquiringPercent;
          sizeStat.acquiring_percent_count += 1;
        }

        if (isSale) {
          if (isQtyEligibleSale) {
            const saleQty = Math.abs(qty);
            const finalSaleQty = saleQty > 0 ? saleQty : 1;
            item.sold_qty += finalSaleQty;
            sizeStat.sold += finalSaleQty;
          }
          sizeStat.sales_gross += sales;
          sizeStat.payout_sales_sum += payout;
        } else if (isReturn) {
          if (isQtyEligibleReturn) {
            const retQty = Math.abs(qty);
            const finalRetQty = retQty > 0 ? retQty : 1;
            item.return_qty += finalRetQty;
            sizeStat.ret += finalRetQty;
          }
          sizeStat.returns_gross += Math.abs(sales);
          sizeStat.payout_returns_sum += Math.abs(payout);
        }
      }

      // Per-product дневная серия нужна только для НЕ-turbo (легаси-график). На больших
      // отчётах (turbo) не строим её — экономим память/время.
      const hasDateForDaily = !turbo && opDate && !Number.isNaN(opDate.getTime());
      if (hasDateForDaily) {
        const d = opDate as Date;
        const dKey = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
        const dk = `${key}|${dKey}`;
        const cur = daily.get(dk) || {
          code,
          name,
          date: dKey,
          sales_net: 0,
          returns_gross: 0,
          logistics_sum: 0,
          payout_net: 0,
          fine_sum: 0,
          storage_sum: 0,
          withhold_sum: 0,
          to_pay_total: 0,
          sold_qty: 0,
          return_qty: 0,
          acquiring_sum: 0,
        };

        cur.logistics_sum += logistics;
        cur.fine_sum += fine;
        cur.storage_sum += storage;
        cur.withhold_sum += withhold;
        cur.acquiring_sum += acquiring;

        if (isSale) {
          cur.sales_net += Math.max(0, sales);
          cur.payout_net += Math.max(0, payout);
          if (isQtyEligibleSale) cur.sold_qty += Math.abs(qty) > 0 ? Math.abs(qty) : 1;
        } else if (isReturn) {
          cur.returns_gross += Math.abs(sales);
          cur.payout_net -= Math.abs(payout);
          if (isQtyEligibleReturn) cur.return_qty += Math.abs(qty) > 0 ? Math.abs(qty) : 1;
        }

        cur.to_pay_total = Number(cur.payout_net || 0) - Number(cur.logistics_sum || 0) - Number(cur.storage_sum || 0) - Number(cur.fine_sum || 0) - Number(cur.withhold_sum || 0);
        daily.set(dk, cur);
      }

      // Гео/время агрегации (только продуктовые операции)
      if (isSale || isReturn) {
        // Только точная колонка «Склад» (не «коэффициент склада» — там числа).
        let wh = String(row?.['Склад'] ?? '').trim() || '—';
        if (/^[\d.,]+$/.test(wh)) wh = '—';   // отбрасываем числовой мусор
        const officeRaw = pickTextKeys(row, officeKeys);
        const office = extractRegion(officeRaw) || '—';
        const country = String(row?.['Страна'] ?? '').trim() || '—';
        const addGeo = (m: Map<string, any>, k: string) => {
          if (!k || k === '—') return;
          const e = m.get(k) || { key: k, ...geoBucket() };
          if (isSale) { e.sales_net += Math.max(0, sales); e.payout_net += Math.max(0, payout); if (isQtyEligibleSale) e.sold_qty += Math.abs(qty) > 0 ? Math.abs(qty) : 1; }
          else { e.sales_net -= Math.abs(sales); e.payout_net -= Math.abs(payout); if (isQtyEligibleReturn) e.return_qty += Math.abs(qty) > 0 ? Math.abs(qty) : 1; }
          e.logistics_sum += logistics;
          m.set(k, e);
        };
        addGeo(byWarehouse, wh);
        addGeo(byOffice, office);
        addGeo(byCountry, country);
        if (opDate && !Number.isNaN(opDate.getTime())) {
          const dKey = `${opDate.getFullYear()}-${String(opDate.getMonth() + 1).padStart(2, '0')}-${String(opDate.getDate()).padStart(2, '0')}`;
          const e = dayTotals.get(dKey) || { key: dKey, ...geoBucket() };
          if (isSale) { e.sales_net += Math.max(0, sales); e.payout_net += Math.max(0, payout); if (isQtyEligibleSale) e.sold_qty += Math.abs(qty) > 0 ? Math.abs(qty) : 1; }
          else { e.sales_net -= Math.abs(sales); e.payout_net -= Math.abs(payout); if (isQtyEligibleReturn) e.return_qty += Math.abs(qty) > 0 ? Math.abs(qty) : 1; }
          e.logistics_sum += logistics;
          dayTotals.set(dKey, e);
        }
      }

      // Заказы по дню — СЧИТАЕМ ОТДЕЛЬНО (не под гейтом isSale||isReturn), т.к. леги
      // «к клиенту при продаже» приходят строками «Логистика», а не «Продажа»:
      //   кол-во = леги «к клиенту при продаже»; сумма = Σ «Цена розничная» по строкам продажи.
      if (opDate && !Number.isNaN(opDate.getTime())) {
        const isOrderLeg = logKind.includes('к клиенту при продаже');
        const isSaleRow = logKindRaw === '' && reason.includes('продажа');
        if (isOrderLeg || isSaleRow) {
          const dKey = `${opDate.getFullYear()}-${String(opDate.getMonth() + 1).padStart(2, '0')}-${String(opDate.getDate()).padStart(2, '0')}`;
          const e = dayTotals.get(dKey) || { key: dKey, ...geoBucket() };
          if (isOrderLeg) e.ordered_qty = (e.ordered_qty || 0) + (Math.abs(qty) > 0 ? Math.abs(qty) : 1);
          if (isSaleRow) e.ordered_retail_sum = (e.ordered_retail_sum || 0) + pickNum(row, ['Цена розничная']);
          dayTotals.set(dKey, e);
        }
      }

      grouped.set(key, item);
    });

    const analytics = [...grouped.values()].map((x) => {
      const salesNet = x.sales_gross - x.returns_gross;
      const soldNetQty = Math.max(0, Number(x.sold_qty || 0) - Number(x.return_qty || 0));
      const payoutNet = Number(x.payout_sales_sum || 0) - Number(x.payout_returns_sum || 0);
      const toPayTotal = payoutNet - Number(x.logistics_sum || 0) - Number(x.storage_sum || 0) - Number(x.fine_sum || 0) - Number(x.withhold_sum || 0);
      const sizeBreakdown = Object.entries(x.size_stats || {})
        .map(([size, st]: any) => {
          const sold = Number((st as any)?.sold || 0);
          const ret = Number((st as any)?.ret || 0);
          const net = sold - ret;
          const salesGross = Number((st as any)?.sales_gross || 0);
          const returnsGross = Number((st as any)?.returns_gross || 0);
          const salesNetBySize = salesGross - returnsGross;
          const payoutNetBySize = Number((st as any)?.payout_sales_sum || 0) - Number((st as any)?.payout_returns_sum || 0);
          const logisticsBySize = Number((st as any)?.logistics_sum || 0);
          const fineBySize = Number((st as any)?.fine_sum || 0);
          const storageBySize = Number((st as any)?.storage_sum || 0);
          const withholdBySize = Number((st as any)?.withhold_sum || 0);
          const acquiringBySize = Number((st as any)?.acquiring_sum || 0);
          const taxBySize = Number((st as any)?.tax_sum || 0);
          const toPayBySize = payoutNetBySize - logisticsBySize - fineBySize - storageBySize - withholdBySize;
          const acquiringPercentBySize = salesNetBySize > 0 ? (acquiringBySize / salesNetBySize) * 100 : 0;
          return {
            size: String(size),
            sold,
            ret,
            net,
            sales_net: salesNetBySize,
            returns_gross: returnsGross,
            logistics_sum: logisticsBySize,
            payout_net: payoutNetBySize,
            fine_sum: fineBySize,
            storage_sum: storageBySize,
            withhold_sum: withholdBySize,
            to_pay_total: toPayBySize,
            sold_qty: sold,
            sold_net_qty: Math.max(0, net),
            return_qty: ret,
            acquiring_sum: acquiringBySize,
            tax_sum: taxBySize,
            acquiring_percent: acquiringPercentBySize,
            log_kinds: { ...((st as any)?.log_kinds || {}) },
          };
        })
        .filter((z: any) => {
          const allZero =
            Number(z?.sales_net || 0) === 0 &&
            Number(z?.returns_gross || 0) === 0 &&
            Number(z?.logistics_sum || 0) === 0 &&
            Number(z?.payout_net || 0) === 0 &&
            Number(z?.fine_sum || 0) === 0 &&
            Number(z?.storage_sum || 0) === 0 &&
            Number(z?.withhold_sum || 0) === 0 &&
            Number(z?.to_pay_total || 0) === 0 &&
            Number(z?.sold_net_qty || 0) === 0 &&
            Number(z?.return_qty || 0) === 0 &&
            Number(z?.acquiring_sum || 0) === 0;
          return !allZero;
        })
        .sort((a: any, b: any) => compareSizesAsc(String(a?.size || ''), String(b?.size || '')));

      return {
        ...x,
        sales_net: salesNet,
        sold_net_qty: soldNetQty,
        payout_net: payoutNet,
        to_pay_total: toPayTotal,
        size_breakdown: sizeBreakdown.map((z: any) => `${z.size}: ${z.net}`).join(' • '),
        size_breakdown_list: sizeBreakdown,
        acquiring_percent: salesNet > 0 ? (Number(x.acquiring_sum || 0) / salesNet) * 100 : 0,
      };
    }).sort((a, b) => Number(b.sales_net || 0) - Number(a.sales_net || 0));

    // Локальная дата YYYY-MM-DD без UTC-сдвига (toISOString уводил период на день назад).
    const localISO = (d: Date | null) => d ? `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}` : null;
    // Период по «Дата продажи»: конец = ПОСЛЕДНЯЯ дата продажи, начало = РЕАЛЬНАЯ первая
    // дата продажи, но не раньше чем конец − 6 дней. Так короткий отчёт (напр. продажи
    // только 29–31.12) показывает свой настоящий диапазон, а единичные старые строки
    // (возвраты/корректировки за прошлые месяцы) не растягивают период дальше недели.
    const finalPeriodEnd = periodEnd || anyDateEnd;
    let finalPeriodStart = periodStart || anyDateStart;
    if (finalPeriodEnd) {
      const weekFloor = new Date(finalPeriodEnd.getTime());
      weekFloor.setDate(weekFloor.getDate() - 6);
      finalPeriodStart = (finalPeriodStart && finalPeriodStart.getTime() > weekFloor.getTime())
        ? finalPeriodStart
        : weekFloor;
    }
    const summary = {
      report_number: reportNumber || null,
      period_start: localISO(finalPeriodStart),
      period_end: localISO(finalPeriodEnd),
      has_sale_date_column: hasSaleDateColumn,
      items: analytics.length,
      sales_net: analytics.reduce((s, x) => s + Number(x.sales_net || 0), 0),
      returns_gross: analytics.reduce((s, x) => s + Number(x.returns_gross || 0), 0),
      logistics_sum: analytics.reduce((s, x) => s + Number(x.logistics_sum || 0), 0),
      logistics_forward: analytics.reduce((s, x) => s + Number(x.logistics_forward || 0), 0),
      logistics_logi: analytics.reduce((s, x) => s + Number(x.logistics_logi || 0), 0),
      logistics_return: analytics.reduce((s, x) => s + Number(x.logistics_return || 0), 0),
      payout_sum: analytics.reduce((s, x) => s + Number(x.payout_sum || 0), 0),
      payout_net: analytics.reduce((s, x) => s + Number(x.payout_net || 0), 0),
      fine_sum: analytics.reduce((s, x) => s + Number(x.fine_sum || 0), 0),
      storage_sum: analytics.reduce((s, x) => s + Number(x.storage_sum || 0), 0),
      withhold_sum: analytics.reduce((s, x) => s + Number(x.withhold_sum || 0), 0),
      to_pay_total: analytics.reduce((s, x) => s + Number(x.to_pay_total || 0), 0),
      sold_qty: analytics.reduce((s, x) => s + Number(x.sold_qty || 0), 0),
      return_qty: analytics.reduce((s, x) => s + Number(x.return_qty || 0), 0),
      ordered_qty: orderedLegs,
      ordered_retail_sum: orderedRetailSum,
      return_legs_qty: returnLegs,
      acquiring_sum: analytics.reduce((s, x) => s + Number(x.acquiring_sum || 0), 0),
      acquiring_percent: (analytics.reduce((s, x) => s + Number(x.acquiring_sum || 0), 0) > 0 && analytics.reduce((s, x) => s + Number(x.sales_net || 0), 0) > 0)
        ? (analytics.reduce((s, x) => s + Number(x.acquiring_sum || 0), 0) / analytics.reduce((s, x) => s + Number(x.sales_net || 0), 0)) * 100
        : 0,
      tax_sum: analytics.reduce((s, x) => s + Number(x.tax_sum || 0), 0),
      wb_commission_vat: analytics.reduce((s, x) => s + Number(x.wb_commission_vat || 0), 0),
      wb_commission_net: analytics.reduce((s, x) => s + Number(x.wb_commission_net || 0), 0),
      profit_total: analytics.reduce((s, x) => {
        const sold = Number(x.sold_qty || 0);
        const cost = Number(uploadedPersistedCostByCode[String(x.code || '').trim()] || 0);
        const avg = sold > 0 ? (Number(x.to_pay_total || 0) / sold) - cost : 0;
        const baseProfit = avg * sold;
        const taxValue = Number(x.tax_sum || 0);
        return s + (baseProfit - taxValue);
      }, 0),
    };

    const dailySeriesMap: Record<string, { code: string; name: string; points: any[] }> = {};
    if (!turbo) {
      Array.from(daily.values()).forEach((d: any) => {
        const k = `${String(d?.code || '')}|${String(d?.name || '')}`;
        if (!dailySeriesMap[k]) dailySeriesMap[k] = { code: String(d?.code || ''), name: String(d?.name || ''), points: [] };
        dailySeriesMap[k].points.push(d);
      });
      Object.values(dailySeriesMap).forEach((v: any) => v.points.sort((a: any, b: any) => String(a?.date || '').localeCompare(String(b?.date || ''))));
    }

    setUploadedDailySeries(dailySeriesMap);
    if (!uploadedChartKey && !turbo) {
      const firstK = Object.keys(dailySeriesMap)[0] || '';
      if (firstK) setUploadedChartKey(firstK);
    }

    setUploadedReportAnalytics(analytics);
    setUploadedReportSummary(summary);
    // Гео/время агрегации для инфографики
    const finishGeo = (m: Map<string, any>) => {
      const arr = [...m.values()].filter((e) => e.sales_net > 0 || e.sold_qty > 0);
      const tot = arr.reduce((s, e) => s + Math.max(0, e.sales_net), 0);
      return arr.map((e) => ({
        ...e,
        buyout_pct: (e.sold_qty + e.return_qty) > 0 ? (e.sold_qty / (e.sold_qty + e.return_qty)) * 100 : 0,
        logistics_pct: e.sales_net > 0 ? (e.logistics_sum / e.sales_net) * 100 : 0,
        share_pct: tot > 0 ? (Math.max(0, e.sales_net) / tot) * 100 : 0,
      })).sort((a, b) => b.sales_net - a.sales_net);
    };
    const geoObj = {
      byWarehouse: finishGeo(byWarehouse),
      byOffice: finishGeo(byOffice),
      byCountry: finishGeo(byCountry),
      dailyTotals: [...dayTotals.values()].sort((a, b) => String(a.key).localeCompare(String(b.key))),
    };
    setUploadedReportGeo(geoObj);
    // Сохраняем гео-снимок в summary, чтобы новая «Сводка» восстанавливалась из истории без исходного файла.
    try { (summary as any).geo_snapshot = geoObj; } catch {}
    const seededCosts: Record<string, string> = {};
    const missingCostValues: Record<string, string> = {};
    let missingCount = 0;

    analytics.forEach((r: any) => {
      const code = String(r?.code || '').trim();
      const key = `${code}|${r?.name || ''}`;
      const resolvedCost = getUploadedCostValue(r);
      if (code && Number.isFinite(Number(resolvedCost)) && Number(resolvedCost) > 0) {
        seededCosts[key] = String(resolvedCost);
      } else if (code) {
        missingCostValues[key] = '';
        missingCount += 1;
      }
    });

    setUploadedCostByKey(seededCosts);

    if (missingCount > 0 && !turbo) {
      setUploadedCostEditorValues((prev) => ({ ...prev, ...missingCostValues }));
      setUploadedCostEditorSearch('');
      // Показываем ТОЛЬКО товары без себестоимости (а не весь список).
      setUploadedCostEditorFilter('without_price');
      setUploadedCostEditorLockedKeys(Object.keys(missingCostValues));
      setUploadedCostEditorOpen(true);
      showToast(`Найдено новых товаров без себестоимости: ${missingCount}. Заполните себестоимость.`, 'warning');
    } else if (turbo) {
      showToast(`Турбо-режим: аналитика построена (${analytics.length} номенклатур), графики и авто-окно себестоимости отключены для скорости`, 'info');
    } else {
      showToast(`Аналитика построена: ${analytics.length} номенклатур`, 'success');
    }
    return { analytics, summary };
  };



  const ensureAnalyticsSuppliers = async () => {
    if (Array.isArray(suppliers) && suppliers.length > 0) return;
    try {
      const { data, error } = await supabase
        .from('suppliers')
        .select('id, name, telegram_chat_id, wb_api_token, wb_adv_api_token, created_at, deleted_at')
        .is('deleted_at', null)
        .order('created_at', { ascending: false });
      if (error) throw error;
      if (Array.isArray(data) && data.length > 0) {
        setSuppliers(data as any);
      }
    } catch (e) {
      console.error('ensureAnalyticsSuppliers error', e);
    }
  };

  const loadAnalyticsSupplierOptions = async () => {
    try {
      const fromState = (suppliers || [])
        .filter((x: any) => String(x?.name || '').trim())
        .map((x: any) => ({ id: String(x.id), name: String(x.name) }));
      if (fromState.length > 0) {
        setUploadedAnalyticsSuppliers(fromState);
        return;
      }

      // direct fetch (light columns)
      const { data, error } = await supabase
        .from('suppliers')
        .select('id, name')
        .is('deleted_at', null)
        .order('created_at', { ascending: false });
      if (!error && Array.isArray(data) && data.length > 0) {
        setUploadedAnalyticsSuppliers(data.map((x: any) => ({ id: String(x.id), name: String(x.name || '') })).filter((x: any) => x.name));
        return;
      }

      // fallback from history if suppliers endpoint temporarily unavailable
      const { data: hist } = await supabase
        .from('analytics_upload_history')
        .select('supplier_id, supplier_name')
        .order('created_at', { ascending: false })
        .limit(200);
      const uniq = new Map<string, string>();
      (hist || []).forEach((h: any) => {
        const id = String(h?.supplier_id || '').trim();
        const name = String(h?.supplier_name || '').trim();
        if (id && name && !uniq.has(id)) uniq.set(id, name);
      });
      const arr = Array.from(uniq.entries()).map(([id, name]) => ({ id, name }));
      if (arr.length > 0) setUploadedAnalyticsSuppliers(arr);
    } catch (e) {
      console.error('loadAnalyticsSupplierOptions error', e);
    }
  };

    const loadUploadedRawReportHistory = async (supplierId: string) => {
    if (!supplierId) {
      setUploadedRawReports([]);
      return;
    }
    try {
      // Лёгкий список: без тяжёлых rows_json/summary_json — только метаданные.
      let rawQuery = supabase
        .from('analytics_upload_reports_raw')
        .select('id, supplier_id, supplier_name, file_name, period_start, period_end, report_number, created_at, rn:summary_json->>report_number, src_bucket:summary_json->>source_file_bucket, src_path:summary_json->>source_file_path');
      rawQuery = supplierId === ANY_SUPPLIER_ID ? rawQuery.is('supplier_id', null) : rawQuery.eq('supplier_id', supplierId);
      const { data, error } = await rawQuery
        .order('period_start', { ascending: true, nullsFirst: false })
        .order('created_at', { ascending: true })
        .limit(300);
      if (error) throw error;
      const light = (Array.isArray(data) ? data : []).map((r: any) => ({
        ...r,
        report_number: r.report_number || r.rn || null,
        summary_json: { report_number: r.report_number || r.rn || null, period_start: r.period_start, period_end: r.period_end, source_file_bucket: r.src_bucket || null, source_file_path: r.src_path || null },
      }));
      setUploadedRawReports(light);
    } catch (e) {
      console.error('loadUploadedRawReportHistory error', e);
      setUploadedRawReports([]);
    }
  };

  const saveUploadedRawReportHistory = async (rows: any[], fileName?: string, summaryArg?: any, sourceFile?: File) => {
    if (!uploadedSelectedSupplierId || !Array.isArray(rows) || !rows.length) return;
    const isAnySup = uploadedSelectedSupplierId === ANY_SUPPLIER_ID;
    const supplierDbId = isAnySup ? null : uploadedSelectedSupplierId;
    const supplierPathId = isAnySup ? '_any_' : uploadedSelectedSupplierId;
    try {
      const supplier = (suppliers || []).find((s: any) => String(s?.id) === String(uploadedSelectedSupplierId));
      const summary = summaryArg || null;
      const reportNumber = String(summary?.report_number || '').trim();
      const ps = summary?.period_start ? new Date(summary.period_start).toLocaleDateString('ru-RU') : '-';
      const pe = summary?.period_end ? new Date(summary.period_end).toLocaleDateString('ru-RU') : '-';
      const supplierName = supplier?.name || 'Без поставщика';
      const defaultName = `Период Продаж_${ps}_${pe}_${supplierName}`;

      let sourceFileBucket: string | null = null;
      let sourceFilePath: string | null = null;
      let sourceFileSize: number | null = null;
      if (sourceFile && uploadedSelectedSupplierId) {
        try {
          const safeName = String(fileName || sourceFile.name || 'raw_report.xlsx').replace(/[^a-zA-Z0-9._-]+/g, '_');
          const now = new Date();
          const yyyy = String(now.getFullYear());
          const mm = String(now.getMonth() + 1).padStart(2, '0');
          const dd = String(now.getDate()).padStart(2, '0');
          const targetPath = `${supplierPathId}/${yyyy}/${mm}/${dd}/${Date.now()}_${safeName}`;
          const { error: uploadErr } = await supabase.storage.from(RAW_REPORTS_BUCKET).upload(targetPath, sourceFile, {
            cacheControl: '3600',
            upsert: false,
            contentType: sourceFile.type || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
          });
          if (!uploadErr) {
            sourceFileBucket = RAW_REPORTS_BUCKET;
            sourceFilePath = targetPath;
            sourceFileSize = Number(sourceFile.size || 0);
          } else {
            console.error('raw source upload error', uploadErr);
            showToast('Исходный файл не загружен в Storage, сохранены данные отчёта', 'warning');
          }
        } catch (storageErr) {
          console.error('raw source upload exception', storageErr);
          showToast('Ошибка Storage: исходный файл не загружен, сохранены данные отчёта', 'warning');
        }
      }

      // Hotfix: never persist full raw rows in DB to avoid memory pressure/crashes
      const shouldStoreRawRows = false;
      showToast(`RAW строки (${rows.length.toLocaleString('ru-RU')}) не сохраняются в БД: сохраняется только сводка`, 'info');

      const payload: any = {
        supplier_id: supplierDbId,
        supplier_name: supplierName,
        file_name: defaultName,
        period_start: summary?.period_start ? new Date(summary.period_start).toISOString().slice(0, 10) : null,
        period_end: summary?.period_end ? new Date(summary.period_end).toISOString().slice(0, 10) : null,
        report_number: reportNumber || null,
        summary_json: { ...(summary || {}), source_file_name: fileName || null, source_file_bucket: sourceFileBucket, source_file_path: sourceFilePath, source_file_size: sourceFileSize, original_rows_count: Array.isArray(rows) ? rows.length : 0, rows_json_truncated: !shouldStoreRawRows },
        rows_json: shouldStoreRawRows ? rows : [],
      };

      const saveWithPayload = async (p: any) => {
        // Дедуп: по номеру отчёта. Если номера нет — по поставщику + периоду, но только
        // среди строк БЕЗ номера: за один период бывает несколько разных отчётов
        // (маленький и большой), и они не должны затирать друг друга.
        let existingId: string | null = null;
        const supFilter = (q: any) => isAnySup ? q.is('supplier_id', null) : q.eq('supplier_id', uploadedSelectedSupplierId);
        if (!uploadedCheckDuplicates) {
          existingId = null; // проверка дублей выключена галочкой — всегда новая запись
        } else if (reportNumber) {
          const { data: existing, error: findErr } = await supFilter(supabase
            .from('analytics_upload_reports_raw')
            .select('id'))
            .eq('report_number', reportNumber)
            .maybeSingle();
          if (findErr) throw findErr;
          existingId = existing?.id ? String(existing.id) : null;
        } else if (p?.period_start && p?.period_end) {
          const { data: existing, error: findErr } = await supFilter(supabase
            .from('analytics_upload_reports_raw')
            .select('id'))
            .eq('period_start', p.period_start)
            .eq('period_end', p.period_end)
            .is('report_number', null)
            .limit(1)
            .maybeSingle();
          if (findErr) throw findErr;
          existingId = existing?.id ? String(existing.id) : null;
        }
        if (existingId) {
          const { error } = await supabase.from('analytics_upload_reports_raw').update(p).eq('id', existingId);
          if (error) throw error;
        } else {
          const { error } = await supabase.from('analytics_upload_reports_raw').insert(p);
          if (error) throw error;
        }
      };

      const saveWithRetry = async (p: any, attempts = 3) => {
        let lastErr: any = null;
        for (let i = 1; i <= attempts; i += 1) {
          try {
            await saveWithPayload(p);
            return;
          } catch (err: any) {
            lastErr = err;
            const msg = String(err?.message || err || '').toLowerCase();
            const retryable = msg.includes('failed to fetch') || msg.includes('timeout') || msg.includes('network') || msg.includes('gateway');
            if (!retryable || i >= attempts) break;
            await new Promise((r) => setTimeout(r, 500 * i));
          }
        }
        throw lastErr;
      };

      try {
        await saveWithRetry(payload, 3);
      } catch (firstErr: any) {
        console.error('saveUploadedRawReportHistory full payload error', firstErr);

        // fallback for older table schema and/or oversized payload: keep rows + summary without binary file
        const fallbackPayload: any = {
          supplier_id: supplierDbId,
          supplier_name: supplierName,
          file_name: defaultName,
          summary_json: { ...(summary || {}), source_file_name: fileName || null, source_file_bucket: sourceFileBucket, source_file_path: sourceFilePath, source_file_size: sourceFileSize },
          rows_json: shouldStoreRawRows ? rows : [],
        };

        try {
          await saveWithRetry(fallbackPayload, 2);
          showToast('Отчёт сохранён в облегченном формате', 'info');
        } catch (secondErr: any) {
          console.error('saveUploadedRawReportHistory fallback error', secondErr);
          throw secondErr;
        }
      }

      await loadUploadedRawReportHistory(uploadedSelectedSupplierId);
    } catch (e: any) {
      console.error('saveUploadedRawReportHistory error', e);
      showToast(`Не удалось сохранить WB отчёт в БД: ${e?.message || 'ошибка'}`, 'error');
    }
  };

  const fetchRawRowsByIds = async (ids: string[]) => {
    const cleanIds = Array.from(new Set((ids || []).map((x) => String(x || '').trim()).filter(Boolean)));
    if (!cleanIds.length) return [] as any[];
    const { data, error } = await supabase
      .from('analytics_upload_reports_raw')
      .select('id, rows_json')
      .in('id', cleanIds as any)
      .limit(Math.max(1, cleanIds.length));
    if (error) throw error;
    const byId = new Map<string, any[]>();
    (data || []).forEach((r: any) => {
      byId.set(String(r?.id || ''), Array.isArray(r?.rows_json) ? r.rows_json : []);
    });
    return cleanIds.flatMap((id) => byId.get(id) || []);
  };

  // Достаёт строки отчёта в порядке: 1) встроенные rows_json, 2) rows_json в БД,
  // 3) ПЕРЕ-ПАРСИНГ исходного xlsx из Storage. Третий путь и решает проблему:
  // когда добавлен новый расчёт, не нужно вручную грузить файл заново — берём
  // уже сохранённый исходник и пересчитываем актуальным кодом.
  const getRowsForRawItem = async (item: any): Promise<any[]> => {
    let rows = Array.isArray(item?.rows_json) ? item.rows_json : [];
    if (rows.length) return rows;
    if (item?.id) {
      try { rows = await fetchRawRowsByIds([String(item.id)]); } catch { /* ignore */ }
      if (rows.length) return rows;
    }
    const bucket = String(item?.summary_json?.source_file_bucket || '').trim();
    const path = String(item?.summary_json?.source_file_path || '').trim();
    if (bucket && path) {
      try {
        const { data, error } = await supabase.storage.from(bucket).download(path);
        if (!error && data) return await readFirstSheetAsJsonFast(data as any);
      } catch (e) { console.error('getRowsForRawItem reparse error', e); }
    }
    return [];
  };

  const openUploadedRawHistoryItem = async (item: any) => {
    try {
      const rows = await getRowsForRawItem(item);
      if (!rows.length) {
        showToast('Нет данных и исходного файла — загрузите этот отчёт заново один раз', 'error');
        return;
      }
      const turbo = rows.length >= TURBO_MODE_ROWS;
      processUploadedWbReport(rows, { turbo });
      setUploadedRawHistoryPickerOpen(false);
      showToast('WB отчёт открыт (пересчитан актуальным кодом)', 'success');
    } catch (e) {
      console.error('openUploadedRawHistoryItem error', e);
      showToast('Не удалось открыть WB отчёт из истории', 'error');
    }
  };

  const openUploadedRawHistoryMonth = async (items: any[]) => {
    try {
      const list = Array.isArray(items) ? items : [];
      let rows: any[] = [];
      for (const it of list) rows = rows.concat(await getRowsForRawItem(it));
      if (!rows.length) {
        showToast('Нет данных WB отчётов за выбранный месяц (нет исходников)', 'error');
        return;
      }
      const turbo = rows.length >= TURBO_MODE_ROWS;
      processUploadedWbReport(rows, { turbo });
      setUploadedRawHistoryPickerOpen(false);
      showToast('Открыт объединённый WB отчёт за месяц', 'success');
    } catch (e) {
      console.error('openUploadedRawHistoryMonth error', e);
      showToast('Не удалось открыть отчёт за месяц', 'error');
    }
  };

  // Пересчёт отчёта из исходника + перезапись снапшота в «Отчёты» (precomputed
  // история), чтобы новые показатели сохранились и подтянулись без перезагрузки файла.
  const recomputeRawHistoryItem = async (item: any, opts?: { silent?: boolean }) => {
    const rows = await getRowsForRawItem(item);
    if (!rows.length) {
      if (!opts?.silent) showToast('Нет исходного файла для пересчёта — загрузите отчёт заново один раз', 'error');
      return false;
    }
    const turbo = rows.length >= TURBO_MODE_ROWS;
    const result = processUploadedWbReport(rows, { turbo });
    if (result?.summary) {
      const sm: any = { ...(result.summary || {}) };
      if (!String(sm.report_number || '').trim() && item?.summary_json?.report_number) sm.report_number = item.summary_json.report_number;
      await saveUploadedReportHistory(item?.file_name || 'recomputed.xlsx', sm, result.analytics);
    }
    return true;
  };

  const [rawRecomputeBusy, setRawRecomputeBusy] = useState<string | null>(null);
  const recomputeAllRawHistory = async () => {
    const items = (uploadedRawReports || []).filter((h: any) => {
      const b = String(h?.summary_json?.source_file_path || '').trim();
      const inDb = Array.isArray(h?.rows_json) && h.rows_json.length > 0;
      return !!b || inDb;
    });
    if (!items.length) { showToast('Нет отчётов с доступным исходником для пересчёта', 'error'); return; }
    const ok = await confirmDialog({ title: 'Пересчитать все отчёты?', message: `Будут пересчитаны из исходников и обновлены в «Отчётах»: ${items.length} шт.\nЭто применит все новые показатели без ручной перезагрузки файлов.`, tone: 'primary', confirmText: 'Пересчитать', cancelText: 'Отмена' });
    if (!ok) return;
    let done = 0, fail = 0;
    for (let i = 0; i < items.length; i += 1) {
      setRawRecomputeBusy(`Пересчёт ${i + 1} из ${items.length}…`);
      try { (await recomputeRawHistoryItem(items[i], { silent: true })) ? (done += 1) : (fail += 1); }
      catch (e) { console.error('recomputeAll item error', e); fail += 1; }
      await new Promise((r) => setTimeout(r, 60));
    }
    setRawRecomputeBusy(null);
    showToast(`Пересчитано: ${done}${fail ? `, пропущено: ${fail}` : ''}`, fail ? 'warning' : 'success');
    await loadUploadedReportHistory(uploadedSelectedSupplierId);
  };

  // ===== WB API: еженедельные отчёты о реализации (тот же файл, что грузили вручную) =====
  // Маппинг строки API (reportDetailByPeriod) → колонки WB-отчёта (русские заголовки,
  // которые читает processUploadedWbReport). Парсер сопоставляет по подстрокам, поэтому
  // достаточно канонических названий колонок отчёта о реализации.
  const mapWbApiRowToReportRow = (r: any) => ({
    'Номер отчета': r?.realizationreport_id ?? '',
    'Номер поставки': r?.gi_id ?? '',
    'Предмет': r?.subject_name ?? '',
    'Код номенклатуры': r?.nm_id ?? '',
    'Бренд': r?.brand_name ?? '',
    'Артикул поставщика': r?.sa_name ?? '',
    'Размер': r?.ts_name ?? '',
    'Баркод': r?.barcode ?? '',
    'Тип документа': r?.doc_type_name ?? '',
    'Обоснование для оплаты': r?.supplier_oper_name ?? '',
    'Дата заказа покупателем': r?.order_dt ?? '',
    'Дата продажи': r?.sale_dt ?? '',
    'Кол-во': r?.quantity ?? 0,
    'Цена розничная': r?.retail_price ?? 0,
    'Вайлдберриз реализовал Товар (Пр)': r?.retail_amount ?? 0,
    'Согласованный продуктовый дисконт, %': r?.product_discount_for_report ?? 0,
    'Промокод, %': r?.supplier_promo ?? 0,
    'Цена розничная с учетом согласованной скидки': r?.retail_price_withdisc_rub ?? 0,
    'Скидка постоянного покупателя (СПП), %': r?.ppvz_spp_prc ?? 0,
    'Размер кВВ без НДС, % базовый': r?.ppvz_kvw_prc_base ?? 0,
    'Итоговый кВВ без НДС, %': r?.ppvz_kvw_prc ?? 0,
    'Вознаграждение с продаж до вычета комиссий (ВВ), без НДС': r?.ppvz_sales_commission ?? 0,
    'К перечислению Продавцу за реализованный Товар': r?.ppvz_for_pay ?? 0,
    'Возмещение за выдачу и хранение товара на ПВЗ': r?.ppvz_reward ?? 0,
    'Количество доставок': r?.delivery_amount ?? 0,
    'Количество возврата': r?.return_amount ?? 0,
    'Услуги по доставке товара покупателю': r?.delivery_rub ?? 0,
    'Общая сумма штрафов': r?.penalty ?? 0,
    'Доплаты': r?.additional_payment ?? 0,
    'Хранение': r?.storage_fee ?? 0,
    'Удержания': r?.deduction ?? 0,
    'Платная приемка': r?.acceptance ?? 0,
    'Возмещение издержек по эквайрингу/Комиссии за организацию платежей': r?.acquiring_fee ?? 0,
    'Размер комиссии за эквайринг/Комиссии за организацию платежей, %': r?.acquiring_percent ?? 0,
    'Наименование банка-эквайера': r?.acquiring_bank ?? '',
    'Виды логистики, штрафов и корректировок ВВ': r?.bonus_type_name ?? '',
    'Стикер МП': r?.sticker_id ?? '',
    // В API два РАЗНЫХ поля: ppvz_office_name = адрес доставки покупателю (→ «Города»),
    // office_name = склад отгрузки (→ «Склады»). Раньше путались и дублировались.
    'Наименование офиса доставки': r?.ppvz_office_name ?? '',
    'Склад': r?.office_name ?? '',
    'Страна': r?.site_country ?? '',
    'Тип коробов': r?.gi_box_type_name ?? '',
    'Номер таможенной декларации': r?.declaration_number ?? '',
    'Код маркировки': r?.kiz ?? '',
    'ШК': r?.shk_id ?? '',
    'Srid': r?.srid ?? '',
  });

  const invokeWbReports = async (payload: any): Promise<any> => {
    const { data, error } = await supabase.functions.invoke('wb-reports', { body: { supplier_id: uploadedSelectedSupplierId, ...payload } });
    if (error) throw new Error(error?.message || 'Ошибка вызова WB API');
    if (data && !Array.isArray(data) && data.error) throw new Error(String(data.error));
    return data;
  };

  const loadWbApiReports = async (supplierId: string) => {
    if (!supplierId) { setWbApiReports([]); return; }
    const { data, error } = await supabase.from('wb_api_reports').select('*').eq('supplier_id', supplierId).order('date_from', { ascending: false });
    if (error) { console.error('loadWbApiReports', error); return; }
    setWbApiReports(Array.isArray(data) ? data : []);
  };

  // Завершённые недели WB (пн–вс), пересекающиеся с указанным месяцем.
  const wbWeeksOfMonth = (year: number, month: number) => {
    const out: Array<{ from: string; to: string; label: string }> = [];
    const ymd = (d: Date) => d.toISOString().slice(0, 10);
    const today = new Date(); today.setHours(0, 0, 0, 0);
    const last = new Date(year, month + 1, 0);                 // последний день месяца
    const d = new Date(year, month, 1);
    const dow = (d.getDay() + 6) % 7; d.setDate(d.getDate() - dow);  // понедельник недели с 1-м числом
    while (d <= last) {
      const start = new Date(d);
      const end = new Date(d); end.setDate(d.getDate() + 6);
      if (end < today) out.push({ from: ymd(start), to: ymd(end), label: `${ymd(start)}…${ymd(end)}` }); // только завершённые
      d.setDate(d.getDate() + 7);
    }
    return out;
  };

  // Группировка строк WB → агрегаты по отчётам + upsert в историю (дата загрузки = сейчас).
  const upsertWbApiReportsFromRows = async (rows: any[]) => {
    const byId = new Map<string, any>();
    for (const r of (rows || [])) {
      const id = String(r?.realizationreport_id || ''); if (!id) continue;
      let g = byId.get(id);
      if (!g) { g = { supplier_id: uploadedSelectedSupplierId, realizationreport_id: id, date_from: r?.date_from || null, date_to: r?.date_to || null, create_dt: r?.create_dt || null, rows_count: 0, retail_amount_sum: 0, ppvz_for_pay_sum: 0 }; byId.set(id, g); }
      g.rows_count += 1; g.retail_amount_sum += Number(r?.retail_amount || 0); g.ppvz_for_pay_sum += Number(r?.ppvz_for_pay || 0);
    }
    const list = Array.from(byId.values());
    if (!list.length) return 0;
    const { error } = await supabase.from('wb_api_reports').upsert(list.map((x) => ({ ...x, updated_at: new Date().toISOString() })), { onConflict: 'supplier_id,realizationreport_id' });
    if (error) throw error;
    return list.length;
  };

  // Сканируем несколько недель подряд (каждая — отдельный безопасный запрос) и сохраняем найденные.
  const scanWbApiWeeks = async (weeks: Array<{ from: string; to: string; label: string }>) => {
    if (!uploadedSelectedSupplierId) { showToast('Сначала выберите поставщика', 'error'); return; }
    let found = 0;
    try {
      for (let i = 0; i < weeks.length; i += 1) {
        setWbApiBusy(`Проверка недели ${i + 1}/${weeks.length} (${weeks[i].from})…`);
        try {
          const rows = await invokeWbReports({ dateFrom: weeks[i].from, dateTo: weeks[i].to });
          if (Array.isArray(rows)) found += await upsertWbApiReportsFromRows(rows);
        } catch (e) { console.error('scanWbApiWeeks week error', e); }
      }
      await loadWbApiReports(uploadedSelectedSupplierId);
      showToast(found > 0 ? `Загружено/обновлено отчётов: ${found}` : 'Новых отчётов не найдено', found > 0 ? 'success' : 'info');
    } catch (e: any) { console.error('scanWbApiWeeks', e); showToast(`Ошибка: ${e?.message || 'не удалось получить отчёты'}`, 'error'); }
    finally { setWbApiBusy(''); }
  };

  const fetchWbApiReportRows = async (report: any) => {
    const rows = await invokeWbReports({ dateFrom: report?.date_from, dateTo: report?.date_to });
    if (!Array.isArray(rows)) throw new Error('Неверный ответ WB');
    const rid = String(report?.realizationreport_id || '');
    return rows.filter((r: any) => String(r?.realizationreport_id || '') === rid);
  };

  const downloadWbApiReport = async (report: any) => {
    setWbApiBusy(`Скачиваю отчёт №${report?.realizationreport_id}…`);
    try {
      const rows = await fetchWbApiReportRows(report);
      if (!rows.length) { showToast('В отчёте нет строк', 'error'); return; }
      const mapped = rows.map(mapWbApiRowToReportRow);
      const ps = report?.date_from ? new Date(report.date_from).toLocaleDateString('ru-RU').replace(/\./g, '-') : '';
      const pe = report?.date_to ? new Date(report.date_to).toLocaleDateString('ru-RU').replace(/\./g, '-') : '';
      await downloadWorkbook(`Отчет_WB_${report?.realizationreport_id}_${ps}_${pe}.xlsx`, [{ name: 'Отчёт о реализации', rows: mapped }]);
      showToast('Отчёт скачан', 'success');
    } catch (e: any) { console.error('downloadWbApiReport', e); showToast(`Ошибка: ${e?.message || 'не удалось скачать'}`, 'error'); }
    finally { setWbApiBusy(''); }
  };

  const importWbApiReport = async (report: any) => {
    setWbApiBusy(`Загружаю в систему №${report?.realizationreport_id}…`);
    try {
      const rows = await fetchWbApiReportRows(report);
      if (!rows.length) { showToast('В отчёте нет строк', 'error'); return; }
      const mapped = rows.map(mapWbApiRowToReportRow);
      const turbo = mapped.length >= TURBO_MODE_ROWS;
      const result = processUploadedWbReport(mapped, { turbo });
      if (result?.summary) {
        const sm: any = { ...(result.summary || {}) };
        if (!String(sm.report_number || '').trim()) sm.report_number = String(report?.realizationreport_id || '');
        await saveUploadedReportHistory(`Отчет WB ${report?.realizationreport_id}`, sm, result.analytics);
      }
      showToast('Отчёт загружен в систему и сохранён в «Отчётах»', 'success');
      setWbApiPickerOpen(false);
    } catch (e: any) { console.error('importWbApiReport', e); showToast(`Ошибка: ${e?.message || 'не удалось загрузить'}`, 'error'); }
    finally { setWbApiBusy(''); }
  };


  const downloadUploadedRawSourceFile = async (item: any) => {
    const b64 = String(item?.summary_json?.source_file_base64 || '').trim();
    const srcName = String(item?.summary_json?.source_file_name || item?.file_name || 'source_report.xlsx');
    const sourceBucket = String(item?.summary_json?.source_file_bucket || '').trim();
    const sourcePath = String(item?.summary_json?.source_file_path || '').trim();

    try {
      if (sourceBucket && sourcePath) {
        const { data, error } = await supabase.storage.from(sourceBucket).download(sourcePath);
        if (!error && data) {
          const url = URL.createObjectURL(data);
          const a = document.createElement('a');
          a.href = url;
          a.download = srcName.endsWith('.xlsx') || srcName.endsWith('.xls') ? srcName : `${srcName}.xlsx`;
          document.body.appendChild(a);
          a.click();
          a.remove();
          URL.revokeObjectURL(url);
          return;
        }
      }

      if (b64) {
        const bytes = Uint8Array.from(atob(b64), c => c.charCodeAt(0));
        const blob = new Blob([bytes], { type: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = srcName.endsWith('.xlsx') || srcName.endsWith('.xls') ? srcName : `${srcName}.xlsx`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        URL.revokeObjectURL(url);
        return;
      }

      const rows = Array.isArray(item?.rows_json) ? item.rows_json : [];
      if (!rows.length) {
        showToast('Для этой записи нет исходных строк отчёта', 'error');
        return;
      }

      await downloadJsonRowsAsExcel(rows, srcName, 'WB Report Raw');
      showToast('Файл восстановлен из данных БД и скачан', 'success');
    } catch (e) {
      console.error('downloadUploadedRawSourceFile error', e);
      showToast('Не удалось скачать исходный файл', 'error');
    }
  };

  const deleteUploadedRawHistoryItem = async (id: string, fileName?: string) => {
    if (!id) return;
    const label = String(fileName || 'этот WB отчёт');
    const ok = await confirmDialog({ title: 'Удалить отчёт?', message: `Будет удалён из истории WB:\n${label}\n\nДействие необратимо.`, tone: 'danger', confirmText: 'Удалить', cancelText: 'Отмена' });
    if (!ok) return;
    try {
      const { error } = await supabase.from('analytics_upload_reports_raw').delete().eq('id', id);
      if (error) throw error;
      await loadUploadedRawReportHistory(uploadedSelectedSupplierId);
      logAction('Аналитика: удаление отчёта', `Удалён WB-отчёт из истории: ${label}`, currentEmployee?.id);
      showToast('WB отчёт удалён из отдельной истории', 'success');
    } catch (e) {
      console.error('deleteUploadedRawHistoryItem error', e);
      showToast('Не удалось удалить WB отчёт', 'error');
    }
  };

  // Загрузка полной сводки выбранного периода для сравнения.
  const loadCompareSummary = async (id: string) => {
    setCompareReportId(id);
    if (!id) { setCompareSummary(null); return; }
    try {
      const { data, error } = await supabase.from('analytics_upload_history').select('summary_json').eq('id', id).single();
      if (error) throw error;
      setCompareSummary(data?.summary_json || null);
    } catch (e) { console.error('loadCompareSummary', e); setCompareSummary(null); showToast('Не удалось загрузить период для сравнения', 'error'); }
  };

  const loadUploadedReportHistory = async (supplierId: string) => {
    if (!supplierId) return;
    try {
      setUploadedHistoryLoading(true);
      // Лёгкий список: вытаскиваем только нужные поля из summary_json (без geo_snapshot/аналитики),
      // полные данные подгружаются при открытии конкретного отчёта.
      let histQuery = supabase
        .from('analytics_upload_history')
        .select('id, supplier_id, supplier_name, file_name, created_at, rn:summary_json->>report_number, ps:summary_json->>period_start, pe:summary_json->>period_end, tp:summary_json->>to_pay_total, pn:summary_json->>payout_net, pf:summary_json->>profit_total, sn:summary_json->>sales_net, ls:summary_json->>logistics_sum, fn:summary_json->>fine_sum, st:summary_json->>storage_sum, wh:summary_json->>withhold_sum, cv:summary_json->>wb_commission_vat, ts:summary_json->>tax_sum, pfv:summary_json->>profit_total_vat, cs:summary_json->>cost_sum, aq:summary_json->>acquiring_sum');
      histQuery = supplierId === ANY_SUPPLIER_ID ? histQuery.is('supplier_id', null) : histQuery.eq('supplier_id', supplierId);
      const { data, error } = await histQuery
        .order('created_at', { ascending: false })
        .limit(200);
      if (error) throw error;
      const numOrNull = (v: any) => (v == null || v === '') ? null : Number(v);
      const light = (Array.isArray(data) ? data : []).map((row: any) => ({
        id: row.id,
        supplier_id: row.supplier_id,
        supplier_name: row.supplier_name,
        file_name: row.file_name,
        created_at: row.created_at,
        summary_json: { report_number: row.rn || null, period_start: row.ps || null, period_end: row.pe || null, to_pay_total: numOrNull(row.tp), payout_net: numOrNull(row.pn), profit_total: numOrNull(row.pf), sales_net: numOrNull(row.sn), logistics_sum: numOrNull(row.ls), fine_sum: numOrNull(row.fn), storage_sum: numOrNull(row.st), withhold_sum: numOrNull(row.wh), wb_commission_vat: numOrNull(row.cv), tax_sum: numOrNull(row.ts), profit_total_vat: numOrNull(row.pfv), cost_sum: numOrNull(row.cs), acquiring_sum: numOrNull(row.aq) },
      }));
      const sorted = light.sort((a: any, b: any) => {
        const da = new Date(a?.summary_json?.period_start || a?.created_at || 0).getTime();
        const db = new Date(b?.summary_json?.period_start || b?.created_at || 0).getTime();
        return da - db;
      });
      setUploadedHistory(sorted);
    } catch (e) {
      console.error('loadUploadedReportHistory error', e);
      setUploadedHistory([]);
    } finally {
      setUploadedHistoryLoading(false);
    }
  };

  // Чистая прибыль отчёта в режиме ОСНО с НДС 22% (та же формула, что в hero открытого отчёта).
  // costSumOverride — актуальная себестоимость (Σ текущая_цена × продано); если не задан,
  // восстанавливаем зашитую при сохранении.
  const reportProfitVat = (s: any, costSumOverride?: number | null, includeAcqVat?: boolean): number => {
    const num = (v: any) => Number(v || 0);
    const sales = num(s?.sales_net), payout = num(s?.payout_net), toPay = num(s?.to_pay_total);
    const logistics = num(s?.logistics_sum), fine = num(s?.fine_sum), storage = num(s?.storage_sum), withhold = num(s?.withhold_sum);
    const taxSum = num(s?.tax_sum), profitBase = num(s?.profit_total), acquiring = num(s?.acquiring_sum);
    // Себестоимость: актуальная (override) либо восстановленная (К перечислению − налог − базовая прибыль).
    const costSum = (costSumOverride != null) ? Math.max(0, costSumOverride) : Math.max(0, toPay - taxSum - profitBase);
    const VAT = 0.22, PT = 0.25, ex = (a: number) => (a * VAT) / (1 + VAT);
    const commissionWB = sales - payout;
    const commVatExact = num(s?.wb_commission_vat);
    const commissionVat = Math.abs(commVatExact) > 0.005 ? commVatExact : ex(commissionWB);
    const vatOut = ex(sales);
    const vatIn = ex(costSum) + commissionVat + ex(logistics) + ex(withhold) + ex(storage) + (includeAcqVat ? ex(acquiring) : 0);
    const vatToPay = vatOut - vatIn;
    const wbOtherFees = logistics + fine;
    const baseCosts = costSum + withhold + storage;
    const profitBeforeTax = payout - wbOtherFees - baseCosts - vatToPay;
    const profitTax = Math.max(0, profitBeforeTax) * PT;
    return payout - wbOtherFees - (baseCosts + vatToPay + profitTax);
  };
  // Живая себестоимость по каждому отчёту (Σ текущая_цена × продано), подгружается для точной прибыли.
  const [uploadedHistoryLiveCost, setUploadedHistoryLiveCost] = useState<Record<string, number>>({});
  // Прибыль для отображения: у «Любой поставщик» — с НДС 22% (ОСНО) по актуальной себестоимости, иначе базовая.
  const reportNetProfit = (h: any): number | null => {
    const s = h?.summary_json || {};
    const isAny = h?.supplier_id == null;
    if (isAny) {
      // Если включён НДС с эквайринга — пересчитываем на лету от сохранённой себестоимости (cost_sum).
      if (uploadedAcquiringVat) {
        const cs = s?.cost_sum != null ? Number(s.cost_sum) : (uploadedHistoryLiveCost[String(h?.id || '')] ?? null);
        if (s?.payout_net == null && s?.to_pay_total == null) return s?.profit_total ?? null;
        return reportProfitVat(s, cs, true);
      }
      // 1) сохранённая при загрузке VAT-прибыль (быстро); 2) построчная подгрузка; 3) восстановление.
      if (s?.profit_total_vat != null) return Number(s.profit_total_vat);
      if (s?.payout_net == null && s?.to_pay_total == null) return s?.profit_total ?? null;
      const live = uploadedHistoryLiveCost[String(h?.id || '')];
      return reportProfitVat(s, live != null ? live : null);
    }
    return s?.profit_total ?? null;
  };
  // Подгружает построчные данные отчётов и считает актуальную себестоимость каждого (по текущим ценам).
  const loadUploadedHistoryLiveCosts = async () => {
    // Грузим построчно только те отчёты, где нет сохранённой VAT-прибыли (старые записи).
    const ids = (uploadedHistory || [])
      .filter((h: any) => h?.supplier_id == null && h?.summary_json?.profit_total_vat == null)
      .map((h: any) => String(h?.id || '')).filter(Boolean);
    if (!ids.length) return;
    try {
      const details = await fetchUploadedHistoryDetailsByIds(ids);
      const map: Record<string, number> = {};
      (details || []).forEach((d: any) => {
        const arr = Array.isArray(d?.analytics_json) ? d.analytics_json : [];
        let costSum = 0;
        arr.forEach((x: any) => {
          const code = String(x?.code || '').trim();
          const sold = Number(x?.sold_qty || 0);
          const cost = Number(uploadedPersistedCostByCode[code] || 0);
          costSum += cost * sold;
        });
        map[String(d?.id || '')] = costSum;
      });
      setUploadedHistoryLiveCost(map);
    } catch (e) { console.error('loadUploadedHistoryLiveCosts', e); }
  };
  useEffect(() => {
    if (uploadedHistoryPickerOpen && (uploadedHistory || []).length) loadUploadedHistoryLiveCosts();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [uploadedHistoryPickerOpen, uploadedHistory, uploadedPersistedCostByCode]);


  // Пересчитывает и сохраняет VAT-прибыль всех загруженных отчётов по ТЕКУЩЕЙ себестоимости.
  const [recomputeProfitsBusy, setRecomputeProfitsBusy] = useState<string>('');
  const recomputeUploadedProfits = async () => {
    const items = (uploadedHistory || []).filter((h: any) => h?.supplier_id == null);
    const ids = items.map((h: any) => String(h?.id || '')).filter(Boolean);
    if (!ids.length) { showToast('Нет отчётов «Любой поставщик» в списке', 'info'); return; }
    setRecomputeProfitsBusy('Пересчёт…');
    try {
      const chunk = 20;
      let updated = 0;
      for (let i = 0; i < ids.length; i += chunk) {
        setRecomputeProfitsBusy(`Пересчёт ${Math.min(i + chunk, ids.length)}/${ids.length}…`);
        const details = await fetchUploadedHistoryDetailsByIds(ids.slice(i, i + chunk));
        for (const d of details || []) {
          const s = d?.summary_json || {};
          const arr = Array.isArray(d?.analytics_json) ? d.analytics_json : [];
          let costSum = 0;
          arr.forEach((x: any) => { const code = String(x?.code || '').trim(); costSum += Number(uploadedPersistedCostByCode[code] || 0) * Number(x?.sold_qty || 0); });
          const pfv = reportProfitVat(s, costSum);
          const merged = { ...s, cost_sum: costSum, profit_total_vat: pfv };
          const { error } = await supabase.from('analytics_upload_history').update({ summary_json: merged }).eq('id', d.id);
          if (!error) updated += 1;
        }
      }
      showToast(`Прибыль пересчитана: ${updated} отчётов`, 'success');
      setUploadedHistoryLiveCost({});
      await loadUploadedReportHistory(uploadedSelectedSupplierId);
    } catch (e) { console.error('recomputeUploadedProfits', e); showToast('Ошибка пересчёта прибыли', 'error'); }
    finally { setRecomputeProfitsBusy(''); }
  };

  const recalcAnalyticsToPayWithoutAcquiring = (arr: any[]) => {
    return (Array.isArray(arr) ? arr : []).map((x: any) => {
      const payoutFallback = Number(x?.payout_sales_sum || 0) - Number(x?.payout_returns_sum || 0);
      const payoutNet = Number(x?.payout_net ?? payoutFallback);
      const logistics = Number(x?.logistics_sum || 0);
      const storage = Number(x?.storage_sum || 0);
      const fine = Number(x?.fine_sum || 0);
      const withhold = Number(x?.withhold_sum || 0);
      const toPay = payoutNet - logistics - storage - fine - withhold;
      return { ...x, payout_net: payoutNet, to_pay_total: toPay };
    });
  };

  const fetchUploadedHistoryDetailsByIds = async (ids: string[]) => {
    const cleanIds = Array.from(new Set((ids || []).map((x) => String(x || '').trim()).filter(Boolean)));
    if (!cleanIds.length) return [] as any[];
    const { data, error } = await supabase
      .from('analytics_upload_history')
      .select('id, summary_json, analytics_json')
      .in('id', cleanIds as any)
      .limit(Math.max(1, cleanIds.length));
    if (error) throw error;
    return Array.isArray(data) ? data : [];
  };

  // Пересчёт отчёта из исходного Excel в Storage (даёт свежие гео-агрегации,
  // эквайринг и т.п. — то, чего нет в сохранённой сводке старых отчётов).
  const reparseHistoryFromFile = async (sumObj: any): Promise<boolean> => {
    const bucket = sumObj?.source_file_bucket;
    const path = sumObj?.source_file_path;
    if (!bucket || !path) return false;
    try {
      showToast('Пересчитываю отчёт из файла…', 'info');
      const { data, error } = await supabase.storage.from(bucket).download(path);
      if (error || !data) return false;
      const buf = await data.arrayBuffer();
      const rows = await readFirstSheetAsJson<Record<string, any>>(buf, { defval: '' });
      if (!Array.isArray(rows) || rows.length === 0) return false;
      processUploadedWbReport(rows);
      setUploadedViewTab('summary');
      showToast('Отчёт пересчитан из файла', 'success');
      return true;
    } catch (e) {
      console.warn('reparseHistoryFromFile failed', e);
      return false;
    }
  };

  // Пересчёт из СЫРЫХ строк отчёта (analytics_upload_reports_raw) — там полные данные,
  // поэтому новый парсер строит размеры/штуки/виды логистики заново.
  const reparseHistoryFromRaw = async (sumObj: any, supplierId?: string): Promise<boolean> => {
    try {
      const supId = String(supplierId || uploadedSelectedSupplierId || '').trim();
      if (!supId) return false;
      const rn = String((sumObj as any)?.report_number || '').trim();
      const ps = (sumObj as any)?.period_start ? new Date((sumObj as any).period_start) : null;
      const pe = (sumObj as any)?.period_end ? new Date((sumObj as any).period_end) : null;
      const iso = (d: Date | null) => d && !Number.isNaN(d.getTime()) ? `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}` : '';
      // Шаг 1: только метаданные (без тяжёлого rows_json), чтобы найти нужный отчёт.
      const { data: metaRows, error: metaErr } = await supabase
        .from('analytics_upload_reports_raw')
        .select('id, report_number, period_start, period_end')
        .eq('supplier_id', supId)
        .order('created_at', { ascending: false })
        .limit(50);
      if (metaErr || !Array.isArray(metaRows) || metaRows.length === 0) return false;
      const psIso = iso(ps), peIso = iso(pe);
      const match = metaRows.find((r: any) => {
        if (rn && String(r?.report_number || '').trim() === rn) return true;
        const rps = r?.period_start ? String(r.period_start).slice(0, 10) : '';
        const rpe = r?.period_end ? String(r.period_end).slice(0, 10) : '';
        return !!psIso && !!peIso && rps === psIso && rpe === peIso;
      }) || null;
      if (!match?.id) return false;
      // Шаг 2: тянем rows_json ТОЛЬКО для найденного отчёта.
      const { data: oneRow, error: rowErr } = await supabase
        .from('analytics_upload_reports_raw')
        .select('rows_json')
        .eq('id', match.id)
        .maybeSingle();
      const rows = oneRow && Array.isArray(oneRow.rows_json) ? oneRow.rows_json : null;
      if (rowErr || !rows || rows.length === 0) return false;
      showToast('Пересчитываю отчёт из сохранённых строк…', 'info');
      processUploadedWbReport(rows);
      setUploadedViewTab('summary');
      showToast('Отчёт пересчитан (полные размеры и виды логистики)', 'success');
      return true;
    } catch (e) {
      console.warn('reparseHistoryFromRaw failed', e);
      return false;
    }
  };

  const openUploadedHistoryItem = async (item: any) => {
    try {
      let analytics = Array.isArray(item?.analytics_json) ? item.analytics_json : [];
      let summary = item?.summary_json || null;
      if ((!analytics.length || !summary) && item?.id) {
        const rows = await fetchUploadedHistoryDetailsByIds([String(item.id)]);
        const found = (rows || [])[0] || null;
        if (found) {
          analytics = Array.isArray(found?.analytics_json) ? found.analytics_json : analytics;
          summary = found?.summary_json || summary;
        }
      }
      // Пробуем пересчитать из исходного файла (полная инфографика + эквайринг).
      if (await reparseHistoryFromFile(summary)) return;
      // Иначе — из сохранённых сырых строк отчёта (полные размеры/штуки/виды логистики).
      if (await reparseHistoryFromRaw(summary, item?.supplier_id)) return;
      // Файла нет — восстанавливаем гео-снимок из сохранённой сводки (если он есть).
      const geoSnap = (summary as any)?.geo_snapshot || null;
      setUploadedReportGeo(geoSnap && (geoSnap.byWarehouse || geoSnap.byOffice || geoSnap.dailyTotals) ? geoSnap : null);
      if (!Array.isArray(analytics) || analytics.length === 0) {
        showToast('В этом отчёте нет сохранённых данных аналитики', 'error');
        return;
      }

      const recalcedAnalytics = recalcAnalyticsToPayWithoutAcquiring(analytics);

      const dateCandidates = recalcedAnalytics
        .map((x: any) => new Date(x?.operation_date || x?.date || x?.created_at || ''))
        .filter((d: Date) => !Number.isNaN(d.getTime()))
        .sort((a: Date, b: Date) => a.getTime() - b.getTime());

      const summaryTaxRate = getUploadedTaxRate(summary);
      const normalizedSummary = summary ? {
        ...summary,
        return_qty: recalcedAnalytics.reduce((acc: number, x: any) => acc + Number(x?.return_qty || 0), 0),
        acquiring_sum: recalcedAnalytics.reduce((acc: number, x: any) => acc + Number(x?.acquiring_sum || 0), 0),
        acquiring_percent: (recalcedAnalytics.reduce((acc: number, x: any) => acc + Number(x?.sales_net || 0), 0) > 0)
          ? (recalcedAnalytics.reduce((acc: number, x: any) => acc + Number(x?.acquiring_sum || 0), 0) / recalcedAnalytics.reduce((acc: number, x: any) => acc + Number(x?.sales_net || 0), 0)) * 100
          : 0,
        profit_total: recalcedAnalytics.reduce((acc: number, x: any) => {
          const sold = Number(x?.sold_qty || 0);
          const cost = Number(uploadedPersistedCostByCode[String(x?.code || '').trim()] || 0);
          const avg = sold > 0 ? (Number(x?.to_pay_total || 0) / sold) - cost : 0;
          const baseProfit = avg * sold;
          const taxValue = Number(x?.sales_net || 0) * summaryTaxRate;
          return acc + (baseProfit - taxValue);
        }, 0),
        period_start: summary?.period_start || (dateCandidates[0] ? dateCandidates[0].toISOString() : null),
        period_end: summary?.period_end || (dateCandidates.length ? dateCandidates[dateCandidates.length - 1].toISOString() : null),
      } : summary;

      setUploadedReportAnalytics(recalcedAnalytics);
      setUploadedReportSummary(normalizedSummary);
      setUploadedDailySeries({});
      setUploadedChartKey('');
      setUploadedViewTab('summary');

      if (item?.id) {
        try {
          await supabase
            .from('analytics_upload_history')
            .update({ analytics_json: recalcedAnalytics, summary_json: normalizedSummary })
            .eq('id', item.id);
        } catch {}
      }

      showToast('Отчёт открыт из истории', 'success');
    } catch (e) {
      console.error('openUploadedHistoryItem error', e);
      showToast('Не удалось открыть отчёт из истории', 'error');
    }
  };


  const openUploadedHistoryMonth = async (items: any[]) => {
    const rows = Array.isArray(items) ? items : [];
    if (!rows.length) return;

    const grouped = new Map<string, any>();
    let periodStart: Date | null = null;
    let periodEnd: Date | null = null;

    const byId = new Map<string, any>();
    try {
      const ids = rows.map((r: any) => String(r?.id || '')).filter(Boolean);
      const details = await fetchUploadedHistoryDetailsByIds(ids);
      (details || []).forEach((d: any) => byId.set(String(d?.id || ''), d));
    } catch (e) {
      console.error('openUploadedHistoryMonth details fetch error', e);
    }

    rows.forEach((it: any) => {
      const detail = byId.get(String(it?.id || '')) || it;
      const arr = Array.isArray(detail?.analytics_json) ? detail.analytics_json : [];
      const summaryForDates = detail?.summary_json || it?.summary_json || {};
      const s0 = summaryForDates?.period_start ? new Date(summaryForDates.period_start) : null;
      const e0 = summaryForDates?.period_end ? new Date(summaryForDates.period_end) : null;
      if (s0 && !Number.isNaN(s0.getTime())) periodStart = !periodStart || s0 < periodStart ? s0 : periodStart;
      if (e0 && !Number.isNaN(e0.getTime())) periodEnd = !periodEnd || e0 > periodEnd ? e0 : periodEnd;

      const sourceYear = new Date(summaryForDates?.period_start || summaryForDates?.period_end || summaryForDates?.created_at || '').getFullYear();
      const sourceTaxRate = getTaxRateByYear(sourceYear);

      arr.forEach((r: any) => {
        const code = String(r?.code || '').trim();
        const name = String(r?.name || 'Без названия').trim();
        const key = `${code}|${name}`;
        const cur = grouped.get(key) || {
          code,
          name,
          vendor_code: '',
          sales_net: 0,
          returns_gross: 0,
          logistics_sum: 0,
          payout_sum: 0,
          payout_net: 0,
          fine_sum: 0,
          storage_sum: 0,
          withhold_sum: 0,
          to_pay_total: 0,
          sold_net_qty: 0,
          sold_qty: 0,
          return_qty: 0,
          acquiring_sum: 0,
          tax_sum: 0,
          wb_commission_vat: 0,
          wb_commission_net: 0,
          acquiring_percent_sum: 0,
          acquiring_percent_count: 0,
          size_stats: {},
        };

        // Артикул поставщика берём из любого отчёта, где он заполнен (в старых записях пусто).
        if (!cur.vendor_code) {
          const vcSrc = String(r?.vendor_code || '').trim();
          if (vcSrc) cur.vendor_code = vcSrc;
        }
        cur.sales_net += Number(r?.sales_net || 0);
        cur.returns_gross += Number(r?.returns_gross || 0);
        cur.logistics_sum += Number(r?.logistics_sum || 0);
        cur.payout_sum += Number(r?.payout_sum || 0);
        cur.payout_net += Number(r?.payout_net || 0);
        cur.fine_sum += Number(r?.fine_sum || 0);
        cur.storage_sum += Number(r?.storage_sum || 0);
        cur.withhold_sum += Number(r?.withhold_sum || 0);
        cur.to_pay_total += (Number(r?.payout_net || 0) - Number(r?.logistics_sum || 0) - Number(r?.storage_sum || 0) - Number(r?.fine_sum || 0) - Number(r?.withhold_sum || 0));
        cur.sold_net_qty += Number(r?.sold_net_qty || 0);
        cur.sold_qty += Number(r?.sold_qty || r?.sold_net_qty || 0);
        cur.return_qty += Number(r?.return_qty || 0);
        cur.acquiring_sum += Number(r?.acquiring_sum || 0);
        cur.wb_commission_vat += Number(r?.wb_commission_vat || 0);
        cur.wb_commission_net += Number(r?.wb_commission_net || 0);
        cur.tax_sum += Number(r?.tax_sum ?? (Number(r?.sales_net || 0) * sourceTaxRate));

        const ap = Number(r?.acquiring_percent || 0);
        if (ap > 0) {
          cur.acquiring_percent_sum += ap;
          cur.acquiring_percent_count += 1;
        }

        const sizeArr = Array.isArray(r?.size_breakdown_list) ? r.size_breakdown_list : [];
        sizeArr.forEach((sz: any) => {
          const sizeKey = String(sz?.size || 'Без размера');
          const prev = cur.size_stats[sizeKey] || {
            size: sizeKey,
            sales_net: 0,
            returns_gross: 0,
            logistics_sum: 0,
            payout_net: 0,
            fine_sum: 0,
            storage_sum: 0,
            withhold_sum: 0,
            to_pay_total: 0,
            sold_net_qty: 0,
            sold_qty: 0,
            return_qty: 0,
            acquiring_sum: 0,
            tax_sum: 0,
            acquiring_percent_sum: 0,
            acquiring_percent_count: 0,
          };
          prev.sales_net += Number(sz?.sales_net || 0);
          prev.returns_gross += Number(sz?.returns_gross || 0);
          prev.logistics_sum += Number(sz?.logistics_sum || 0);
          prev.payout_net += Number(sz?.payout_net || 0);
          prev.fine_sum += Number(sz?.fine_sum || 0);
          prev.storage_sum += Number(sz?.storage_sum || 0);
          prev.withhold_sum += Number(sz?.withhold_sum || 0);
          prev.to_pay_total += (Number(sz?.payout_net || 0) - Number(sz?.logistics_sum || 0) - Number(sz?.storage_sum || 0) - Number(sz?.fine_sum || 0) - Number(sz?.withhold_sum || 0));
          prev.sold_net_qty += Number(sz?.sold_net_qty || 0);
          prev.sold_qty += Number(sz?.sold_qty || sz?.sold_net_qty || 0);
          prev.return_qty += Number(sz?.return_qty || 0);
          prev.acquiring_sum += Number(sz?.acquiring_sum || 0);
          prev.tax_sum += Number(sz?.tax_sum || 0);
          const apSz = Number(sz?.acquiring_percent || 0);
          if (apSz > 0) {
            prev.acquiring_percent_sum += apSz;
            prev.acquiring_percent_count += 1;
          }
          cur.size_stats[sizeKey] = prev;
        });

        grouped.set(key, cur);
      });
    });

    const compareSizesAscLocal = (aSize: string, bSize: string) => {
      const prep = (v: string) => String(v || '').trim().toUpperCase();
      const a = prep(aSize);
      const b = prep(bSize);
      const rank = (v: string) => {
        if (!v || v === 'БЕЗ РАЗМЕРА' || v === 'БЕЗ Р-РА' || v === 'NONE' || v === 'NO SIZE') return 100000;

        const fixed: Record<string, number> = {
          XXS: 10,
          XS: 20,
          S: 30,
          M: 40,
          L: 50,
          XL: 60,
          XXL: 70,
          XXXL: 80,
          XXXXL: 90,
        };
        if (fixed[v] != null) return fixed[v];

        const xL = v.match(/^X+L$/i);
        if (xL) return 50 + String(v).replace(/[^X]/gi, '').length * 10;

        const numXL = v.match(/^(\d+)\s*XL$/i);
        if (numXL) return 60 + Number(numXL[1]) * 10;

        const pureNum = Number(v);
        if (!Number.isNaN(pureNum) && v !== '') return 500 + pureNum;

        return 90000;
      };
      const ra = rank(a);
      const rb = rank(b);
      if (ra !== rb) return ra - rb;
      return a.localeCompare(b, 'ru', { numeric: true });
    };

    const analytics = Array.from(grouped.values()).map((x: any) => {
      const sizeBreakdown = Object.values(x?.size_stats || {})
        .map((sz: any) => ({
          ...sz,
          acquiring_percent: Number(sz?.sales_net || 0) > 0 ? (Number(sz?.acquiring_sum || 0) / Number(sz?.sales_net || 0)) * 100 : 0,
        }))
        .sort((a: any, b: any) => compareSizesAscLocal(String(a?.size || ''), String(b?.size || '')));
      return {
        ...x,
        acquiring_percent: Number(x.sales_net || 0) > 0 ? (Number(x.acquiring_sum || 0) / Number(x.sales_net || 0)) * 100 : 0,
        size_breakdown: sizeBreakdown.map((z: any) => `${z.size}: ${Number(z.sold_net_qty || 0) - Number(z.return_qty || 0)}`).join(' • '),
        size_breakdown_list: sizeBreakdown,
      };
    }).sort((a: any, b: any) => Number(b.sales_net || 0) - Number(a.sales_net || 0));

    const localISO2 = (d: Date | null) => d ? `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}` : null;
    const summary = {
      report_number: null,
      period_start: localISO2(periodStart),
      period_end: localISO2(periodEnd),
      items: analytics.length,
      sales_net: analytics.reduce((acc: number, x: any) => acc + Number(x.sales_net || 0), 0),
      returns_gross: analytics.reduce((acc: number, x: any) => acc + Number(x.returns_gross || 0), 0),
      logistics_sum: analytics.reduce((acc: number, x: any) => acc + Number(x.logistics_sum || 0), 0),
      payout_sum: analytics.reduce((acc: number, x: any) => acc + Number(x.payout_sum || 0), 0),
      payout_net: analytics.reduce((acc: number, x: any) => acc + Number(x.payout_net || 0), 0),
      fine_sum: analytics.reduce((acc: number, x: any) => acc + Number(x.fine_sum || 0), 0),
      storage_sum: analytics.reduce((acc: number, x: any) => acc + Number(x.storage_sum || 0), 0),
      withhold_sum: analytics.reduce((acc: number, x: any) => acc + Number(x.withhold_sum || 0), 0),
      to_pay_total: analytics.reduce((acc: number, x: any) => acc + Number(x.to_pay_total || 0), 0),
      sold_qty: analytics.reduce((acc: number, x: any) => acc + Number(x.sold_qty || 0), 0),
      return_qty: analytics.reduce((acc: number, x: any) => acc + Number(x.return_qty || 0), 0),
      acquiring_sum: analytics.reduce((acc: number, x: any) => acc + Number(x.acquiring_sum || 0), 0),
      acquiring_percent: (analytics.reduce((acc: number, x: any) => acc + Number(x.sales_net || 0), 0) > 0)
        ? (analytics.reduce((acc: number, x: any) => acc + Number(x.acquiring_sum || 0), 0) / analytics.reduce((acc: number, x: any) => acc + Number(x.sales_net || 0), 0)) * 100
        : 0,
      tax_sum: analytics.reduce((acc: number, x: any) => acc + Number(x.tax_sum || 0), 0),
      wb_commission_vat: analytics.reduce((acc: number, x: any) => acc + Number(x.wb_commission_vat || 0), 0),
      wb_commission_net: analytics.reduce((acc: number, x: any) => acc + Number(x.wb_commission_net || 0), 0),
      profit_total: analytics.reduce((acc: number, x: any) => {
        const sold = Number(x.sold_qty || 0);
        const cost = Number(uploadedPersistedCostByCode[String(x.code || '').trim()] || 0);
        const avg = sold > 0 ? (Number(x.to_pay_total || 0) / sold) - cost : 0;
        const baseProfit = avg * sold;
        const taxValue = Number(x.tax_sum || 0);
        return acc + (baseProfit - taxValue);
      }, 0),
    };

    setUploadedReportAnalytics(analytics);
    setUploadedReportSummary(summary);
    setUploadedDailySeries({});
    setUploadedChartKey('');
    setUploadedViewTab('table');
    showToast('Открыт объединённый отчёт за месяц', 'success');
  };

  // Точный отчёт по КОНКРЕТНЫМ дням: перечитываем исходные строки отчётов из Storage
  // и фильтруем по «Дата продажи» в диапазоне, затем считаем тем же движком, что и при загрузке.
  // Кэш распарсенных строк исходников по номеру отчёта и кэш готовых дневных отчётов — чтобы
  // повторные открытия (другие дни той же недели / тот же день) были мгновенными.
  const dayRowsCacheRef = useRef<Map<string, any[]>>(new Map());
  const dayReportCacheRef = useRef<Map<string, { analytics: any[]; summary: any }>>(new Map());
  const buildDayRangeReport = async (items: any[], fromYmd: string, toYmd: string) => {
    if (!Array.isArray(items) || !items.length) return;
    const parseAny = (v: any): Date | null => {
      if (v == null || String(v).trim() === '') return null;
      if (v instanceof Date && !Number.isNaN(v.getTime())) return v;
      if (typeof v === 'number' && Number.isFinite(v)) { const dt = new Date(Date.UTC(1899, 11, 30).valueOf() + v * 86400000); return Number.isNaN(dt.getTime()) ? null : dt; }
      const str = String(v).trim();
      let m = str.match(/^(\d{1,2})[.\/-](\d{1,2})[.\/-](\d{4})/); if (m) return new Date(Number(m[3]), Number(m[2]) - 1, Number(m[1]));
      m = str.match(/^(\d{4})-(\d{1,2})-(\d{1,2})/); if (m) return new Date(Number(m[1]), Number(m[2]) - 1, Number(m[3]));
      const iso = new Date(str); return Number.isNaN(iso.getTime()) ? null : iso;
    };
    const toKey = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}-${String(d.getDate()).padStart(2, '0')}`;
    // Кэш готового дневного отчёта — тот же день/те же отчёты открываются мгновенно.
    const nums = Array.from(new Set(items.map((it: any) => String(it?.summary_json?.report_number || '').trim()).filter(Boolean)));
    const resultKey = `${nums.slice().sort().join(',')}|${fromYmd}|${toYmd}`;
    const cached = dayReportCacheRef.current.get(resultKey);
    if (cached) {
      setUploadedReportAnalytics(cached.analytics);
      setUploadedReportSummary(cached.summary);
      setUploadedDailySeries({});
      setUploadedChartKey('');
      setUploadedViewTab('table');
      showToast(`Отчёт за день ${fromYmd || '…'}${fromYmd !== toYmd ? ` — ${toYmd}` : ''} (из кэша)`, 'success');
      return;
    }
    try {
      showToast('Собираю точный отчёт по дням…', 'info');
      // Строки исходников кэшируем по номеру отчёта — качаем/парсим xlsx только раз.
      const rowsCache = dayRowsCacheRef.current;
      const missingNums = nums.filter((n) => !rowsCache.has(n));
      const rawByNum = new Map<string, any>();
      if (missingNums.length) {
        try {
          const { data: rr } = await supabase.from('analytics_upload_reports_raw').select('id, report_number, summary_json').in('report_number', missingNums).limit(missingNums.length * 2);
          (rr || []).forEach((r: any) => { const n = String(r?.report_number || '').trim(); if (n && !rawByNum.has(n)) rawByNum.set(n, r); });
        } catch (e) { console.error('day report: raw lookup', e); }
      }
      const allRows: any[] = [];
      let missed = 0;
      for (const it of items) {
        const n = String(it?.summary_json?.report_number || '').trim();
        let rows = rowsCache.get(n);
        if (!rows) {
          const src = rawByNum.get(n) || it;
          try { rows = await getRowsForRawItem(src); } catch { rows = []; }
          if (Array.isArray(rows) && rows.length) rowsCache.set(n, rows);
        }
        if (Array.isArray(rows) && rows.length) allRows.push(...rows); else missed += 1;
      }
      if (!allRows.length) { showToast('Не удалось получить строки отчётов (исходники недоступны)', 'error'); return; }
      const keys = Object.keys(allRows[0] || {});
      const saleKeys = keys.filter((k) => { const n = String(k || '').toLowerCase().replace(/\s+/g, ' ').trim(); return n === 'дата продажи' || n.includes('дата продажи'); });
      if (!saleKeys.length) { showToast('В исходниках нет столбца «Дата продажи» — по дням не собрать', 'error'); return; }
      const filtered = allRows.filter((r) => {
        for (const k of saleKeys) { const d = parseAny(r?.[k]); if (d) { const y = toKey(d); return (!fromYmd || y >= fromYmd) && (!toYmd || y <= toYmd); } }
        return false;
      });
      if (!filtered.length) { showToast('За выбранные дни строк продаж нет', 'info'); return; }
      const result = processUploadedWbReport(filtered, {});
      if (result?.summary) {
        const analyticsOut = Array.isArray(result?.analytics) ? result.analytics : [];
        const summaryOut = { ...result.summary, period_start: fromYmd || result.summary.period_start, period_end: toYmd || result.summary.period_end };
        dayReportCacheRef.current.set(resultKey, { analytics: analyticsOut, summary: summaryOut });
        setUploadedReportAnalytics(analyticsOut);
        setUploadedReportSummary(summaryOut);
        setUploadedDailySeries({});
        setUploadedChartKey('');
        setUploadedViewTab('table');
        showToast(`Отчёт по дням ${fromYmd || '…'} — ${toYmd || '…'}: товаров ${analyticsOut.length}${missed ? `, без исходника ${missed}` : ''}`, missed ? 'warning' : 'success');
      }
    } catch (e: any) { console.error('buildDayRangeReport', e); showToast('Ошибка сборки по дням: ' + (e?.message || 'неизвестно'), 'error'); }
  };


  const openUploadedHistorySelected = () => {
    const selected = (uploadedHistory || []).filter((h: any) => uploadedHistorySelectedIds[String(h.id)]);
    if (!selected.length) {
      showToast('Выберите хотя бы один отчёт', 'error');
      return;
    }
    openUploadedHistoryMonth(selected as any[]);
    setUploadedHistoryPickerOpen(false);
  };

  const deleteUploadedHistoryItem = async (id: string, fileName?: string) => {
    if (!id) return;
    const label = String(fileName || 'этот отчёт');
    const ok = await confirmDialog({ title: 'Удалить отчёт?', message: `Будет удалён из истории:\n${label}\n\nДействие необратимо.`, tone: 'danger', confirmText: 'Удалить', cancelText: 'Отмена' });
    if (!ok) return;
    try {
      const { error } = await supabase.from('analytics_upload_history').delete().eq('id', id);
      if (error) throw error;
      setUploadedHistory((prev) => (prev || []).filter((x: any) => String(x.id) !== String(id)));
      showToast('Отчёт удалён из истории', 'success');
    } catch (e) {
      console.error('deleteUploadedHistoryItem error', e);
      showToast('Не удалось удалить отчёт из истории', 'error');
    }
  };

  // ── Массовое удаление в историях отчётов ──
  const deleteUploadedHistoryMany = async (ids: string[]) => {
    const list = Array.from(new Set((ids || []).map(String).filter(Boolean)));
    if (!list.length) return;
    const ok = await confirmDialog({ title: 'Удалить выбранные?', message: `Будет удалено отчётов: ${list.length}.\nДействие необратимо.`, tone: 'danger', confirmText: 'Удалить', cancelText: 'Отмена' });
    if (!ok) return;
    try {
      const { error } = await supabase.from('analytics_upload_history').delete().in('id', list);
      if (error) throw error;
      setUploadedHistory((prev) => (prev || []).filter((x: any) => !list.includes(String(x.id))));
      setHistorySel({});
      setUploadedHistorySelectedIds({});
      showToast(`Удалено отчётов: ${list.length}`, 'success');
    } catch (e) {
      console.error('deleteUploadedHistoryMany error', e);
      showToast('Не удалось удалить выбранные отчёты', 'error');
    }
  };

  const deleteUploadedRawHistoryMany = async (ids: string[]) => {
    const list = Array.from(new Set((ids || []).map(String).filter(Boolean)));
    if (!list.length) return;
    const ok = await confirmDialog({ title: 'Удалить выбранные?', message: `Будет удалено WB-отчётов: ${list.length}.\nДействие необратимо.`, tone: 'danger', confirmText: 'Удалить', cancelText: 'Отмена' });
    if (!ok) return;
    try {
      const { error } = await supabase.from('analytics_upload_reports_raw').delete().in('id', list);
      if (error) throw error;
      setRawSel({});
      await loadUploadedRawReportHistory(uploadedSelectedSupplierId);
      showToast(`Удалено WB-отчётов: ${list.length}`, 'success');
    } catch (e) {
      console.error('deleteUploadedRawHistoryMany error', e);
      showToast('Не удалось удалить выбранные WB-отчёты', 'error');
    }
  };

  const saveUploadedReportHistory = async (fileName?: string, summaryArg?: any, analyticsArg?: any[]) => {
    const summaryToSave = summaryArg || uploadedReportSummary;
    const analyticsToSave = analyticsArg || uploadedReportAnalytics;
    if (!uploadedSelectedSupplierId || !summaryToSave || !analyticsToSave?.length) return;
    const isAnySup = uploadedSelectedSupplierId === ANY_SUPPLIER_ID;
    const supplierDbId = isAnySup ? null : uploadedSelectedSupplierId;
    const supplier = (suppliers || []).find((s: any) => String(s?.id) === String(uploadedSelectedSupplierId));
    try {
      const reportNumber = String((summaryToSave as any)?.report_number || '').trim();
      let duplicateId: string | null = null;
      if (uploadedCheckDuplicates) {
        let checkQuery = supabase
          .from('analytics_upload_history')
          .select('id, summary_json, created_at');
        checkQuery = isAnySup ? checkQuery.is('supplier_id', null) : checkQuery.eq('supplier_id', uploadedSelectedSupplierId);
        const { data: existingRows, error: checkError } = await checkQuery
          .order('created_at', { ascending: false })
          .limit(400);
        if (checkError) throw checkError;

        const psIso = (summaryToSave as any)?.period_start ? new Date((summaryToSave as any).period_start).toISOString().slice(0, 10) : '';
        const peIso = (summaryToSave as any)?.period_end ? new Date((summaryToSave as any).period_end).toISOString().slice(0, 10) : '';

        const duplicate = (existingRows || []).find((x: any) => {
          const rn = String(x?.summary_json?.report_number || '').trim();
          const xps = x?.summary_json?.period_start ? new Date(x.summary_json.period_start).toISOString().slice(0, 10) : '';
          const xpe = x?.summary_json?.period_end ? new Date(x.summary_json.period_end).toISOString().slice(0, 10) : '';
          // Дедуп ТОЛЬКО по номеру отчёта: за один период бывает несколько разных отчётов
          // (маленький и большой) — оба должны сохраняться. По периоду сверяем лишь когда
          // номера нет ни у нового, ни у существующего.
          if (reportNumber) return rn === reportNumber;
          if (rn) return false;
          return !!psIso && !!peIso && xps === psIso && xpe === peIso;
        });

        if (duplicate?.id) duplicateId = String(duplicate.id);
      }

      const ps = (summaryToSave as any)?.period_start ? new Date((summaryToSave as any).period_start).toLocaleDateString('ru-RU') : '-';
      const pe = (summaryToSave as any)?.period_end ? new Date((summaryToSave as any).period_end).toLocaleDateString('ru-RU') : '-';
      const supplierName = supplier?.name || 'Без поставщика';
      const defaultHistoryName = `Период отчета: ${ps} - ${pe}, ${supplierName}`;

      const compactAnalyticsRow = (row: any) => {
        const sizeRows = Array.isArray(row?.size_breakdown_list) ? row.size_breakdown_list.slice(0, 20) : [];
        return {
          code: row?.code || '',
          name: row?.name || '',
          vendor_code: row?.vendor_code || '',
          ordered_qty: Number(row?.ordered_qty || 0),
          ordered_retail_sum: Number(row?.ordered_retail_sum || 0),
          sales_net: Number(row?.sales_net || 0),
          returns_gross: Number(row?.returns_gross || 0),
          logistics_sum: Number(row?.logistics_sum || 0),
          logistics_forward: Number(row?.logistics_forward || 0),
          logistics_logi: Number(row?.logistics_logi || 0),
          logistics_return: Number(row?.logistics_return || 0),
          payout_sum: Number(row?.payout_sum || 0),
          payout_net: Number(row?.payout_net || 0),
          fine_sum: Number(row?.fine_sum || 0),
          storage_sum: Number(row?.storage_sum || 0),
          withhold_sum: Number(row?.withhold_sum || 0),
          to_pay_total: Number(row?.to_pay_total || 0),
          sold_qty: Number(row?.sold_qty || 0),
          return_qty: Number(row?.return_qty || 0),
          acquiring_sum: Number(row?.acquiring_sum || 0),
          acquiring_percent: Number(row?.acquiring_percent || 0),
          tax_sum: Number(row?.tax_sum || 0),
          wb_commission_vat: Number(row?.wb_commission_vat || 0),
          wb_commission_net: Number(row?.wb_commission_net || 0),
          log_kinds: { ...(row?.log_kinds || {}) },
          size_breakdown: row?.size_breakdown || '',
          size_breakdown_list: sizeRows.map((sz: any) => ({
            size: sz?.size || '',
            sold_qty: Number(sz?.sold_qty || 0),
            return_qty: Number(sz?.return_qty || 0),
            sales_net: Number(sz?.sales_net || 0),
            returns_gross: Number(sz?.returns_gross || 0),
            logistics_sum: Number(sz?.logistics_sum || 0),
            payout_net: Number(sz?.payout_net || 0),
            fine_sum: Number(sz?.fine_sum || 0),
            storage_sum: Number(sz?.storage_sum || 0),
            withhold_sum: Number(sz?.withhold_sum || 0),
            to_pay_total: Number(sz?.to_pay_total || 0),
            acquiring_sum: Number(sz?.acquiring_sum || 0),
            log_kinds: { ...(sz?.log_kinds || {}) },
          })),
        };
      };
      const analyticsSafe = Array.isArray(analyticsToSave) ? analyticsToSave.slice(0, ANALYTICS_JSON_DB_LIMIT).map(compactAnalyticsRow) : [];
      const analyticsTruncated = Array.isArray(analyticsToSave) && analyticsToSave.length > analyticsSafe.length;
      // Компактный гео-снимок для восстановления «Сводки» из истории (топ-150 точек).
      const geoSrc = (summaryToSave as any)?.geo_snapshot || uploadedReportGeo || null;
      const compactGeoArr = (arr: any[]) => (Array.isArray(arr) ? arr : []).slice(0, 150).map((e: any) => ({
        key: e?.key, name: e?.name, sales_net: Number(e?.sales_net || 0), sold_qty: Number(e?.sold_qty || 0),
        return_qty: Number(e?.return_qty || 0), logistics_sum: Number(e?.logistics_sum || 0),
        buyout_pct: Number(e?.buyout_pct || 0), logistics_pct: Number(e?.logistics_pct || 0), share_pct: Number(e?.share_pct || 0),
      }));
      const geoSafe = geoSrc ? {
        byWarehouse: compactGeoArr(geoSrc.byWarehouse),
        byOffice: compactGeoArr(geoSrc.byOffice),
        byCountry: compactGeoArr(geoSrc.byCountry),
        dailyTotals: (Array.isArray(geoSrc.dailyTotals) ? geoSrc.dailyTotals : []).map((d: any) => ({ key: d?.key, sales_net: Number(d?.sales_net || 0), sold_qty: Number(d?.sold_qty || 0), ordered_qty: Number(d?.ordered_qty || 0), ordered_retail_sum: Number(d?.ordered_retail_sum || 0) })),
      } : null;
      // Чистая прибыль с НДС 22% (ОСНО) по текущей себестоимости — сохраняем, чтобы список/месяц
      // не пересчитывали построчно при каждом открытии.
      const vatCostSum = (Array.isArray(analyticsToSave) ? analyticsToSave : []).reduce((acc: number, x: any) => {
        const code = String(x?.code || '').trim();
        return acc + Number(uploadedPersistedCostByCode[code] || 0) * Number(x?.sold_qty || 0);
      }, 0);
      const profitTotalVat = reportProfitVat(summaryToSave, vatCostSum);
      const summarySafe = { ...(summaryToSave || {}), geo_snapshot: geoSafe, analytics_truncated: analyticsTruncated, analytics_rows_saved: analyticsSafe.length, analytics_rows_original: Array.isArray(analyticsToSave) ? analyticsToSave.length : 0, cost_sum: vatCostSum, profit_total_vat: profitTotalVat } as any;

      const payload = {
        supplier_id: supplierDbId,
        supplier_name: supplierName,
        file_name: defaultHistoryName,
        summary_json: summarySafe,
        analytics_json: analyticsSafe,
      };

      const payloadBytes = new TextEncoder().encode(JSON.stringify(payload)).length;
      if (payloadBytes > 7_000_000) {
        payload.analytics_json = [];
        payload.summary_json = { ...summarySafe, analytics_json_skipped: true, analytics_rows_saved: 0 };
        showToast('Агрегаты слишком большие для БД: сохранена только сводка и исходный файл', 'warning');
      }

      if (duplicateId) {
        const { error } = await supabase
          .from('analytics_upload_history')
          .update(payload)
          .eq('id', duplicateId);
        if (error) throw error;
        logAction('Аналитика: обновление отчёта', `${supplierName} · период ${ps}–${pe}${reportNumber ? ` · №${reportNumber}` : ''} · позиций ${analyticsSafe.length}`, currentEmployee?.id);
        showToast(`Отчёт №${reportNumber} обновлён`, 'success');
      } else {
        const { error } = await supabase.from('analytics_upload_history').insert(payload);
        if (error) throw error;
        logAction('Аналитика: загрузка отчёта', `${supplierName} · период ${ps}–${pe}${reportNumber ? ` · №${reportNumber}` : ''} · позиций ${analyticsSafe.length}`, currentEmployee?.id);
      }

      if (analyticsTruncated) {
        showToast(`Сохранена облегчённая версия: ${analyticsSafe.length.toLocaleString('ru-RU')} из ${analyticsToSave.length.toLocaleString('ru-RU')} строк аналитики`, 'warning');
      }

      loadUploadedReportHistory(uploadedSelectedSupplierId);
    } catch (e: any) {
      console.error('saveUploadedReportHistory error', e);
      showToast(`Не удалось сохранить отчёт в "Отчёты": ${e?.message || 'ошибка'}`, 'error');
    }
  };

  const normalizeNmId = (v: any) => String(v ?? '').replace(/\D+/g, '').replace(/^0+/, '');
  // Синтез WB-CDN URL фото по nmID (фолбэк, когда в БД фото нет).
  const wbBasketHost = (vol: number) => { const t = [143,287,431,719,1007,1061,1115,1169,1313,1601,1655,1919,2045,2189,2405,2621,2837,3053,3269,3485,3701,3917,4133,4349,4565,4877,5189,5501,5813,6125,6437,6749,7061,7373,7685,7997,8309,8621,9244,9620,10380,11132,11900,12650,13400,14150,14900]; let i = 0; while (i < t.length && vol > t[i]) i++; return `basket-${String(i + 1).padStart(2, '0')}.wbbasket.ru`; };
  const wbSynthPhotos = (code: string) => {
    const n = Number(normalizeNmId(code)); if (!n) return [] as string[];
    const vol = Math.floor(n / 100000), part = Math.floor(n / 1000);
    const base = `https://${wbBasketHost(vol)}/vol${vol}/part${part}/${n}/images/c246x328/1`;
    return [`${base}.webp`, `${base}.jpg`];
  };
  const getUploadedPhotoCandidates = (code: string) => {
    const raw = String(code || '').trim();
    const norm = normalizeNmId(raw);
    const candidates: string[] = [];

    if (uploadedPhotoMap[raw]) candidates.push(uploadedPhotoMap[raw]);
    if (norm && uploadedPhotoMap[norm]) candidates.push(uploadedPhotoMap[norm]);
    // Фолбэк: прямые ссылки на WB-CDN (если из БД фото не нашлось/не открылось).
    candidates.push(...wbSynthPhotos(raw));

    const failed = uploadedFailedPhotoUrlsRef.current;
    return Array.from(new Set(candidates.filter(Boolean))).filter((u) => !failed.has(String(u)));
  };
  const getUploadedPhoto = (code: string) => getUploadedPhotoCandidates(code)[0] || '';

  const enrichUploadedPhotosByApi = async (sourceAnalytics?: any[]) => {
    const analyticsSource = Array.isArray(sourceAnalytics) ? sourceAnalytics : uploadedReportAnalytics;
    if (!analyticsSource.length) {
      showToast('Сначала загрузите отчет', 'error');
      return;
    }
    if (analyticsSource.length > 2000) {
      showToast('Для большого отчёта автообновление фото отключено (чтобы не перегружать систему)', 'info');
      return;
    }

    try {
      const normalized = (v: any) => String(v ?? '').replace(/\D+/g, '').replace(/^0+/, '');
      const allCovered = (analyticsSource || []).every((r: any) => {
        const raw = String(r?.code || '').trim();
        const norm = normalized(raw);
        return !!((uploadedPhotoMap || {})[raw] || (norm && (uploadedPhotoMap || {})[norm]));
      });
      if (allCovered) {
        showToast('Фото уже загружены, автообновление пропущено', 'info');
        return;
      }

      setUploadedPhotoLoading(true);
      uploadedFailedPhotoUrlsRef.current.clear();
      const nextMap: Record<string, string> = { ...(uploadedPhotoMap || {}) };

      // 1) try supplier cache first
      if (uploadedSelectedSupplierId) {
        const { data: cacheRows, error: cacheErr } = await fetchAllPages((__a, __b) => supabase
          .from('wb_products_cache')
          .select('product_json')
          .eq('supplier_id', uploadedSelectedSupplierId)
          .order('nm_id').range(__a, __b));
        if (!cacheErr) {
          (cacheRows || []).forEach((row: any) => {
            const p = row?.product_json || {};
            const nm = normalizeNmId(p?.nmID || p?.nm_id || 0);
            const vendorCode = String(p?.vendorCode || p?.supplierArticle || p?.article || '').trim();
            const first = (Array.isArray(p?.photos) && p.photos[0]) || (Array.isArray(p?.mediaFiles) && p.mediaFiles[0]) || '';
            let src = typeof first === 'string' ? first : (first?.big || first?.c246x328 || first?.tm || '');
            src = String(src || '').trim();
            if (src && src.startsWith('//')) src = `https:${src}`;
            if (/^https?:\/\//i.test(src)) {
              if (nm) nextMap[String(nm)] = src;
              if (vendorCode) nextMap[vendorCode] = src;
            }
          });
        }
      }

      // 2) public WB card API for missing
      const missing = analyticsSource
        .map((r: any) => {
          const raw = String(r.code || '').trim();
          const norm = normalizeNmId(raw);
          return norm || raw;
        })
        .filter((c: string) => c && c !== '0' && !nextMap[c])
        .slice(0, 200);

      // Strict DB-only photo mode: do not synthesize external WB image URLs.
      if (missing.length) {
        console.info('DB-only photo mode, no external fallback for codes:', missing.slice(0, 10));
      }

      setUploadedPhotoMap(nextMap);
      showToast('Фото обновлены из базы', 'success');
    } catch (e: any) {
      showToast(e?.message || 'Ошибка загрузки фото', 'error');
    } finally {
      setUploadedPhotoLoading(false);
    }
  };

